INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-barbarian', 'class', 'Barbarian', 'class-barbarian', '{"index":"barbarian","name":"Barbarian","hit_die":12,"proficiency_choices":[{"desc":"Choose two from Animal Handling, Athletics, Intimidation, Nature, Perception, and Survival","choose":2,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-survival","name":"Skill: Survival","url":"/api/2014/proficiencies/skill-survival"}}]}}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/proficiencies/martial-weapons"},{"index":"saving-throw-str","name":"Saving Throw: STR","url":"/api/2014/proficiencies/saving-throw-str"},{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}],"saving_throws":[{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"}],"starting_equipment":[{"equipment":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"},"quantity":1},{"equipment":{"index":"javelin","name":"Javelin","url":"/api/2014/equipment/javelin"},"quantity":4}],"starting_equipment_options":[{"desc":"(a) a greataxe or (b) any martial melee weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"greataxe","name":"Greataxe","url":"/api/2014/equipment/greataxe"}},{"option_type":"choice","choice":{"desc":"any martial melee weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"martial-melee-weapons","name":"Martial Melee Weapons","url":"/api/2014/equipment-categories/martial-melee-weapons"}}}}]}},{"desc":"(a) two handaxes or (b) any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":2,"of":{"index":"handaxe","name":"Handaxe","url":"/api/2014/equipment/handaxe"}},{"option_type":"choice","choice":{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}}]}}],"class_levels":"/api/2014/classes/barbarian/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"minimum_score":13}],"proficiencies":[{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/proficiencies/martial-weapons"}]},"subclasses":[{"index":"berserker","name":"Berserker","url":"/api/2014/subclasses/berserker"}],"url":"/api/2014/classes/barbarian","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-bard', 'class', 'Bard', 'class-bard', '{"index":"bard","name":"Bard","hit_die":8,"proficiency_choices":[{"desc":"Choose any three","choose":3,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-acrobatics","name":"Skill: Acrobatics","url":"/api/2014/proficiencies/skill-acrobatics"}},{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"option_type":"reference","item":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-performance","name":"Skill: Performance","url":"/api/2014/proficiencies/skill-performance"}},{"option_type":"reference","item":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}},{"option_type":"reference","item":{"index":"skill-sleight-of-hand","name":"Skill: Sleight of Hand","url":"/api/2014/proficiencies/skill-sleight-of-hand"}},{"option_type":"reference","item":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}},{"option_type":"reference","item":{"index":"skill-survival","name":"Skill: Survival","url":"/api/2014/proficiencies/skill-survival"}}]}},{"desc":"Three musical instruments of your choice","choose":3,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"bagpipes","name":"Bagpipes","url":"/api/2014/proficiencies/bagpipes"}},{"option_type":"reference","item":{"index":"drum","name":"Drum","url":"/api/2014/proficiencies/drum"}},{"option_type":"reference","item":{"index":"dulcimer","name":"Dulcimer","url":"/api/2014/proficiencies/dulcimer"}},{"option_type":"reference","item":{"index":"flute","name":"Flute","url":"/api/2014/proficiencies/flute"}},{"option_type":"reference","item":{"index":"lute","name":"Lute","url":"/api/2014/proficiencies/lute"}},{"option_type":"reference","item":{"index":"lyre","name":"Lyre","url":"/api/2014/proficiencies/lyre"}},{"option_type":"reference","item":{"index":"horn","name":"Horn","url":"/api/2014/proficiencies/horn"}},{"option_type":"reference","item":{"index":"pan-flute","name":"Pan flute","url":"/api/2014/proficiencies/pan-flute"}},{"option_type":"reference","item":{"index":"shawm","name":"Shawm","url":"/api/2014/proficiencies/shawm"}},{"option_type":"reference","item":{"index":"viol","name":"Viol","url":"/api/2014/proficiencies/viol"}}]}}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"longswords","name":"Longswords","url":"/api/2014/proficiencies/longswords"},{"index":"rapiers","name":"Rapiers","url":"/api/2014/proficiencies/rapiers"},{"index":"shortswords","name":"Shortswords","url":"/api/2014/proficiencies/shortswords"},{"index":"hand-crossbows","name":"Hand crossbows","url":"/api/2014/proficiencies/hand-crossbows"},{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"},{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}],"saving_throws":[{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"}],"starting_equipment":[{"equipment":{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"},"quantity":1},{"equipment":{"index":"dagger","name":"Dagger","url":"/api/2014/equipment/dagger"},"quantity":1}],"starting_equipment_options":[{"desc":"(a) a rapier, (b) a longsword, or (c) any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"rapier","name":"Rapier","url":"/api/2014/equipment/rapier"}},{"option_type":"counted_reference","count":1,"of":{"index":"longsword","name":"Longsword","url":"/api/2014/equipment/longsword"}},{"option_type":"choice","choice":{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}}]}},{"desc":"(a) a diplomat’s pack or (b) an entertainer’s pack","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"diplomats-pack","name":"Diplomat''s Pack","url":"/api/2014/equipment/diplomats-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"entertainers-pack","name":"Entertainer''s Pack","url":"/api/2014/equipment/entertainers-pack"}}]}},{"desc":"(a) a lute or (b) any other musical instrument","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"lute","name":"Lute","url":"/api/2014/equipment/lute"}},{"option_type":"choice","choice":{"desc":"any other musical instrument","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"musical-instruments","name":"Musical Instruments","url":"/api/2014/equipment-categories/musical-instruments"}}}}]}}],"class_levels":"/api/2014/classes/bard/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"minimum_score":13}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"}],"proficiency_choices":[{"desc":"skill","choose":1,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-acrobatics","name":"Skill: Acrobatics","url":"/api/2014/proficiencies/skill-acrobatics"}},{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"option_type":"reference","item":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-performance","name":"Skill: Performance","url":"/api/2014/proficiencies/skill-performance"}},{"option_type":"reference","item":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}},{"option_type":"reference","item":{"index":"skill-sleight-of-hand","name":"Skill: Sleight of Hand","url":"/api/2014/proficiencies/skill-sleight-of-hand"}},{"option_type":"reference","item":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}},{"option_type":"reference","item":{"index":"skill-survival","name":"Skill: Survival","url":"/api/2014/proficiencies/skill-survival"}}]}},{"desc":"musical instrument","choose":1,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"bagpipes","name":"Bagpipes","url":"/api/2014/proficiencies/bagpipes"}},{"option_type":"reference","item":{"index":"drum","name":"Drum","url":"/api/2014/proficiencies/drum"}},{"option_type":"reference","item":{"index":"dulcimer","name":"Dulcimer","url":"/api/2014/proficiencies/dulcimer"}},{"option_type":"reference","item":{"index":"flute","name":"Flute","url":"/api/2014/proficiencies/flute"}},{"option_type":"reference","item":{"index":"lute","name":"Lute","url":"/api/2014/proficiencies/lute"}},{"option_type":"reference","item":{"index":"lyre","name":"Lyre","url":"/api/2014/proficiencies/lyre"}},{"option_type":"reference","item":{"index":"horn","name":"Horn","url":"/api/2014/proficiencies/horn"}},{"option_type":"reference","item":{"index":"pan-flute","name":"Pan flute","url":"/api/2014/proficiencies/pan-flute"}},{"option_type":"reference","item":{"index":"shawm","name":"Shawm","url":"/api/2014/proficiencies/shawm"}},{"option_type":"reference","item":{"index":"viol","name":"Viol","url":"/api/2014/proficiencies/viol"}}]}}]},"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"spellcasting":{"level":1,"spellcasting_ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"info":[{"name":"Cantrips","desc":["You know two cantrips of your choice from the bard spell list. You learn additional bard cantrips of your choice at higher levels, as shown in the Cantrips Known column of the Bard table."]},{"name":"Spell Slots","desc":["The Bard table shows how many spell slots you have to cast your spells of 1st level and higher. To cast one of these spells, you must expend a slot of the spell''s level or higher. You regain all expended spell slots when you finish a long rest.","For example, if you know the 1st-level spell cure wounds and have a 1st-level and a 2nd-level spell slot available, you can cast cure wounds using either slot."]},{"name":"Spells Known of 1st Level and Higher","desc":["You know four 1st-level spells of your choice from the bard spell list.","The Spells Known column of the Bard table shows when you learn more bard spells of your choice.","Each of these spells must be of a level for which you have spell slots, as shown on the table. For instance, when you reach 3rd level in this class, you can learn one new spell of 1st or 2nd level.","Additionally, when you gain a level in this class, you can choose one of the bard spells you know and replace it with another spell from the bard spell list, which also must be of a level for which you have spell slots."]},{"name":"Spellcasting Ability","desc":["Charisma is your spellcasting ability for your bard spells. Your magic comes from the heart and soul you pour into the performance of your music or oration. You use your Charisma whenever a spell refers to your spellcasting ability. In addition, you use your Charisma modifier when setting the saving throw DC for a bard spell you cast and when making an attack roll with one.","Spell save DC = 8 + your proficiency bonus + your Charisma modifier.","Spell attack modifier = your proficiency bonus + your Charisma modifier."]},{"name":"Ritual Casting","desc":["You can cast any bard spell you know as a ritual if that spell has the ritual tag."]},{"name":"Spellcasting Focus","desc":["You can use a musical instrument (see Equipment) as a spellcasting focus for your bard spells."]}]},"spells":"/api/2014/classes/bard/spells","url":"/api/2014/classes/bard","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-cleric', 'class', 'Cleric', 'class-cleric', '{"index":"cleric","name":"Cleric","hit_die":8,"proficiency_choices":[{"desc":"Choose two from History, Insight, Medicine, Persuasion, and Religion","choose":2,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"option_type":"reference","item":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}]}}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"},{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}],"saving_throws":[{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"}],"starting_equipment":[{"equipment":{"index":"shield","name":"Shield","url":"/api/2014/equipment/shield"},"quantity":1}],"starting_equipment_options":[{"desc":"(a) a mace or (b) a warhammer (if proficient)","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"mace","name":"Mace","url":"/api/2014/equipment/mace"}},{"option_type":"counted_reference","count":1,"of":{"index":"warhammer","name":"Warhammer","url":"/api/2014/equipment/warhammer"},"prerequisites":[{"type":"proficiency","proficiency":{"index":"warhammers","name":"Warhammers","url":"/api/2014/proficiencies/warhammers"}}]}]}},{"desc":"(a) scale mail, (b) leather armor, or (c) chain mail (if proficient)","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"scale-mail","name":"Scale Mail","url":"/api/2014/equipment/scale-mail"}},{"option_type":"counted_reference","count":1,"of":{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"}},{"option_type":"counted_reference","count":1,"of":{"index":"chain-mail","name":"Chain Mail","url":"/api/2014/equipment/chain-mail"},"prerequisites":[{"type":"proficiency","proficiency":{"index":"chain-mail","name":"Chain Mail","url":"/api/2014/proficiencies/chain-mail"}}]}]}},{"desc":"(a) a light crossbow and 20 bolts or (b) any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"counted_reference","count":1,"of":{"index":"crossbow-light","name":"Crossbow, light","url":"/api/2014/equipment/crossbow-light"}},{"option_type":"counted_reference","count":20,"of":{"index":"crossbow-bolt","name":"Crossbow bolt","url":"/api/2014/equipment/crossbow-bolt"}}]},{"option_type":"choice","choice":{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}}]}},{"desc":"(a) a priest’s pack or (b) an explorer’s pack","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"priests-pack","name":"Priest''s Pack","url":"/api/2014/equipment/priests-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"}}]}},{"desc":"holy symbol","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"holy-symbols","name":"Holy Symbols","url":"/api/2014/equipment-categories/holy-symbols"}}}],"class_levels":"/api/2014/classes/cleric/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"minimum_score":13}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"}]},"subclasses":[{"index":"life","name":"Life","url":"/api/2014/subclasses/life"}],"spellcasting":{"level":1,"spellcasting_ability":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"info":[{"name":"Cantrips","desc":["At 1st level, you know three cantrips of your choice from the cleric spell list. You learn additional cleric cantrips of your choice at higher levels, as shown in the Cantrips Known column of the Cleric table."]},{"name":"Preparing and Casting Spells","desc":["The Cleric table shows how many spell slots you have to cast your spells of 1st level and higher. To cast one of these spells, you must expend a slot of the spell''s level or higher. You regain all expended spell slots when you finish a long rest.","You prepare the list of cleric spells that are available for you to cast, choosing from the cleric spell list. When you do so, choose a number of cleric spells equal to your Wisdom modifier + your cleric level (minimum of one spell). The spells must be of a level for which you have spell slots.","For example, if you are a 3rd-level cleric, you have four 1st-level and two 2nd-level spell slots. With a Wisdom of 16, your list of prepared spells can include six spells of 1st or 2nd level, in any combination. If you prepare the 1st-level spell cure wounds, you can cast it using a 1st-level or 2nd-level slot. Casting the spell doesn''t remove it from your list of prepared spells.","You can change your list of prepared spells when you finish a long rest. Preparing a new list of cleric spells requires time spent in prayer and meditation: at least 1 minute per spell level for each spell on your list."]},{"name":"Spellcasting Ability","desc":["Wisdom is your spellcasting ability for your cleric spells. The power of your spells comes from your devotion to your deity. You use your Wisdom whenever a cleric spell refers to your spellcasting ability. In addition, you use your Wisdom modifier when setting the saving throw DC for a cleric spell you cast and when making an attack roll with one.","Spell save DC = 8 + your proficiency bonus + your Wisdom modifier","Spell attack modifier = your proficiency bonus + your Wisdom modifier"]},{"name":"Ritual Casting","desc":["You can cast a cleric spell as a ritual if that spell has the ritual tag and you have the spell prepared."]},{"name":"Spellcasting Focus","desc":["You can use a holy symbol (see Equipment) as a spellcasting focus for your cleric spells."]}]},"spells":"/api/2014/classes/cleric/spells","url":"/api/2014/classes/cleric","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-druid', 'class', 'Druid', 'class-druid', '{"index":"druid","name":"Druid","hit_die":8,"proficiency_choices":[{"desc":"Choose two from Arcana, Animal Handling, Insight, Medicine, Nature, Perception, Religion, and Survival","choose":2,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}},{"option_type":"reference","item":{"index":"skill-survival","name":"Skill: Survival","url":"/api/2014/proficiencies/skill-survival"}}]}}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"clubs","name":"Clubs","url":"/api/2014/proficiencies/clubs"},{"index":"daggers","name":"Daggers","url":"/api/2014/proficiencies/daggers"},{"index":"javelins","name":"Javelins","url":"/api/2014/proficiencies/javelins"},{"index":"maces","name":"Maces","url":"/api/2014/proficiencies/maces"},{"index":"quarterstaffs","name":"Quarterstaffs","url":"/api/2014/proficiencies/quarterstaffs"},{"index":"sickles","name":"Sickles","url":"/api/2014/proficiencies/sickles"},{"index":"spears","name":"Spears","url":"/api/2014/proficiencies/spears"},{"index":"darts","name":"Darts","url":"/api/2014/proficiencies/darts"},{"index":"slings","name":"Slings","url":"/api/2014/proficiencies/slings"},{"index":"scimitars","name":"Scimitars","url":"/api/2014/proficiencies/scimitars"},{"index":"herbalism-kit","name":"Herbalism Kit","url":"/api/2014/proficiencies/herbalism-kit"},{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"},{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}],"saving_throws":[{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"}],"starting_equipment":[{"equipment":{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"},"quantity":1},{"equipment":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"},"quantity":1}],"starting_equipment_options":[{"desc":"(a) a wooden shield or (b) any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"shield","name":"Shield","url":"/api/2014/equipment/shield"}},{"option_type":"choice","choice":{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}}]}},{"desc":"(a) a scimitar or (b) any simple melee weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"scimitar","name":"Scimitar","url":"/api/2014/equipment/scimitar"}},{"option_type":"choice","choice":{"desc":"any simple melee weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-melee-weapons","name":"Simple Melee Weapons","url":"/api/2014/equipment-categories/simple-melee-weapons"}}}}]}},{"desc":"druidic focus","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"druidic-foci","name":"Druidic Foci","url":"/api/2014/equipment-categories/druidic-foci"}}}],"class_levels":"/api/2014/classes/druid/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"minimum_score":13}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"}]},"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"spellcasting":{"level":1,"spellcasting_ability":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"info":[{"name":"Cantrips","desc":["At 1st level, you know two cantrips of your choice from the druid spell list. You learn additional druid cantrips of your choice at higher levels, as shown in the Cantrips Known column of the Druid table."]},{"name":"Preparing and Casting Spells","desc":["The Druid table shows how many spell slots you have to cast your spells of 1st level and higher. To cast one of these druid spells, you must expend a slot of the spell''s level or higher. You regain all expended spell slots when you finish a long rest.","You prepare the list of druid spells that are available for you to cast, choosing from the druid spell list. When you do so, choose a number of druid spells equal to your Wisdom modifier + your druid level (minimum of one spell). The spells must be of a level for which you have spell slots.","For example, if you are a 3rd-level druid, you have four 1st-level and two 2nd-level spell slots. With a Wisdom of 16, your list of prepared spells can include six spells of 1st or 2nd level, in any combination. If you prepare the 1st-level spell cure wounds, you can cast it using a 1st-level or 2nd-level slot. Casting the spell doesn''t remove it from your list of prepared spells.","You can also change your list of prepared spells when you finish a long rest. Preparing a new list of druid spells requires time spent in prayer and meditation: at least 1 minute per spell level for each spell on your list."]},{"name":"Spellcasting Ability","desc":["Wisdom is your spellcasting ability for your druid spells, since your magic draws upon your devotion and attunement to nature. You use your Wisdom whenever a spell refers to your spellcasting ability. In addition, you use your Wisdom modifier when setting the saving throw DC for a druid spell you cast and when making an attack roll with one.","Spell save DC = 8 + your proficiency bonus + your Wisdom modifier.","Spell attack modifier = your proficiency bonus + your Wisdom modifier."]},{"name":"Ritual Casting","desc":["You can cast a druid spell as a ritual if that spell has the ritual tag and you have the spell prepared."]},{"name":"Spellcasting Focus","desc":["You can use a druidic focus (see chapter 5, \"Equipment\") as a spellcasting focus for your druid spells."]}]},"spells":"/api/2014/classes/druid/spells","url":"/api/2014/classes/druid","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
