INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-paladin', 'class', 'Paladin', 'class-paladin', '{"index":"paladin","name":"Paladin","hit_die":10,"proficiency_choices":[{"desc":"Choose two from Athletics, Insight, Intimidation, Medicine, Persuasion, and Religion","choose":2,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"option_type":"reference","item":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}]}}],"proficiencies":[{"index":"all-armor","name":"All armor","url":"/api/2014/proficiencies/all-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/proficiencies/martial-weapons"},{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"},{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}],"saving_throws":[{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"}],"starting_equipment":[{"equipment":{"index":"chain-mail","name":"Chain Mail","url":"/api/2014/equipment/chain-mail"},"quantity":1}],"starting_equipment_options":[{"desc":"(a) a martial weapon and a shield or (b) two martial weapons","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"choice","choice":{"desc":"a martial weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"name":"Martial Weapons","index":"martial-weapons","url":"/api/2014/equipment-categories/martial-weapons"}}}},{"option_type":"counted_reference","count":1,"of":{"index":"shield","name":"Shield","url":"/api/2014/equipment/shield"}}]},{"option_type":"choice","choice":{"desc":"two martial weapons","choose":2,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/equipment-categories/martial-weapons"}}}}]}},{"desc":"(a) five javelins or (b) any simple melee weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":5,"of":{"index":"javelin","name":"Javelin","url":"/api/2014/equipment/javelin"}},{"option_type":"choice","choice":{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}}]}},{"desc":"(a) a priest’s pack or (b) an explorer’s pack","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"priests-pack","name":"Priest''s Pack","url":"/api/2014/equipment/priests-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"}}]}},{"desc":"holy symbol","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"holy-symbols","name":"Holy Symbols","url":"/api/2014/equipment-categories/holy-symbols"}}}],"class_levels":"/api/2014/classes/paladin/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"minimum_score":13},{"ability_score":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"minimum_score":13}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/proficiencies/martial-weapons"}]},"subclasses":[{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"spellcasting":{"level":2,"spellcasting_ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"info":[{"name":"Preparing and Casting Spells","desc":["The Paladin table shows how many spell slots you have to cast your spells. To cast one of your paladin spells of 1st level or higher, you must expend a slot of the spell''s level or higher. You regain all expended spell slots when you finish a long rest.","You prepare the list of paladin spells that are available for you to cast, choosing from the paladin spell list. When you do so, choose a number of paladin spells equal to your Charisma modifier + half your paladin level, rounded down (minimum of one spell). The spells must be of a level for which you have spell slots.","For example, if you are a 5th-level paladin, you have four 1st-level and two 2nd-level spell slots. With a Charisma of 14, your list of prepared spells can include four spells of 1st or 2nd level, in any combination. If you prepare the 1st-level spell cure wounds, you can cast it using a 1st-level or a 2nd- level slot. Casting the spell doesn''t remove it from your list of prepared spells.","You can change your list of prepared spells when you finish a long rest. Preparing a new list of paladin spells requires time spent in prayer and meditation: at least 1 minute per spell level for each spell on your list."]},{"name":"Spellcasting Ability","desc":["Charisma is your spellcasting ability for your paladin spells, since their power derives from the strength of your convictions. You use your Charisma whenever a spell refers to your spellcasting ability. In addition, you use your Charisma modifier when setting the saving throw DC for a paladin spell you cast and when making an attack roll with one.","Spell save DC = 8 + your proficiency bonus + your Charisma modifier.","Spell attack modifier = your proficiency bonus + your Charisma modifier."]},{"name":"Spellcasting Focus","desc":["You can use a holy symbol as a spellcasting focus for your paladin spells."]}]},"spells":"/api/2014/classes/paladin/spells","url":"/api/2014/classes/paladin","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-ranger', 'class', 'Ranger', 'class-ranger', '{"index":"ranger","name":"Ranger","hit_die":10,"proficiency_choices":[{"desc":"Choose three from Animal Handling, Athletics, Insight, Investigation, Nature, Perception, Stealth, and Survival","choose":3,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}},{"option_type":"reference","item":{"index":"skill-survival","name":"Skill: Survival","url":"/api/2014/proficiencies/skill-survival"}}]}}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/proficiencies/martial-weapons"},{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"},{"index":"saving-throw-str","name":"Saving Throw: STR","url":"/api/2014/proficiencies/saving-throw-str"}],"saving_throws":[{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"}],"starting_equipment":[{"equipment":{"index":"longbow","name":"Longbow","url":"/api/2014/equipment/longbow"},"quantity":1},{"equipment":{"index":"arrow","name":"Arrow","url":"/api/2014/equipment/arrow"},"quantity":20}],"starting_equipment_options":[{"desc":"(a) scale mail or (b) leather armor","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"scale-mail","name":"Scale Mail","url":"/api/2014/equipment/scale-mail"}},{"option_type":"counted_reference","count":1,"of":{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"}}]}},{"desc":"(a) two shortswords or (b) two simple melee weapons","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":2,"of":{"index":"shortsword","name":"Shortsword","url":"/api/2014/equipment/shortsword"}},{"option_type":"choice","choice":{"desc":"two simple melee weapons","choose":2,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-melee-weapons","name":"Simple Melee Weapons","url":"/api/2014/equipment-categories/simple-melee-weapons"}}}}]}},{"desc":"(a) a dungeoneer’s pack or (b) an explorer’s pack","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"dungeoneers-pack","name":"Dungeoneer''s Pack","url":"/api/2014/equipment/dungeoneers-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"}}]}}],"class_levels":"/api/2014/classes/ranger/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"minimum_score":13},{"ability_score":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"minimum_score":13}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/proficiencies/martial-weapons"}],"proficiency_choices":[{"choose":1,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}},{"option_type":"reference","item":{"index":"skill-survival","name":"Skill: Survival","url":"/api/2014/proficiencies/skill-survival"}}]}}]},"subclasses":[{"index":"hunter","name":"Hunter","url":"/api/2014/subclasses/hunter"}],"spellcasting":{"level":2,"spellcasting_ability":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"info":[{"name":"Spell Slots","desc":["The Ranger table shows how many spell slots you have to cast your spells of 1st level and higher. To cast one of these spells, you must expend a slot of the spell''s level or higher. You regain all expended spell slots when you finish a long rest.","For example, if you know the 1st-level spell animal friendship and have a 1st-level and a 2nd-level spell slot available, you can cast animal friendship using either slot."]},{"name":"Spells Known of 1st Level and Higher","desc":["You know two 1st-level spells of your choice from the ranger spell list.","The Spells Known column of the Ranger table shows when you learn more ranger spells of your choice. Each of these spells must be of a level for which you have spell slots. For instance, when you reach 5th level in this class, you can learn one new spell of 1st or 2nd level.","Additionally, when you gain a level in this class, you can choose one of the ranger spells you know and replace it with another spell from the ranger spell list, which also must be of a level for which you have spell slots."]},{"name":"Spellcasting Ability","desc":["Wisdom is your spellcasting ability for your ranger spells, since your magic draws on your attunement to nature. You use your Wisdom whenever a spell refers to your spellcasting ability. In addition, you use your Wisdom modifier when setting the saving throw DC for a ranger spell you cast and when making an attack roll with one.","Spell save DC = 8 + your proficiency bonus + your Wisdom modifier.","Spell attack modifier = your proficiency bonus + your Wisdom modifier."]}]},"spells":"/api/2014/classes/ranger/spells","url":"/api/2014/classes/ranger","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
