ce","count":1,"of":{"index":"shortbow","name":"Shortbow","url":"/api/2014/equipment/shortbow"}},{"option_type":"counted_reference","count":20,"of":{"index":"arrow","name":"Arrow","url":"/api/2014/equipment/arrow"}}]},{"option_type":"counted_reference","count":1,"of":{"index":"shortsword","name":"Shortsword","url":"/api/2014/equipment/shortsword"}}]}},{"desc":"(a) a burglar’s pack, (b) a dungeoneer’s pack, or (c) an explorer’s pack","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"burglars-pack","name":"Burglar''s Pack","url":"/api/2014/equipment/burglars-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"dungeoneers-pack","name":"Dungeoneer''s Pack","url":"/api/2014/equipment/dungeoneers-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"}}]}}],"class_levels":"/api/2014/classes/rogue/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"minimum_score":13}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"thieves-tools","name":"Thieves'' Tools","url":"/api/2014/proficiencies/thieves-tools"}],"proficiency_choices":[{"choose":1,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-acrobatics","name":"Skill: Acrobatics","url":"/api/2014/proficiencies/skill-acrobatics"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-performance","name":"Skill: Performance","url":"/api/2014/proficiencies/skill-performance"}},{"option_type":"reference","item":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"option_type":"reference","item":{"index":"skill-sleight-of-hand","name":"Skill: Sleight of Hand","url":"/api/2014/proficiencies/skill-sleight-of-hand"}},{"option_type":"reference","item":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}]}}]},"subclasses":[{"index":"thief","name":"Thief","url":"/api/2014/subclasses/thief"}],"url":"/api/2014/classes/rogue","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-sorcerer', 'class', 'Sorcerer', 'class-sorcerer', '{"index":"sorcerer","name":"Sorcerer","hit_die":6,"proficiency_choices":[{"desc":"Choose two from Arcana, Deception, Insight, Intimidation, Persuasion, and Religion","choose":2,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}]}}],"proficiencies":[{"index":"daggers","name":"Daggers","url":"/api/2014/proficiencies/daggers"},{"index":"darts","name":"Darts","url":"/api/2014/proficiencies/darts"},{"index":"slings","name":"Slings","url":"/api/2014/proficiencies/slings"},{"index":"quarterstaffs","name":"Quarterstaffs","url":"/api/2014/proficiencies/quarterstaffs"},{"index":"crossbows-light","name":"Crossbows, light","url":"/api/2014/proficiencies/crossbows-light"},{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"},{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}],"saving_throws":[{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"}],"starting_equipment":[{"equipment":{"index":"dagger","name":"Dagger","url":"/api/2014/equipment/dagger"},"quantity":2}],"starting_equipment_options":[{"desc":"(a) a light crossbow and 20 bolts or (b) any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"counted_reference","count":1,"of":{"index":"crossbow-light","name":"Crossbow, light","url":"/api/2014/equipment/crossbow-light"}},{"option_type":"counted_reference","count":20,"of":{"index":"crossbow-bolt","name":"Crossbow bolt","url":"/api/2014/equipment/crossbow-bolt"}}]},{"option_type":"choice","choice":{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}}]}},{"desc":"(a) a component pouch or (b) an arcane focus","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"component-pouch","name":"Component pouch","url":"/api/2014/equipment/component-pouch"}},{"option_type":"choice","choice":{"desc":"arcane focus","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"arcane-foci","name":"Arcane Foci","url":"/api/2014/equipment-categories/arcane-foci"}}}}]}},{"desc":"(a) a dungeoneer’s pack or (b) an explorer’s pack","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"dungeoneers-pack","name":"Dungeoneer''s Pack","url":"/api/2014/equipment/dungeoneers-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"}}]}}],"class_levels":"/api/2014/classes/sorcerer/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"minimum_score":13}],"proficiencies":[]},"subclasses":[{"index":"draconic","name":"Draconic","url":"/api/2014/subclasses/draconic"}],"spellcasting":{"level":1,"spellcasting_ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"info":[{"name":"Cantrips","desc":["At 1st level, you know four cantrips of your choice from the sorcerer spell list. You learn additional sorcerer cantrips of your choice at higher levels, as shown in the Cantrips Known column of the Sorcerer table."]},{"name":"Spell Slots","desc":["The Sorcerer table shows how many spell slots you have to cast your spells of 1st level and higher. To cast one of these sorcerer spells, you must expend a slot of the spell''s level or higher. You regain all expended spell slots when you finish a long rest.","For example, if you know the 1st-level spell burning hands and have a 1st-level and a 2nd-level spell slot available, you can cast burning hands using either slot."]},{"name":"Spells Known of 1st Level and Higher","desc":["You know two 1st-level spells of your choice from the sorcerer spell list.","The Spells Known column of the Sorcerer table shows when you learn more sorcerer spells of your choice. Each of these spells must be of a level for which you have spell slots. For instance, when you reach 3rd level in this class, you can learn one new spell of 1st or 2nd level. ","Additionally, when you gain a level in this class, you can choose one of the sorcerer spells you know and replace it with another spell from the sorcerer spell list, which also must be of a level for which you have spell slots."]},{"name":"Spellcasting Ability","desc":["Charisma is your spellcasting ability for your sorcerer spells, since the power of your magic relies on your ability to project your will into the world. You use your Charisma whenever a spell refers to your spellcasting ability. In addition, you use your Charisma modifier when setting the saving throw DC for a sorcerer spell you cast and when making an attack roll with one.","Spell save DC = 8 + your proficiency bonus + your Charisma modifier.","Spell attack modifier = your proficiency bonus + your Charisma modifier."]},{"name":"Spellcasting Focus","desc":["You can use an arcane focus as a spellcasting focus for your sorcerer spells."]}]},"spells":"/api/2014/classes/sorcerer/spells","url":"/api/2014/classes/sorcerer","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-warlock', 'class', 'Warlock', 'class-warlock', '{"index":"warlock","name":"Warlock","hit_die":8,"proficiency_choices":[{"desc":"Choose two skills from Arcana, Deception, History, Intimidation, Investigation, Nature, and Religion","choose":2,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"option_type":"reference","item":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}]}}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"},{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}],"saving_throws":[{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"}],"starting_equipment":[{"equipment":{"index":"dagger","name":"Dagger","url":"/api/2014/equipment/dagger"},"quantity":2},{"equipment":{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"},"quantity":1}],"starting_equipment_options":[{"desc":"(a) a light crossbow and 20 bolts or (b) any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"counted_reference","count":1,"of":{"index":"crossbow-light","name":"Crossbow, light","url":"/api/2014/equipment/crossbow-light"}},{"option_type":"counted_reference","count":20,"of":{"index":"crossbow-bolt","name":"Crossbow bolt","url":"/api/2014/equipment/crossbow-bolt"}}]},{"option_type":"choice","choice":{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}}]}},{"desc":"(a) a component pouch or (b) an arcane focus","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"component-pouch","name":"Component pouch","url":"/api/2014/equipment/component-pouch"}},{"option_type":"choice","choice":{"desc":"arcane focus","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"arcane-foci","name":"Arcane Foci","url":"/api/2014/equipment-categories/arcane-foci"}}}}]}},{"desc":"(a) a scholar’s pack or (b) a dungeoneer’s pack","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"scholars-pack","name":"Scholar''s Pack","url":"/api/2014/equipment/scholars-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"dungeoneers-pack","name":"Dungeoneer''s Pack","url":"/api/2014/equipment/dungeoneers-pack"}}]}},{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}],"class_levels":"/api/2014/classes/warlock/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"minimum_score":13}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"}]},"subclasses":[{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"spellcasting":{"level":1,"spellcasting_ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"info":[{"name":"Cantrips","desc":["You know two cantrips of your choice from the warlock spell list. You learn additional warlock cantrips of your choice at higher levels, as shown in the Cantrips Known column of the Warlock table."]},{"name":"Spell Slots","desc":["The Warlock table shows how many spell slots you have. The table also shows what the level of those slots is; all of your spell slots are the same level. To cast one of your warlock spells of 1st level or higher, you must expend a spell slot. You regain all expended spell slots when you finish a short or long rest.","For example, when you are 5th level, you have two 3rd-level spell slots. To cast the 1st-level spell thunderwave, you must spend one of those slots, and you cast it as a 3rd-level spell."]},{"name":"Spells Known of 1st Level and Higher","desc":["At 1st level, you know two 1st-level spells of your choice from the warlock spell list.","The Spells Known column of the Warlock table shows when you learn more warlock spells of your choice of 1st level and higher. ","A spell you choose must be of a level no higher than what''s shown in the table''s Slot Level column for your level. When you reach 6th level, for example, you learn a new warlock spell, which can be 1st, 2nd, or 3rd level.","Additionally, when you gain a level in this class, you can choose one of the warlock spells you know and replace it with another spell from the warlock spell list, which also must be of a level for which you have spell slots."]},{"name":"Spellcasting Ability","desc":["Charisma is your spellcasting ability for your warlock spells, so you use your Charisma whenever a spell refers to your spellcasting ability. In addition, you use your Charisma modifier when setting the saving throw DC for a warlock spell you cast and when making an attack roll with one.","Spell save DC = 8 + your proficiency bonus + your Charisma modifier.","Spell attack modifier = your proficiency bonus + your Charisma modifier."]},{"name":"Spellcasting Focus","desc":["You can use an arcane focus as a spellcasting focus for your warlock spells."]}]},"spells":"/api/2014/classes/warlock/spells","url":"/api/2014/classes/warlock","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('class-wizard', 'class', 'Wizard', 'class-wizard', '{"index":"wizard","name":"Wizard","hit_die":6,"proficiency_choices":[{"desc":"Choose two from Arcana, History, Insight, Investigation, Medicine, and Religion","choose":2,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}]}}],"proficiencies":[{"index":"daggers","name":"Daggers","url":"/api/2014/proficiencies/daggers"},{"index":"darts","name":"Darts","url":"/api/2014/proficiencies/darts"},{"index":"slings","name":"Slings","url":"/api/2014/proficiencies/slings"},{"index":"quarterstaffs","name":"Quarterstaffs","url":"/api/2014/proficiencies/quarterstaffs"},{"index":"crossbows-light","name":"Crossbows, light","url":"/api/2014/proficiencies/crossbows-light"},{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"},{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}],"saving_throws":[{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"}],"starting_equipment":[{"equipment":{"index":"spellbook","name":"Spellbook","url":"/api/2014/equipment/spellbook"},"quantity":1}],"starting_equipment_options":[{"desc":"(a) a quarterstaff or (b) a dagger","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"quarterstaff","name":"Quarterstaff","url":"/api/2014/equipment/quarterstaff"}},{"option_type":"counted_reference","count":1,"of":{"index":"dagger","name":"Dagger","url":"/api/2014/equipment/dagger"}}]}},{"desc":"(a) a component pouch or (b) an arcane focus","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"component-pouch","name":"Component pouch","url":"/api/2014/equipment/component-pouch"}},{"option_type":"choice","choice":{"desc":"arcane focus","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"arcane-foci","name":"Arcane Foci","url":"/api/2014/equipment-categories/arcane-foci"}}}}]}},{"desc":"(a) a scholar’s pack or (b) an explorer’s pack","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"scholars-pack","name":"Scholar''s Pack","url":"/api/2014/equipment/scholars-pack"}},{"option_type":"counted_reference","count":1,"of":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"}}]}}],"class_levels":"/api/2014/classes/wizard/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"minimum_score":13}],"proficiencies":[]},"subclasses":[{"index":"evocation","name":"Evocation","url":"/api/2014/subclasses/evocation"}],"spellcasting":{"level":1,"spellcasting_ability":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"info":[{"name":"Cantrips","desc":["At 1st level, you know three cantrips of your choice from the wizard spell list. You learn additional wizard cantrips of your choice at higher levels, as shown in the Cantrips Known column of the Wizard table."]},{"name":"Spellbook","desc":["At 1st level, you have a spellbook containing six 1st- level wizard spells of your choice. Your spellbook is the repository of the wizard spells you know, except your cantrips, which are fixed in your mind."]},{"name":"Preparing and Casting Spells","desc":["The Wizard table shows how many spell slots you have to cast your spells of 1st level and higher. To cast one of these spells, you must expend a slot of the spell''s level or higher. You regain all expended spell slots when you finish a long rest.","You prepare the list of wizard spells that are available for you to cast. To do so, choose a number of wizard spells from your spellbook equal to your Intelligence modifier + your wizard level (minimum of one spell). The spells must be of a level for which you have spell slots.","For example, if you''re a 3rd-level wizard, you have four 1st-level and two 2nd-level spell slots. With an Intelligence of 16, your list of prepared spells can include six spells of 1st or 2nd level, in any combination, chosen from your spellbook. If you prepare the 1st-level spell magic missile, you can cast it using a 1st-level or a 2nd-level slot. Casting the spell doesn''t remove it from your list of prepared spells.","You can change your list of prepared spells when you finish a long rest. Preparing a new list of wizard spells requires time spent studying your spellbook and memorizing the incantations and gestures you must make to cast the spell: at least 1 minute per spell level for each spell on your list."]},{"name":"Spellcasting Ability","desc":["Intelligence is your spellcasting ability for your wizard spells, since you learn your spells through dedicated study and memorization. You use your Intelligence whenever a spell refers to your spellcasting ability. In addition, you use your Intelligence modifier when setting the saving throw DC for a wizard spell you cast and when making an attack roll with one.","Spell save DC = 8 + your proficiency bonus + your Intelligence modifier.","Spell attack modifier = your proficiency bonus + your Intelligence modifier."]},{"name":"Ritual Casting","desc":["You can cast a wizard spell as a ritual if that spell has the ritual tag and you have the spell in your spellbook. You don''t need to have the spell prepared."]},{"name":"Spellcasting Focus","desc":["You can use an arcane focus as a spellcasting focus for your wizard spells."]}]},"spells":"/api/2014/classes/wizard/spells","url":"/api/2014/classes/wizard","updated_at":"2026-04-01T20:35:36.453Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-dragonborn', 'race', 'Dragonborn', 'race-dragonborn', '{"index":"dragonborn","name":"Dragonborn","speed":30,"ability_bonuses":[{"ability_score":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"bonus":2},{"ability_score":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"bonus":1}],"alignment":"Dragonborn tend to extremes, making a conscious choice for one side or the other in the cosmic war between good and evil. Most dragonborn are good, but those who side with evil can be terrible villains.","age":"Young dragonborn grow quickly. They walk hours after hatching, attain the size and development of a 10-year-old human child by the age of 3, and reach adulthood by 15. They live to be around 80.","size":"Medium","size_description":"Dragonborn are taller and heavier than humans, standing well over 6 feet tall and averaging almost 250 pounds. Your size is Medium.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"},{"index":"draconic","name":"Draconic","url":"/api/2014/languages/draconic"}],"language_desc":"You can speak, read, and write Common and Draconic. Draconic is thought to be one of the oldest languages and is often used in the study of magic. The language sounds harsh to most other creatures and includes numerous hard consonants and sibilants.","traits":[{"index":"draconic-ancestry","name":"Draconic Ancestry","url":"/api/2014/traits/draconic-ancestry"},{"index":"breath-weapon","name":"Breath Weapon","url":"/api/2014/traits/breath-weapon"},{"index":"damage-resistance","name":"Damage Resistance","url":"/api/2014/traits/damage-resistance"}],"subraces":[],"url":"/api/2014/races/dragonborn","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-dwarf', 'race', 'Dwarf', 'race-dwarf', '{"index":"dwarf","name":"Dwarf","speed":25,"ability_bonuses":[{"ability_score":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"bonus":2}],"alignment":"Most dwarves are lawful, believing firmly in the benefits of a well-ordered society. They tend toward good as well, with a strong sense of fair play and a belief that everyone deserves to share in the benefits of a just order.","age":"Dwarves mature at the same rate as humans, but they''re considered young until they reach the age of 50. On average, they live about 350 years.","size":"Medium","size_description":"Dwarves stand between 4 and 5 feet tall and average about 150 pounds. Your size is Medium.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"},{"index":"dwarvish","name":"Dwarvish","url":"/api/2014/languages/dwarvish"}],"language_desc":"You can speak, read, and write Common and Dwarvish. Dwarvish is full of hard consonants and guttural sounds, and those characteristics spill over into whatever other language a dwarf might speak.","traits":[{"index":"darkvision","name":"Darkvision","url":"/api/2014/traits/darkvision"},{"index":"dwarven-resilience","name":"Dwarven Resilience","url":"/api/2014/traits/dwarven-resilience"},{"index":"stonecunning","name":"Stonecunning","url":"/api/2014/traits/stonecunning"},{"index":"dwarven-combat-training","name":"Dwarven Combat Training","url":"/api/2014/traits/dwarven-combat-training"},{"index":"tool-proficiency","name":"Tool Proficiency","url":"/api/2014/traits/tool-proficiency"}],"subraces":[{"index":"hill-dwarf","name":"Hill Dwarf","url":"/api/2014/subraces/hill-dwarf"}],"url":"/api/2014/races/dwarf","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-elf', 'race', 'Elf', 'race-elf', '{"index":"elf","name":"Elf","speed":30,"ability_bonuses":[{"ability_score":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"bonus":2}],"age":"Although elves reach physical maturity at about the same age as humans, the elven understanding of adulthood goes beyond physical growth to encompass worldly experience. An elf typically claims adulthood and an adult name around the age of 100 and can live to be 750 years old.","alignment":"Elves love freedom, variety, and self-expression, so they lean strongly toward the gentler aspects of chaos. They value and protect others'' freedom as well as their own, and they are more often good than not.","size":"Medium","size_description":"Elves range from under 5 to over 6 feet tall and have slender builds. Your size is Medium.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"},{"index":"elvish","name":"Elvish","url":"/api/2014/languages/elvish"}],"language_desc":"You can speak, read, and write Common and Elvish. Elvish is fluid, with subtle intonations and intricate grammar. Elven literature is rich and varied, and their songs and poems are famous among other races. Many bards learn their language so they can add Elvish ballads to their repertoires.","traits":[{"index":"darkvision","name":"Darkvision","url":"/api/2014/traits/darkvision"},{"index":"fey-ancestry","name":"Fey Ancestry","url":"/api/2014/traits/fey-ancestry"},{"index":"trance","name":"Trance","url":"/api/2014/traits/trance"},{"index":"keen-senses","name":"Keen Senses","url":"/api/2014/traits/keen-senses"}],"subraces":[{"index":"high-elf","name":"High Elf","url":"/api/2014/subraces/high-elf"}],"url":"/api/2014/races/elf","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-gnome', 'race', 'Gnome', 'race-gnome', '{"index":"gnome","name":"Gnome","speed":25,"ability_bonuses":[{"ability_score":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"bonus":2}],"alignment":"Gnomes are most often good. Those who tend toward law are sages, engineers, researchers, scholars, investigators, or inventors. Those who tend toward chaos are minstrels, tricksters, wanderers, or fanciful jewelers. Gnomes are good-hearted, and even the tricksters among them are more playful than vicious.","age":"Gnomes mature at the same rate humans do, and most are expected to settle down into an adult life by around age 40. They can live 350 to almost 500 years.","size":"Small","size_description":"Gnomes are between 3 and 4 feet tall and average about 40 pounds. Your size is Small.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"},{"index":"gnomish","name":"Gnomish","url":"/api/2014/languages/gnomish"}],"language_desc":"You can speak, read, and write Common and Gnomish. The Gnomish language, which uses the Dwarvish script, is renowned for its technical treatises and its catalogs of knowledge about the natural world.","traits":[{"index":"darkvision","name":"Darkvision","url":"/api/2014/traits/darkvision"},{"index":"gnome-cunning","name":"Gnome Cunning","url":"/api/2014/traits/gnome-cunning"}],"subraces":[{"index":"rock-gnome","name":"Rock Gnome","url":"/api/2014/subraces/rock-gnome"}],"url":"/api/2014/races/gnome","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-half-elf', 'race', 'Half-Elf', 'race-half-elf', '{"index":"half-elf","name":"Half-Elf","speed":30,"ability_bonuses":[{"ability_score":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"bonus":2}],"ability_bonus_options":{"choose":2,"type":"ability_bonuses","from":{"option_set_type":"options_array","options":[{"option_type":"ability_bonus","ability_score":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"bonus":1},{"option_type":"ability_bonus","ability_score":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"bonus":1},{"option_type":"ability_bonus","ability_score":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"bonus":1},{"option_type":"ability_bonus","ability_score":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"bonus":1},{"option_type":"ability_bonus","ability_score":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"bonus":1}]}},"alignment":"Half-elves share the chaotic bent of their elven heritage. They value both personal freedom and creative expression, demonstrating neither love of leaders nor desire for followers. They chafe at rules, resent others'' demands, and sometimes prove unreliable, or at least unpredictable.","age":"Half-elves mature at the same rate humans do and reach adulthood around the age of 20. They live much longer than humans, however, often exceeding 180 years.","size":"Medium","size_description":"Half-elves are about the same size as humans, ranging from 5 to 6 feet tall. Your size is Medium.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"},{"index":"elvish","name":"Elvish","url":"/api/2014/languages/elvish"}],"language_options":{"choose":1,"type":"languages","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"dwarvish","name":"Dwarvish","url":"/api/2014/languages/dwarvish"}},{"option_type":"reference","item":{"index":"giant","name":"Giant","url":"/api/2014/languages/giant"}},{"option_type":"reference","item":{"index":"gnomish","name":"Gnomish","url":"/api/2014/languages/gnomish"}},{"option_type":"reference","item":{"index":"goblin","name":"Goblin","url":"/api/2014/languages/goblin"}},{"option_type":"reference","item":{"index":"halfling","name":"Halfling","url":"/api/2014/languages/halfling"}},{"option_type":"reference","item":{"index":"orc","name":"Orc","url":"/api/2014/languages/orc"}},{"option_type":"reference","item":{"index":"abyssal","name":"Abyssal","url":"/api/2014/languages/abyssal"}},{"option_type":"reference","item":{"index":"celestial","name":"Celestial","url":"/api/2014/languages/celestial"}},{"option_type":"reference","item":{"index":"draconic","name":"Draconic","url":"/api/2014/languages/draconic"}},{"option_type":"reference","item":{"index":"deep-speech","name":"Deep Speech","url":"/api/2014/languages/deep-speech"}},{"option_type":"reference","item":{"index":"infernal","name":"Infernal","url":"/api/2014/languages/infernal"}},{"option_type":"reference","item":{"index":"primordial","name":"Primordial","url":"/api/2014/languages/primordial"}},{"option_type":"reference","item":{"index":"sylvan","name":"Sylvan","url":"/api/2014/languages/sylvan"}},{"option_type":"reference","item":{"index":"undercommon","name":"Undercommon","url":"/api/2014/languages/undercommon"}}]}},"language_desc":"You can speak, read, and write Common, Elvish, and one extra language of your choice.","traits":[{"index":"darkvision","name":"Darkvision","url":"/api/2014/traits/darkvision"},{"index":"fey-ancestry","name":"Fey Ancestry","url":"/api/2014/traits/fey-ancestry"},{"index":"skill-versatility","name":"Skill Versatility","url":"/api/2014/traits/skill-versatility"}],"subraces":[],"url":"/api/2014/races/half-elf","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-half-orc', 'race', 'Half-Orc', 'race-half-orc', '{"index":"half-orc","name":"Half-Orc","speed":30,"ability_bonuses":[{"ability_score":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"bonus":2},{"ability_score":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"bonus":1}],"alignment":"Half-orcs inherit a tendency toward chaos from their orc parents and are not strongly inclined toward good. Half-orcs raised among orcs and willing to live out their lives among them are usually evil.","age":"Half-orcs mature a little faster than humans, reaching adulthood around age 14. They age noticeably faster and rarely live longer than 75 years.","size":"Medium","size_description":"Half-orcs are somewhat larger and bulkier than humans, and they range from 5 to well over 6 feet tall. Your size is Medium.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"},{"index":"orc","name":"Orc","url":"/api/2014/languages/orc"}],"language_desc":"You can speak, read, and write Common and Orc. Orc is a harsh, grating language with hard consonants. It has no script of its own but is written in the Dwarvish script.","traits":[{"index":"darkvision","name":"Darkvision","url":"/api/2014/traits/darkvision"},{"index":"savage-attacks","name":"Savage Attacks","url":"/api/2014/traits/savage-attacks"},{"index":"relentless-endurance","name":"Relentless Endurance","url":"/api/2014/traits/relentless-endurance"},{"index":"menacing","name":"Menacing","url":"/api/2014/traits/menacing"}],"subraces":[],"url":"/api/2014/races/half-orc","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-halfling', 'race', 'Halfling', 'race-halfling', '{"index":"halfling","name":"Halfling","speed":25,"ability_bonuses":[{"ability_score":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"bonus":2}],"age":"A halfling reaches adulthood at the age of 20 and generally lives into the middle of his or her second century.","alignment":"Most halflings are lawful good. As a rule, they are good-hearted and kind, hate to see others in pain, and have no tolerance for oppression. They are also very orderly and traditional, leaning heavily on the support of their community and the comfort of their old ways.","size":"Small","size_description":"Halflings average about 3 feet tall and weigh about 40 pounds. Your size is Small.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"},{"index":"halfling","name":"Halfling","url":"/api/2014/languages/halfling"}],"language_desc":"You can speak, read, and write Common and Halfling. The Halfling language isn''t secret, but halflings are loath to share it with others. They write very little, so they don''t have a rich body of literature. Their oral tradition, however, is very strong. Almost all halflings speak Common to converse with the people in whose lands they dwell or through which they are traveling.","traits":[{"index":"brave","name":"Brave","url":"/api/2014/traits/brave"},{"index":"halfling-nimbleness","name":"Halfling Nimbleness","url":"/api/2014/traits/halfling-nimbleness"},{"index":"lucky","name":"Lucky","url":"/api/2014/traits/lucky"}],"subraces":[{"index":"lightfoot-halfling","name":"Lightfoot Halfling","url":"/api/2014/subraces/lightfoot-halfling"}],"url":"/api/2014/races/halfling","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-human', 'race', 'Human', 'race-human', '{"index":"human","name":"Human","speed":30,"ability_bonuses":[{"ability_score":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"bonus":1},{"ability_score":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"bonus":1},{"ability_score":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"bonus":1},{"ability_score":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"bonus":1},{"ability_score":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"bonus":1},{"ability_score":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"bonus":1}],"age":"Humans reach adulthood in their late teens and live less than a century.","alignment":"Humans tend toward no particular alignment. The best and the worst are found among them.","size":"Medium","size_description":"Humans vary widely in height and build, from barely 5 feet to well over 6 feet tall. Regardless of your position in that range, your size is Medium.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"}],"language_options":{"choose":1,"type":"languages","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"dwarvish","name":"Dwarvish","url":"/api/2014/languages/dwarvish"}},{"option_type":"reference","item":{"index":"elvish","name":"Elvish","url":"/api/2014/languages/elvish"}},{"option_type":"reference","item":{"index":"giant","name":"Giant","url":"/api/2014/languages/giant"}},{"option_type":"reference","item":{"index":"gnomish","name":"Gnomish","url":"/api/2014/languages/gnomish"}},{"option_type":"reference","item":{"index":"goblin","name":"Goblin","url":"/api/2014/languages/goblin"}},{"option_type":"reference","item":{"index":"halfling","name":"Halfling","url":"/api/2014/languages/halfling"}},{"option_type":"reference","item":{"index":"orc","name":"Orc","url":"/api/2014/languages/orc"}},{"option_type":"reference","item":{"index":"abyssal","name":"Abyssal","url":"/api/2014/languages/abyssal"}},{"option_type":"reference","item":{"index":"celestial","name":"Celestial","url":"/api/2014/languages/celestial"}},{"option_type":"reference","item":{"index":"draconic","name":"Draconic","url":"/api/2014/languages/draconic"}},{"option_type":"reference","item":{"index":"deep-speech","name":"Deep Speech","url":"/api/2014/languages/deep-speech"}},{"option_type":"reference","item":{"index":"infernal","name":"Infernal","url":"/api/2014/languages/infernal"}},{"option_type":"reference","item":{"index":"primordial","name":"Primordial","url":"/api/2014/languages/primordial"}},{"option_type":"reference","item":{"index":"sylvan","name":"Sylvan","url":"/api/2014/languages/sylvan"}},{"option_type":"reference","item":{"index":"undercommon","name":"Undercommon","url":"/api/2014/languages/undercommon"}}]}},"language_desc":"You can speak, read, and write Common and one extra language of your choice. Humans typically learn the languages of other peoples they deal with, including obscure dialects. They are fond of sprinkling their speech with words borrowed from other tongues: Orc curses, Elvish musical expressions, Dwarvish military phrases, and so on.","traits":[],"subraces":[],"url":"/api/2014/races/human","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('race-tiefling', 'race', 'Tiefling', 'race-tiefling', '{"index":"tiefling","name":"Tiefling","speed":30,"ability_bonuses":[{"ability_score":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"bonus":1},{"ability_score":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"bonus":2}],"alignment":"Tieflings might not have an innate tendency toward evil, but many of them end up there. Evil or not, an independent nature inclines many tieflings toward a chaotic alignment.","age":"Tieflings mature at the same rate as humans but live a few years longer.","size":"Medium","size_description":"Tieflings are about the same size and build as humans. Your size is Medium.","languages":[{"index":"common","name":"Common","url":"/api/2014/languages/common"},{"index":"infernal","name":"Infernal","url":"/api/2014/languages/infernal"}],"language_desc":"You can speak, read, and write Common and Infernal.","traits":[{"index":"darkvision","name":"Darkvision","url":"/api/2014/traits/darkvision"},{"index":"hellish-resistance","name":"Hellish Resistance","url":"/api/2014/traits/hellish-resistance"},{"index":"infernal-legacy","name":"Infernal Legacy","url":"/api/2014/traits/infernal-legacy"}],"subraces":[],"url":"/api/2014/races/tiefling","updated_at":"2026-04-01T20:35:38.675Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-acid-arrow', 'spell', 'Acid Arrow', 'spell-acid-arrow', '{"index":"acid-arrow","name":"Acid Arrow","desc":["A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 acid damage immediately and 2d4 acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage and no damage at the end of its next turn."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, the damage (both initial and later) increases by 1d4 for each slot level above 2nd."],"range":"90 feet","components":["V","S","M"],"material":"Powdered rhubarb leaf and an adder''s stomach.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":2,"attack_type":"ranged","damage":{"damage_type":{"index":"acid","name":"Acid","url":"/api/2014/damage-types/acid"},"damage_at_slot_level":{"2":"4d4","3":"5d4","4":"6d4","5":"7d4","6":"8d4","7":"9d4","8":"10d4","9":"11d4"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/acid-arrow","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-acid-splash', 'spell', 'Acid Splash', 'spell-acid-splash', '{"higher_level":[],"index":"acid-splash","name":"Acid Splash","desc":["You hurl a bubble of acid. Choose one creature within range, or choose two creatures within range that are within 5 feet of each other. A target must succeed on a dexterity saving throw or take 1d6 acid damage.","This spell''s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"damage":{"damage_type":{"index":"acid","name":"Acid","url":"/api/2014/damage-types/acid"},"damage_at_character_level":{"1":"1d6","5":"2d6","11":"3d6","17":"4d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"none"},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/acid-splash","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-aid', 'spell', 'Aid', 'spell-aid', '{"index":"aid","name":"Aid","desc":["Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each target''s hit point maximum and current hit points increase by 5 for the duration."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, a target''s hit points increase by an additional 5 for each slot level above 2nd."],"range":"30 feet","components":["V","S","M"],"material":"A tiny strip of white cloth.","ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":2,"heal_at_slot_level":{"2":"5","3":"10","4":"15","5":"20","6":"25","7":"30","8":"35","9":"40"},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/aid","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-alarm', 'spell', 'Alarm', 'spell-alarm', '{"higher_level":[],"index":"alarm","name":"Alarm","desc":["You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you whenever a Tiny or larger creature touches or enters the warded area. When you cast the spell, you can designate creatures that won''t set off the alarm. You also choose whether the alarm is mental or audible.","A mental alarm alerts you with a ping in your mind if you are within 1 mile of the warded area. This ping awakens you if you are sleeping.","An audible alarm produces the sound of a hand bell for 10 seconds within 60 feet."],"range":"30 feet","components":["V","S","M"],"material":"A tiny bell and a piece of fine silver wire.","ritual":true,"duration":"8 hours","concentration":false,"casting_time":"1 minute","level":1,"area_of_effect":{"type":"cube","size":20},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/alarm","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-alter-self', 'spell', 'Alter Self', 'spell-alter-self', '{"higher_level":[],"index":"alter-self","name":"Alter Self","desc":["You assume a different form. When you cast the spell, choose one of the following options, the effects of which last for the duration of the spell. While the spell lasts, you can end one option as an action to gain the benefits of a different one.","***Aquatic Adaptation.*** You adapt your body to an aquatic environment, sprouting gills and growing webbing between your fingers. You can breathe underwater and gain a swimming speed equal to your walking speed.","***Change Appearance.*** You transform your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and distinguishing characteristics, if any. You can make yourself appear as a member of another race, though none of your statistics change. You also can''t appear as a creature of a different size than you, and your basic shape stays the same; if you''re bipedal, you can''t use this spell to become quadrupedal, for instance. At any time for the duration of the spell, you can use your action to change your appearance in this way again.","***Natural Weapons.*** You grow claws, fangs, spines, horns, or a different natural weapon of your choice. Your unarmed strikes deal 1d6 bludgeoning, piercing, or slashing damage, as appropriate to the natural weapon you chose, and you are proficient with your unarmed strikes. Finally, the natural weapon is magic and you have a +1 bonus to the attack and damage rolls you make using it."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/alter-self","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-animal-friendship', 'spell', 'Animal Friendship', 'spell-animal-friendship', '{"higher_level":[],"index":"animal-friendship","name":"Animal Friendship","desc":["This spell lets you convince a beast that you mean it no harm. Choose a beast that you can see within range. It must see and hear you. If the beast''s Intelligence is 4 or higher, the spell fails. Otherwise, the beast must succeed on a wisdom saving throw or be charmed by you for the spell''s duration. If you or one of your companions harms the target, the spells ends."],"range":"30 feet","components":["V","S","M"],"material":"A morsel of food.","ritual":false,"duration":"24 hours","concentration":false,"casting_time":"1 action","level":1,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[],"url":"/api/2014/spells/animal-friendship","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-animal-messenger', 'spell', 'Animal Messenger', 'spell-animal-messenger', '{"index":"animal-messenger","name":"Animal Messenger","desc":["By means of this spell, you use an animal to deliver a message. Choose a Tiny beast you can see within range, such as a squirrel, a blue jay, or a bat. You specify a location, which you must have visited, and a recipient who matches a general description, such as \"a man or woman dressed in the uniform of the town guard\" or \"a red-haired dwarf wearing a pointed hat.\" You also speak a message of up to twenty-five words. The target beast travels for the duration of the spell toward the specified location, covering about 50 miles per 24 hours for a flying messenger, or 25 miles for other animals.","When the messenger arrives, it delivers your message to the creature that you described, replicating the sound of your voice. The messenger speaks only to a creature matching the description you gave. If the messenger doesn''t reach its destination before the spell ends, the message is lost, and the beast makes its way back to where you cast this spell."],"higher_level":["If you cast this spell using a spell slot of 3nd level or higher, the duration of the spell increases by 48 hours for each slot level above 2nd."],"range":"30 feet","components":["V","S","M"],"material":"A morsel of food.","ritual":true,"duration":"24 hours","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/animal-messenger","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-animal-shapes', 'spell', 'Animal Shapes', 'spell-animal-shapes', '{"higher_level":[],"index":"animal-shapes","name":"Animal Shapes","desc":["Your magic turns others into beasts. Choose any number of willing creatures that you can see within range. You transform each target into the form of a Large or smaller beast with a challenge rating of 4 or lower. On subsequent turns, you can use your action to transform affected creatures into new forms.","The transformation lasts for the duration for each target, or until the target drops to 0 hit points or dies. You can choose a different form for each target. A target''s game statistics are replaced by the statistics of the chosen beast, though the target retains its alignment and Intelligence, Wisdom, and Charisma scores. The target assumes the hit points of its new form, and when it reverts to its normal form, it returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn''t reduce the creature''s normal form to 0 hit points, it isn''t knocked unconscious. The creature is limited in the actions it can perform by the nature of its new form, and it can''t speak or cast spells.","The target''s gear melds into the new form. The target can''t activate, wield, or otherwise benefit from any of its equipment."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Up to 24 hours","concentration":true,"casting_time":"1 action","level":8,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/animal-shapes","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-animate-dead', 'spell', 'Animate Dead', 'spell-animate-dead', '{"index":"animate-dead","name":"Animate Dead","desc":["This spell creates an undead servant. Choose a pile of bones or a corpse of a Medium or Small humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an undead creature. The target becomes a skeleton if you chose bones or a zombie if you chose a corpse (the GM has the creature''s game statistics).","On each of your turns, you can use a bonus action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.","The creature is under your control for 24 hours, after which it stops obeying any command you''ve given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell, rather than animating a new one."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, you animate or reassert control over two additional undead creatures for each slot level above 3rd. Each of the creatures must come from a different corpse or pile of bones."],"range":"10 feet","components":["V","S","M"],"material":"A drop of blood, a piece of flesh, and a pinch of bone dust.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 minute","level":3,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/animate-dead","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-animate-objects', 'spell', 'Animate Objects', 'spell-animate-objects', '{"index":"animate-objects","name":"Animate Objects","desc":["Objects come to life at your command. Choose up to ten nonmagical objects within range that are not being worn or carried. Medium targets count as two objects, Large targets count as four objects, Huge targets count as eight objects. You can''t animate any object larger than Huge. Each target animates and becomes a creature under your control until the spell ends or until reduced to 0 hit points.","As a bonus action, you can mentally command any creature you made with this spell if the creature is within 500 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.","##### Animated Object Statistics","| Size | HP | AC | Attack | Str | Dex |","|---|---|---|---|---|---|","| Tiny | 20 | 18 | +8 to hit, 1d4 + 4 damage | 4 | 18 |","| Small | 25 | 16 | +6 to hit, 1d8 + 2 damage | 6 | 14 |","| Medium | 40 | 13 | +5 to hit, 2d6 + 1 damage | 10 | 12 |","| Large | 50 | 10 | +6 to hit, 2d10 + 2 damage | 14 | 10 |","| Huge | 80 | 10 | +8 to hit, 2d12 + 4 damage | 18 | 6 |","An animated object is a construct with AC, hit points, attacks, Strength, and Dexterity determined by its size. Its Constitution is 10 and its Intelligence and Wisdom are 3, and its Charisma is 1. Its speed is 30 feet; if the object lacks legs or other appendages it can use for locomotion, it instead has a flying speed of 30 feet and can hover. If the object is securely attached to a surface or a larger object, such as a chain bolted to a wall, its speed is 0. It has blindsight with a radius of 30 feet and is blind beyond that distance. When the animated object drops to 0 hit points, it reverts to its original object form, and any remaining damage carries over to its original object form.","If you command an object to attack, it can make a single melee attack against a creature within 5 feet of it. It makes a slam attack with an attack bonus and bludgeoning damage determined by its size. The GM might rule that a specific object inflicts slashing or piercing damage based on its form."],"higher_level":["If you cast this spell using a spell slot of 6th level or higher, you can animate two additional objects for each slot level above 5th."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":5,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/animate-objects","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-antilife-shell', 'spell', 'Antilife Shell', 'spell-antilife-shell', '{"higher_level":[],"index":"antilife-shell","name":"Antilife Shell","desc":["A shimmering barrier extends out from you in a 10-foot radius and moves with you, remaining centered on you and hedging out creatures other than undead and constructs. The barrier lasts for the duration.","The barrier prevents an affected creature from passing or reaching through. An affected creature can cast spells or make attacks with ranged or reach weapons through the barrier.","If you move so that an affected creature is forced to pass through the barrier, the spell ends."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":5,"area_of_effect":{"type":"sphere","size":10},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/antilife-shell","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-antimagic-field', 'spell', 'Antimagic Field', 'spell-antimagic-field', '{"higher_level":[],"index":"antimagic-field","name":"Antimagic Field","desc":["A 10-foot-radius invisible sphere of antimagic surrounds you. This area is divorced from the magical energy that suffuses the multiverse. Within the sphere, spells can''t be cast, summoned creatures disappear, and even magic items become mundane. Until the spell ends, the sphere moves with you, centered on you.","Spells and other magical effects, except those created by an artifact or a deity, are suppressed in the sphere and can''t protrude into it. A slot expended to cast a suppressed spell is consumed. While an effect is suppressed, it doesn''t function, but the time it spends suppressed counts against its duration.","***Targeted Effects.*** Spells and other magical effects, such as magic missile and charm person, that target a creature or an object in the sphere have no effect on that target.","***Areas of Magic.*** The area of another spell or magical effect, such as fireball, can''t extend into the sphere. If the sphere overlaps an area of magic, the part of the area that is covered by the sphere is suppressed. For example, the flames created by a wall of fire are suppressed within the sphere, creating a gap in the wall if the overlap is large enough.","***Spells.*** Any active spell or other magical effect on a creature or an object in the sphere is suppressed while the creature or object is in it.","***Magic Items.*** The properties and powers of magic items are suppressed in the sphere. For example, a +1 longsword in the sphere functions as a nonmagical longsword.","A magic weapon''s properties and powers are suppressed if it is used against a target in the sphere or wielded by an attacker in the sphere. If a magic weapon or a piece of magic ammunition fully leaves the sphere (for example, if you fire a magic arrow or throw a magic spear at a target outside the sphere), the magic of the item ceases to be suppressed as soon as it exits.","***Magical Travel.*** Teleportation and planar travel fail to work in the sphere, whether the sphere is the destination or the departure point for such magical travel. A portal to another location, world, or plane of existence, as well as an opening to an extradimensional space such as that created by the rope trick spell, temporarily closes while in the sphere.","***Creatures and Objects.*** A creature or object summoned or created by magic temporarily winks out of existence in the sphere. Such a creature instantly reappears once the space the creature occupied is no longer within the sphere.","***Dispel Magic.*** Spells and magical effects such as dispel magic have no effect on the sphere. Likewise, the spheres created by different antimagic field spells don''t nullify each other."],"range":"Self","components":["V","S","M"],"material":"A pinch of powdered iron or iron filings.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":8,"area_of_effect":{"type":"sphere","size":10},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/antimagic-field","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-antipathy-sympathy', 'spell', 'Antipathy/Sympathy', 'spell-antipathy-sympathy', '{"higher_level":[],"index":"antipathy-sympathy","name":"Antipathy/Sympathy","desc":["This spell attracts or repels creatures of your choice. You target something within range, either a Huge or smaller object or creature or an area that is no larger than a 200-foot cube. Then specify a kind of intelligent creature, such as red dragons, goblins, or vampires. You invest the target with an aura that either attracts or repels the specified creatures for the duration. Choose antipathy or sympathy as the aura''s effect.","***Antipathy.*** The enchantment causes creatures of the kind you designated to feel an intense urge to leave the area and avoid the target. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a wisdom saving throw or become frightened. The creature remains frightened while it can see the target or is within 60 feet of it. While frightened by the target, the creature must use its movement to move to the nearest safe spot from which it can''t see the target. If the creature moves more than 60 feet from the target and can''t see it, the creature is no longer frightened, but the creature becomes frightened again if it regains sight of the target or moves within 60 feet of it.","***Sympathy.*** The enchantment causes the specified creatures to feel an intense urge to approach the target while within 60 feet of it or able to see it. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a wisdom saving throw or use its movement on each of its turns to enter the area or move within reach of the target. When the creature has done so, it can''t willingly move away from the target.","If the target damages or otherwise harms an affected creature, the affected creature can make a wisdom saving throw to end the effect, as described below.","***Ending the Effect.*** If an affected creature ends its turn while not within 60 feet of the target or able to see it, the creature makes a wisdom saving throw. On a successful save, the creature is no longer affected by the target and recognizes the feeling of repugnance or attraction as magical. In addition, a creature affected by the spell is allowed another wisdom saving throw every 24 hours while the spell persists.","A creature that successfully saves against this effect is immune to it for 1 minute, after which time it can be affected again."],"range":"60 feet","components":["V","S","M"],"material":"Either a lump of alum soaked in vinegar for the antipathy effect or a drop of honey for the sympathy effect.","ritual":false,"duration":"10 days","concentration":false,"casting_time":"1 hour","level":8,"area_of_effect":{"type":"cube","size":200},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/antipathy-sympathy","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-arcane-eye', 'spell', 'Arcane Eye', 'spell-arcane-eye', '{"higher_level":[],"index":"arcane-eye","name":"Arcane Eye","desc":["You create an invisible, magical eye within range that hovers in the air for the duration.","You mentally receive visual information from the eye, which has normal vision and darkvision out to 30 feet. The eye can look in every direction.","As an action, you can move the eye up to 30 feet in any direction. There is no limit to how far away from you the eye can move, but it can''t enter another plane of existence. A solid barrier blocks the eye''s movement, but the eye can pass through an opening as small as 1 inch in diameter."],"range":"30 feet","components":["V","S","M"],"material":"A bit of bat fur.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":4,"area_of_effect":{"type":"sphere","size":30},"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/arcane-eye","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-arcane-hand', 'spell', 'Arcane Hand', 'spell-arcane-hand', '{"index":"arcane-hand","name":"Arcane Hand","desc":["You create a Large hand of shimmering, translucent force in an unoccupied space that you can see within range. The hand lasts for the spell''s duration, and it moves at your command, mimicking the movements of your own hand.","The hand is an object that has AC 20 and hit points equal to your hit point maximum. If it drops to 0 hit points, the spell ends. It has a Strength of 26 (+8) and a Dexterity of 10 (+0). The hand doesn''t fill its space.","When you cast the spell and as a bonus action on your subsequent turns, you can move the hand up to 60 feet and then cause one of the following effects with it.","***Clenched Fist.*** The hand strikes one creature or object within 5 feet of it. Make a melee spell attack for the hand using your game statistics. On a hit, the target takes 4d8 force damage.","***Forceful Hand.*** The hand attempts to push a creature within 5 feet of it in a direction you choose. Make a check with the hand''s Strength contested by the Strength (Athletics) check of the target. If the target is Medium or smaller, you have advantage on the check. If you succeed, the hand pushes the target up to 5 feet plus a number of feet equal to five times your spellcasting ability modifier. The hand moves with the target to remain within 5 feet of it.","***Grasping Hand.*** The hand attempts to grapple a Huge or smaller creature within 5 feet of it. You use the hand''s Strength score to resolve the grapple. If the target is Medium or smaller, you have advantage on the check. While the hand is grappling the target, you can use a bonus action to have the hand crush it. When you do so, the target takes bludgeoning damage equal to 2d6 + your spellcasting ability modifier.","***Interposing Hand.*** The hand interposes itself between you and a creature you choose until you give the hand a different command. The hand moves to stay between you and the target, providing you with half cover against the target. The target can''t move through the hand''s space if its Strength score is less than or equal to the hand''s Strength score. If its Strength score is higher than the hand''s Strength score, the target can move toward you through the hand''s space, but that space is difficult terrain for the target."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the damage from the clenched fist option increases by 2d8 and the damage from the grasping hand increases by 2d6 for each slot level above 5th."],"range":"120 feet","components":["V","S","M"],"material":"An eggshell and a snakeskin glove.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":5,"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/arcane-hand","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-arcane-lock', 'spell', 'Arcane Lock', 'spell-arcane-lock', '{"higher_level":[],"index":"arcane-lock","name":"Arcane Lock","desc":["You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and the creatures you designate when you cast this spell can open the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute. Otherwise, it is impassable until it is broken or the spell is dispelled or suppressed. Casting knock on the object suppresses arcane lock for 10 minutes.","While affected by this spell, the object is more difficult to break or force open; the DC to break it or pick any locks on it increases by 10."],"range":"Touch","components":["V","S","M"],"material":"Gold dust worth at least 25gp, which the spell consumes.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/arcane-lock","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-arcane-sword', 'spell', 'Arcane Sword', 'spell-arcane-sword', '{"higher_level":[],"index":"arcane-sword","name":"Arcane Sword","desc":["You create a sword-shaped plane of force that hovers within range. It lasts for the duration.","When the sword appears, you make a melee spell attack against a target of your choice within 5 feet of the sword. On a hit, the target takes 3d10 force damage. Until the spell ends, you can use a bonus action on each of your turns to move the sword up to 20 feet to a spot you can see and repeat this attack against the same target or a different one."],"range":"60 feet","components":["V","S","M"],"material":"A miniature platinum sword with a grip and pommel of copper and zinc, worth 250 gp.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":7,"attack_type":"melee","damage":{"damage_type":{"index":"force","name":"Force","url":"/api/2014/damage-types/force"},"damage_at_slot_level":{"7":"3d10"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/arcane-sword","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-arcanists-magic-aura', 'spell', 'Arcanist''s Magic Aura', 'spell-arcanists-magic-aura', '{"higher_level":[],"index":"arcanists-magic-aura","name":"Arcanist''s Magic Aura","desc":["You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn''t being carried or worn by another creature.","When you cast the spell, choose one or both of the following effects. The effect lasts for the duration. If you cast this spell on the same creature or object every day for 30 days, placing the same effect on it each time, the illusion lasts until it is dispelled.","***False Aura.*** You change the way the target appears to spells and magical effects, such as detect magic, that detect magical auras. You can make a nonmagical object appear magical, a magical object appear nonmagical, or change the object''s magical aura so that it appears to belong to a specific school of magic that you choose. When you use this effect on an object, you can make the false magic apparent to any creature that handles the item.","***Mask.*** You change the way the target appears to spells and magical effects that detect creature types, such as a paladin''s Divine Sense or the trigger of a symbol spell. You choose a creature type and other spells and magical effects treat the target as if it were a creature of that type or of that alignment."],"range":"Touch","components":["V","S","M"],"material":"A small square of silk.","ritual":false,"duration":"24 hours","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/arcanists-magic-aura","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-astral-projection', 'spell', 'Astral Projection', 'spell-astral-projection', '{"higher_level":[],"index":"astral-projection","name":"Astral Projection","desc":["You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell fails and the casting is wasted if you are already on that plane). The material body you leave behind is unconscious and in a state of suspended animation; it doesn''t need food or air and doesn''t age.","Your astral body resembles your mortal form in almost every way, replicating your game statistics and possessions. The principal difference is the addition of a silvery cord that extends from between your shoulder blades and trails behind you, fading to invisibility after 1 foot. This cord is your tether to your material body. As long as the tether remains intact, you can find your way home. If the cord is cut--something that can happen only when an effect specifically states that it does--your soul and body are separated, killing you instantly.","Your astral form can freely travel through the Astral Plane and can pass through portals there leading to any other plane. If you enter a new plane or return to the plane you were on when casting this spell, your body and possessions are transported along the silver cord, allowing you to re-enter your body as you enter the new plane. Your astral form is a separate incarnation. Any damage or other effects that apply to it have no effect on your physical body, nor do they persist when you return to it.","The spell ends for you and your companions when you use your action to dismiss it. When the spell ends, the affected creature returns to its physical body, and it awakens.","The spell might also end early for you or one of your companions. A successful dispel magic spell used against an astral or physical body ends the spell for that creature. If a creature''s original body or its astral form drops to 0 hit points, the spell ends for that creature. If the spell ends and the silver cord is intact, the cord pulls the creature''s astral form back to its body, ending its state of suspended animation.","If you are returned to your body prematurely, your companions remain in their astral forms and must find their own way back to their bodies, usually by dropping to 0 hit points."],"range":"10 feet","components":["V","S","M"],"material":"For each creature you affect with this spell, you must provide one jacinth worth at least 1,000gp and one ornately carved bar of silver worth at least 100gp, all of which the spell consumes.","ritual":false,"duration":"Special","concentration":false,"casting_time":"1 hour","level":9,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/astral-projection","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-augury', 'spell', 'Augury', 'spell-augury', '{"higher_level":[],"index":"augury","name":"Augury","desc":["By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes. The GM chooses from the following possible omens:","- Weal, for good results","- Woe, for bad results","- Weal and woe, for both good and bad results","- Nothing, for results that aren''t especially good or bad","The spell doesn''t take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.","If you cast the spell two or more times before completing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret."],"range":"Self","components":["V","S","M"],"material":"Specially marked sticks, bones, or similar tokens worth at least 25gp.","ritual":true,"duration":"Instantaneous","concentration":false,"casting_time":"1 minute","level":2,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/augury","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-awaken', 'spell', 'Awaken', 'spell-awaken', '{"higher_level":[],"index":"awaken","name":"Awaken","desc":["After spending the casting time tracing magical pathways within a precious gemstone, you touch a Huge or smaller beast or plant. The target must have either no Intelligence score or an Intelligence of 3 or less. The target gains an Intelligence of 10. The target also gains the ability to speak one language you know. If the target is a plant, it gains the ability to move its limbs, roots, vines, creepers, and so forth, and it gains senses similar to a human''s. Your GM chooses statistics appropriate for the awakened plant, such as the statistics for the awakened shrub or the awakened tree.","The awakened beast or plant is charmed by you for 30 days or until you or your companions do anything harmful to it. When the charmed condition ends, the awakened creature chooses whether to remain friendly to you, based on how you treated it while it was charmed."],"range":"Touch","components":["V","S","M"],"material":"An agate worth at least 1,000 gp, which the spell consumes.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"8 hours","level":5,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/awaken","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-bane', 'spell', 'Bane', 'spell-bane', '{"index":"bane","name":"Bane","desc":["Up to three creatures of your choice that you can see within range must make charisma saving throws. Whenever a target that fails this saving throw makes an attack roll or a saving throw before the spell ends, the target must roll a d4 and subtract the number rolled from the attack roll or saving throw."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st."],"range":"30 feet","components":["V","S","M"],"material":"A drop of blood.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":1,"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/bane","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-banishment', 'spell', 'Banishment', 'spell-banishment', '{"index":"banishment","name":"Banishment","desc":["You attempt to send one creature that you can see within range to another plane of existence. The target must succeed on a charisma saving throw or be banished.","If the target is native to the plane of existence you''re on, you banish the target to a harmless demiplane. While there, the target is incapacitated. The target remains there until the spell ends, at which point the target reappears in the space it left or in the nearest unoccupied space if that space is occupied.","If the target is native to a different plane of existence than the one you''re on, the target is banished with a faint popping noise, returning to its home plane. If the spell ends before 1 minute has passed, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied. Otherwise, the target doesn''t return."],"higher_level":["When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th."],"range":"60 feet","components":["V","S","M"],"material":"An item distasteful to the target.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"none"},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/banishment","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-barkskin', 'spell', 'Barkskin', 'spell-barkskin', '{"higher_level":[],"index":"barkskin","name":"Barkskin","desc":["You touch a willing creature. Until the spell ends, the target''s skin has a rough, bark-like appearance, and the target''s AC can''t be less than 16, regardless of what kind of armor it is wearing."],"range":"Touch","components":["V","S","M"],"material":"A handful of oak bark.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/barkskin","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-beacon-of-hope', 'spell', 'Beacon of Hope', 'spell-beacon-of-hope', '{"higher_level":[],"index":"beacon-of-hope","name":"Beacon of Hope","desc":["This spell bestows hope and vitality. Choose any number of creatures within range. For the duration, each target has advantage on wisdom saving throws and death saving throws, and regains the maximum number of hit points possible from any healing."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"life","name":"Life","url":"/api/2014/subclasses/life"},{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"url":"/api/2014/spells/beacon-of-hope","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-bestow-curse', 'spell', 'Bestow Curse', 'spell-bestow-curse', '{"index":"bestow-curse","name":"Bestow Curse","desc":["You touch a creature, and that creature must succeed on a wisdom saving throw or become cursed for the duration of the spell. When you cast this spell, choose the nature of the curse from the following options:","- Choose one ability score. While cursed, the target has disadvantage on ability checks and saving throws made with that ability score.","- While cursed, the target has disadvantage on attack rolls against you.","- While cursed, the target must make a wisdom saving throw at the start of each of its turns. If it fails, it wastes its action that turn doing nothing.","- While the target is cursed, your attacks and spells deal an extra 1d8 necrotic damage to the target.","A remove curse spell ends this effect. At the GM''s option, you may choose an alternative curse effect, but it should be no more powerful than those described above. The GM has final say on such a curse''s effect."],"higher_level":["If you cast this spell using a spell slot of 4th level or higher, the duration is concentration, up to 10 minutes. If you use a spell slot of 5th level or higher, the duration is 8 hours. If you use a spell slot of 7th level or higher, the duration is 24 hours. If you use a 9th level spell slot, the spell lasts until it is dispelled. Using a spell slot of 5th level or higher grants a duration that doesn''t require concentration."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none","desc":"On fail, become cursed for the duration of the spell."},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/bestow-curse","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-black-tentacles', 'spell', 'Black Tentacles', 'spell-black-tentacles', '{"higher_level":[],"index":"black-tentacles","name":"Black Tentacles","desc":["Squirming, ebony tentacles fill a 20-foot square on ground that you can see within range. For the duration, these tentacles turn the ground in the area into difficult terrain.","When a creature enters the affected area for the first time on a turn or starts its turn there, the creature must succeed on a Dexterity saving throw or take 3d6 bludgeoning damage and be restrained by the tentacles until the spell ends. A creature that starts its turn in the area and is already restrained by the tentacles takes 3d6 bludgeoning damage.","A creature restrained by the tentacles can use its action to make a Strength or Dexterity check (its choice) against your spell save DC. On a success, it frees itself."],"range":"90 feet","components":["V","S","M"],"material":"A piece of tentacle from a giant octopus or a giant squid","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_at_slot_level":{"4":"3d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"none","desc":"A creature restrained by the tentacles can use its action to make a Strength or Dexterity check (its choice) against your spell save DC. On a success, it frees itself."},"area_of_effect":{"type":"cube","size":20},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/black-tentacles","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-blade-barrier', 'spell', 'Blade Barrier', 'spell-blade-barrier', '{"higher_level":[],"index":"blade-barrier","name":"Blade Barrier","desc":["You create a vertical wall of whirling, razor-sharp blades made of magical energy. The wall appears within range and lasts for the duration. You can make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides three-quarters cover to creatures behind it, and its space is difficult terrain.","When a creature enters the wall''s area for the first time on a turn or starts its turn there, the creature must make a dexterity saving throw. On a failed save, the creature takes 6d10 slashing damage. On a successful save, the creature takes half as much damage."],"range":"90 feet","components":["V","S"],"ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_at_slot_level":{"6":"6d10"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"line","size":100},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/blade-barrier","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-bless', 'spell', 'Bless', 'spell-bless', '{"index":"bless","name":"Bless","desc":["You bless up to three creatures of your choice within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target can roll a d4 and add the number rolled to the attack roll or saving throw."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st."],"range":"30 feet","components":["V","S","M"],"material":"A sprinkling of holy water.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":1,"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"life","name":"Life","url":"/api/2014/subclasses/life"}],"url":"/api/2014/spells/bless","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-blight', 'spell', 'Blight', 'spell-blight', '{"index":"blight","name":"Blight","desc":["Necromantic energy washes over a creature of your choice that you can see within range, draining moisture and vitality from it. The target must make a constitution saving throw. The target takes 8d8 necrotic damage on a failed save, or half as much damage on a successful one. The spell has no effect on undead or constructs.","If you target a plant creature or a magical plant, it makes the saving throw with disadvantage, and the spell deals maximum damage to it.","If you target a nonmagical plant that isn''t a creature, such as a tree or shrub, it doesn''t make a saving throw; it simply withers and dies."],"higher_level":["When you cast this spell using a spell slot of 5th level of higher, the damage increases by 1d8 for each slot level above 4th."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_at_slot_level":{"4":"8d8","5":"9d8","6":"10d8","7":"11d8","8":"12d8","9":"13d8"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/blight","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-blindness-deafness', 'spell', 'Blindness/Deafness', 'spell-blindness-deafness', '{"index":"blindness-deafness","name":"Blindness/Deafness","desc":["You can blind or deafen a foe. Choose one creature that you can see within range to make a constitution saving throw. If it fails, the target is either blinded or deafened (your choice) for the duration. At the end of each of its turns, the target can make a constitution saving throw. On a success, the spell ends."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."],"range":"30 feet","components":["V"],"ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":2,"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"none"},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/blindness-deafness","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-blink', 'spell', 'Blink', 'spell-blink', '{"higher_level":[],"index":"blink","name":"Blink","desc":["Roll a d20 at the end of each of your turns for the duration of the spell. On a roll of 11 or higher, you vanish from your current plane of existence and appear in the Ethereal Plane (the spell fails and the casting is wasted if you were already on that plane). At the start of your next turn, and when the spell ends if you are on the Ethereal Plane, you return to an unoccupied space of your choice that you can see within 10 feet of the space you vanished from. If no unoccupied space is available within that range, you appear in the nearest unoccupied space (chosen at random if more than one space is equally near). You can dismiss this spell as an action.","While on the Ethereal Plane, you can see and hear the plane you originated from, which is cast in shades of gray, and you can''t see anything there more than 60 feet away. You can only affect and be affected by other creatures on the Ethereal Plane. Creatures that aren''t there can''t perceive you or interact with you, unless they have the ability to do so."],"range":"Self","components":["V","S"],"ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/blink","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-blur', 'spell', 'Blur', 'spell-blur', '{"higher_level":[],"index":"blur","name":"Blur","desc":["Your body becomes blurred, shifting and wavering to all who can see you. For the duration, any creature has disadvantage on attack rolls against you. An attacker is immune to this effect if it doesn''t rely on sight, as with blindsight, or can see through illusions, as with truesight."],"range":"Self","components":["V"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/blur","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-branding-smite', 'spell', 'Branding Smite', 'spell-branding-smite', '{"index":"branding-smite","name":"Branding Smite","desc":["The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it''s invisible, and the target sheds dim light in a 5-foot radius and can''t become invisible until the spell ends."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd."],"range":"Self","components":["V"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 bonus action","level":2,"damage":{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_at_slot_level":{"2":"2d6","3":"3d6","4":"4d6","5":"5d6","6":"6d6","7":"7d6","8":"8d6","9":"9d6"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[],"url":"/api/2014/spells/branding-smite","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-burning-hands', 'spell', 'Burning Hands', 'spell-burning-hands', '{"index":"burning-hands","name":"Burning Hands","desc":["As you hold your hands with thumbs touching and fingers spread, a thin sheet of flames shoots forth from your outstretched fingertips. Each creature in a 15-foot cone must make a dexterity saving throw. A creature takes 3d6 fire damage on a failed save, or half as much damage on a successful one.","The fire ignites any flammable objects in the area that aren''t being worn or carried."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":1,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"1":"3d6","2":"4d6","3":"5d6","4":"6d6","5":"7d6","6":"8d6","7":"9d6","8":"10d6","9":"11d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"cone","size":15},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/burning-hands","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-call-lightning', 'spell', 'Call Lightning', 'spell-call-lightning', '{"index":"call-lightning","name":"Call Lightning","desc":["A storm cloud appears in the shape of a cylinder that is 10 feet tall with a 60-foot radius, centered on a point you can see 100 feet directly above you. The spell fails if you can''t see a point in the air where the storm cloud could appear (for example, if you are in a room that can''t accommodate the cloud).","When you cast the spell, choose a point you can see within range. A bolt of lightning flashes down from the cloud to that point. Each creature within 5 feet of that point must make a dexterity saving throw. A creature takes 3d10 lightning damage on a failed save, or half as much damage on a successful one. On each of your turns until the spell ends, you can use your action to call down lightning in this way again, targeting the same point or a different one.","If you are outdoors in stormy conditions when you cast this spell, the spell gives you control over the existing storm instead of creating a new one. Under such conditions, the spell''s damage increases by 1d10."],"higher_level":["When you cast this spell using a spell slot of 4th or higher level, the damage increases by 1d10 for each slot level above 3rd."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":3,"damage":{"damage_type":{"index":"lightning","name":"Lightning","url":"/api/2014/damage-types/lightning"},"damage_at_slot_level":{"3":"3d10","4":"4d10","5":"5d10","6":"6d10","7":"7d10","8":"8d10","9":"9d10"}},"area_of_effect":{"type":"sphere","size":5},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/call-lightning","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-calm-emotions', 'spell', 'Calm Emotions', 'spell-calm-emotions', '{"higher_level":[],"index":"calm-emotions","name":"Calm Emotions","desc":["You attempt to suppress strong emotions in a group of people. Each humanoid in a 20-foot-radius sphere centered on a point you choose within range must make a charisma saving throw; a creature can choose to fail this saving throw if it wishes. If a creature fails its saving throw, choose one of the following two effects. You can suppress any effect causing a target to be charmed or frightened. When this spell ends, any suppressed effect resumes, provided that its duration has not expired in the meantime.","Alternatively, you can make a target indifferent about creatures of your choice that it is hostile toward. This indifference ends if the target is attacked or harmed by a spell or if it witnesses any of its friends being harmed. When the spell ends, the creature becomes hostile again, unless the GM rules otherwise."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"none"},"area_of_effect":{"type":"sphere","size":20},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/calm-emotions","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-chain-lightning', 'spell', 'Chain Lightning', 'spell-chain-lightning', '{"index":"chain-lightning","name":"Chain Lightning","desc":["You create a bolt of lightning that arcs toward a target of your choice that you can see within range. Three bolts then leap from that target to as many as three other targets, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts.","A target must make a dexterity saving throw. The target takes 10d8 lightning damage on a failed save, or half as much damage on a successful one."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, one additional bolt leaps from the first target to another target for each slot level above 6th."],"range":"150 feet","components":["V","S","M"],"material":"A bit of fur; a piece of amber, glass, or a crystal rod; and three silver pins.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"lightning","name":"Lightning","url":"/api/2014/damage-types/lightning"},"damage_at_slot_level":{"6":"10d8"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/chain-lightning","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-charm-person', 'spell', 'Charm Person', 'spell-charm-person', '{"index":"charm-person","name":"Charm Person","desc":["You attempt to charm a humanoid you can see within range. It must make a wisdom saving throw, and does so with advantage if you or your companions are fighting it. If it fails the saving throw, it is charmed by you until the spell ends or until you or your companions do anything harmful to it. The charmed creature regards you as a friendly acquaintance. When the spell ends, the creature knows it was charmed by you."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":1,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/charm-person","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-chill-touch', 'spell', 'Chill Touch', 'spell-chill-touch', '{"higher_level":[],"index":"chill-touch","name":"Chill Touch","desc":["You create a ghostly, skeletal hand in the space of a creature within range. Make a ranged spell attack against the creature to assail it with the chill of the grave. On a hit, the target takes 1d8 necrotic damage, and it can''t regain hit points until the start of your next turn. Until then, the hand clings to the target.","If you hit an undead target, it also has disadvantage on attack rolls against you until the end of your next turn.","This spell''s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 action","level":0,"attack_type":"ranged","damage":{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_at_character_level":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/chill-touch","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-circle-of-death', 'spell', 'Circle of Death', 'spell-circle-of-death', '{"index":"circle-of-death","name":"Circle of Death","desc":["A sphere of negative energy ripples out in a 60-foot radius sphere from a point within range. Each creature in that area must make a constitution saving throw. A target takes 8d6 necrotic damage on a failed save, or half as much damage on a successful one."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, the damage increases by 2d6 for each slot level above 6th."],"range":"150 feet","components":["V","S","M"],"material":"The powder of a crushed black pearl worth at least 500 gp.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_at_slot_level":{"6":"8d6","7":"10d6","8":"12d6","9":"14d6"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":60},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/circle-of-death","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-clairvoyance', 'spell', 'Clairvoyance', 'spell-clairvoyance', '{"higher_level":[],"index":"clairvoyance","name":"Clairvoyance","desc":["You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The sensor remains in place for the duration, and it can''t be attacked or otherwise interacted with.","When you cast the spell, you choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As your action, you can switch between seeing and hearing.","A creature that can see the sensor (such as a creature benefiting from see invisibility or truesight) sees a luminous, intangible orb about the size of your fist."],"range":"1 mile","components":["V","S","M"],"material":"A focus worth at least 100gp, either a jeweled horn for hearing or a glass eye for seeing.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"10 minutes","level":3,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/clairvoyance","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-clone', 'spell', 'Clone', 'spell-clone', '{"higher_level":[],"index":"clone","name":"Clone","desc":["This spell grows an inert duplicate of a living creature as a safeguard against death. This clone forms inside a sealed vessel and grows to full size and maturity after 120 days; you can also choose to have the clone be a younger version of the same creature. It remains inert and endures indefinitely, as long as its vessel remains undisturbed.","At any time after the clone matures, if the original creature dies, its soul transfers to the clone, provided that the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original''s equipment. The original creature''s physical remains, if they still exist, become inert and can''t thereafter be restored to life, since the creature''s soul is elsewhere."],"range":"Touch","components":["V","S","M"],"material":"A diamond worth at least 1,000 gp and at least 1 cubic inch of flesh of the creature that is to be cloned, which the spell consumes, and a vessel worth at least 2,000 gp that has a sealable lid and is large enough to hold a Medium creature, such as a huge urn, coffin, mud-filled cyst in the ground, or crystal container filled with salt water.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 hour","level":8,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/clone","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-cloudkill', 'spell', 'Cloudkill', 'spell-cloudkill', '{"index":"cloudkill","name":"Cloudkill","desc":["You create a 20-foot-radius sphere of poisonous, yellow-green fog centered on a point you choose within range. The fog spreads around corners. It lasts for the duration or until strong wind disperses the fog, ending the spell. Its area is heavily obscured.","When a creature enters the spell''s area for the first time on a turn or starts its turn there, that creature must make a constitution saving throw. The creature takes 5d8 poison damage on a failed save, or half as much damage on a successful one. Creatures are affected even if they hold their breath or don''t need to breathe.","The fog moves 10 feet away from you at the start of each of your turns, rolling along the surface of the ground. The vapors, being heavier than air, sink to the lowest level of the land, even pouring down openings."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":5,"damage":{"damage_type":{"index":"poison","name":"Poison","url":"/api/2014/damage-types/poison"},"damage_at_slot_level":{"5":"5d8","6":"6d8","7":"7d8","8":"8d8","9":"9d8"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half","desc":"Creatures are affected even if they hold their breath or don''t need to breathe."},"area_of_effect":{"type":"sphere","size":20},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/cloudkill","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-color-spray', 'spell', 'Color Spray', 'spell-color-spray', '{"index":"color-spray","name":"Color Spray","desc":["A dazzling array of flashing, colored light springs from your hand. Roll 6d10; the total is how many hit points of creatures this spell can effect. Creatures in a 15-foot cone originating from you are affected in ascending order of their current hit points (ignoring unconscious creatures and creatures that can''t see).","Starting with the creature that has the lowest current hit points, each creature affected by this spell is blinded until the spell ends. Subtract each creature''s hit points from the total before moving on to the creature with the next lowest hit points. A creature''s hit points must be equal to or less than the remaining total for that creature to be affected."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d10 for each slot level above 1st."],"range":"Self","components":["V","S","M"],"material":"A pinch of powder or sand that is colored red, yellow, and blue.","ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 action","level":1,"area_of_effect":{"type":"cone","size":15},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/color-spray","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-command', 'spell', 'Command', 'spell-command', '{"index":"command","name":"Command","desc":["You speak a one-word command to a creature you can see within range. The target must succeed on a wisdom saving throw or follow the command on its next turn. The spell has no effect if the target is undead, if it doesn''t understand your language, or if your command is directly harmful to it.","Some typical commands and their effects follow. You might issue a command other than one described here. If you do so, the GM determines how the target behaves. If the target can''t follow your command, the spell ends.","***Approach.*** The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you.","***Drop.*** The target drops whatever it is holding and then ends its turn.","***Flee.*** The target spends its turn moving away from you by the fastest available means.","***Grovel.*** The target falls prone and then ends its turn.","***Halt.*** The target doesn''t move and takes no actions. A flying creature stays aloft, provided that it is able to do so. If it must move to stay aloft, it flies the minimum distance needed to remain in the air."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them."],"range":"60 feet","components":["V"],"ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 action","level":1,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/command","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-commune', 'spell', 'Commune', 'spell-commune', '{"higher_level":[],"index":"commune","name":"Commune","desc":["You contact your deity or a divine proxy and ask up to three questions that can be answered with a yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question.","Divine beings aren''t necessarily omniscient, so you might receive \"unclear\" as an answer if a question pertains to information that lies beyond the deity''s knowledge. In a case where a one-word answer could be misleading or contrary to the deity''s interests, the GM might offer a short phrase as an answer instead.","If you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer. The GM makes this roll in secret."],"range":"Self","components":["V","S","M"],"material":"Incense and a vial of holy or unholy water.","ritual":true,"duration":"1 minute","concentration":false,"casting_time":"1 minute","level":5,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"url":"/api/2014/spells/commune","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-commune-with-nature', 'spell', 'Commune With Nature', 'spell-commune-with-nature', '{"higher_level":[],"index":"commune-with-nature","name":"Commune With Nature","desc":["You briefly become one with nature and gain knowledge of the surrounding territory. In the outdoors, the spell gives you knowledge of the land within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn''t function where nature has been replaced by construction, such as in dungeons and towns.","You instantly gain knowledge of up to three facts of your choice about any of the following subjects as they relate to the area:","- terrain and bodies of water","- prevalent plants, minerals, animals, or peoples","- powerful celestials, fey, fiends, elementals, or undead","- influence from other planes of existence","- buildings","For example, you could determine the location of powerful undead in the area, the location of major sources of safe drinking water, and the location of any nearby towns."],"range":"Self","components":["V","S"],"ritual":true,"duration":"Instantaneous","concentration":false,"casting_time":"1 minute","level":5,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/commune-with-nature","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-comprehend-languages', 'spell', 'Comprehend Languages', 'spell-comprehend-languages', '{"higher_level":[],"index":"comprehend-languages","name":"Comprehend Languages","desc":["For the duration, you understand the literal meaning of any spoken language that you hear. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text.","This spell doesn''t decode secret messages in a text or a glyph, such as an arcane sigil, that isn''t part of a written language."],"range":"Self","components":["V","S","M"],"material":"A pinch of soot and salt.","ritual":true,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/comprehend-languages","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-compulsion', 'spell', 'Compulsion', 'spell-compulsion', '{"higher_level":[],"index":"compulsion","name":"Compulsion","desc":["Creatures of your choice that you can see within range and that can hear you must make a wisdom saving throw. A target automatically succeeds on this saving throw if it can''t be charmed. On a failed save, a target is affected by this spell. Until the spell ends, you can use a bonus action on each of your turns to designate a direction that is horizontal to you. Each affected target must use as much of its movement as possible to move in that direction on its next turn. It can take any action before it moves. After moving in this way, it can make another Wisdom save to try to end the effect.","A target isn''t compelled to move into an obviously deadly hazard, such as a fire or a pit, but it will provoke opportunity attacks to move in the designated direction."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"}],"subclasses":[],"url":"/api/2014/spells/compulsion","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-cone-of-cold', 'spell', 'Cone of Cold', 'spell-cone-of-cold', '{"index":"cone-of-cold","name":"Cone of Cold","desc":["A blast of cold air erupts from your hands. Each creature in a 60-foot cone must make a constitution saving throw. A creature takes 8d8 cold damage on a failed save, or half as much damage on a successful one.","A creature killed by this spell becomes a frozen statue until it thaws."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."],"range":"Self","components":["V","S","M"],"material":"A small crystal or glass cone.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":5,"damage":{"damage_type":{"index":"cold","name":"Cold","url":"/api/2014/damage-types/cold"},"damage_at_slot_level":{"5":"8d8","6":"9d8","7":"10d8","8":"11d8","9":"12d8"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half","desc":"A creature killed by this spell becomes a frozen statue until it thaws."},"area_of_effect":{"type":"cone","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/cone-of-cold","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-confusion', 'spell', 'Confusion', 'spell-confusion', '{"index":"confusion","name":"Confusion","desc":["This spell assaults and twists creatures'' minds, spawning delusions and provoking uncontrolled action. Each creature in a 10-foot-radius sphere centered on a point you choose within range must succeed on a Wisdom saving throw when you cast this spell or be affected by it.","An affected target can''t take reactions and must roll a d10 at the start of each of its turns to determine its behavior for that turn.","| d10 | Behavior |","|---|---|","| 1 | The creature uses all its movement to move in a random direction. To determine the direction, roll a d8 and assign a direction to each die face. The creature doesn''t take an action this turn. |","| 2-6 | The creature doesn''t move or take actions this turn. |","| 7-8 | The creature uses its action to make a melee attack against a randomly determined creature within its reach. If there is no creature within its reach, the creature does nothing this turn. |","| 9-10 | The creature can act and move normally. |","At the end of each of its turns, an affected target can make a Wisdom saving throw. If it succeeds, this effect ends for that target."],"higher_level":["When you cast this spell using a spell slot of 5th level or higher, the radius of the sphere increases by 5 feet for each slot level above 4th."],"range":"90 feet","components":["V","S","M"],"material":"Three walnut shells.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"area_of_effect":{"type":"sphere","size":10},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/confusion","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-conjure-animals', 'spell', 'Conjure Animals', 'spell-conjure-animals', '{"index":"conjure-animals","name":"Conjure Animals","desc":["You summon fey spirits that take the form of beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:","- One beast of challenge rating 2 or lower","- Two beasts of challenge rating 1 or lower","- Four beasts of challenge rating 1/2 or lower","- Eight beasts of challenge rating 1/4 or lower","- Each beast is also considered fey, and it disappears when it drops to 0 hit points or when the spell ends.","The summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don''t issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.","The GM has the creatures'' statistics."],"higher_level":["When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 5th-level slot, three times as many with a 7th-level."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":3,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/conjure-animals","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-conjure-celestial', 'spell', 'Conjure Celestial', 'spell-conjure-celestial', '{"index":"conjure-celestial","name":"Conjure Celestial","desc":["You summon a celestial of challenge rating 4 or lower, which appears in an unoccupied space that you can see within range. The celestial disappears when it drops to 0 hit points or when the spell ends.","The celestial is friendly to you and your companions for the duration. Roll initiative for the celestial, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don''t violate its alignment. If you don''t issue any commands to the celestial, it defends itself from hostile creatures but otherwise takes no actions.","The GM has the celestial''s statistics."],"higher_level":["When you cast this spell using a 9th-level spell slot, you summon a celestial of challenge rating 5 or lower."],"range":"90 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 minute","level":7,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/conjure-celestial","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-conjure-elemental', 'spell', 'Conjure Elemental', 'spell-conjure-elemental', '{"index":"conjure-elemental","name":"Conjure Elemental","desc":["You call forth an elemental servant. Choose an area of air, earth, fire, or water that fills a 10-foot cube within range. An elemental of challenge rating 5 or lower appropriate to the area you chose appears in an unoccupied space within 10 feet of it. For example, a fire elemental emerges from a bonfire, and an earth elemental rises up from the ground. The elemental disappears when it drops to 0 hit points or when the spell ends.","The elemental is friendly to you and your companions for the duration. Roll initiative for the elemental, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don''t issue any commands to the elemental, it defends itself from hostile creatures but otherwise takes no actions.","If your concentration is broken, the elemental doesn''t disappear. Instead, you lose control of the elemental, it becomes hostile toward you and your companions, and it might attack. An uncontrolled elemental can''t be dismissed by you, and it disappears 1 hour after you summoned it.","The GM has the elemental''s statistics."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the challenge rating increases by 1 for each slot level above 5th."],"range":"90 feet","components":["V","S","M"],"material":"Burning incense for air, soft clay for earth, sulfur and phosphorus for fire, or water and sand for water.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 minute","level":5,"area_of_effect":{"type":"cube","size":10},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/conjure-elemental","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-conjure-fey', 'spell', 'Conjure Fey', 'spell-conjure-fey', '{"index":"conjure-fey","name":"Conjure Fey","desc":["You summon a fey creature of challenge rating 6 or lower, or a fey spirit that takes the form of a beast of challenge rating 6 or lower. It appears in an unoccupied space that you can see within range. The fey creature disappears when it drops to 0 hit points or when the spell ends.","The fey creature is friendly to you and your companions for the duration. Roll initiative for the creature, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don''t violate its alignment. If you don''t issue any commands to the fey creature, it defends itself from hostile creatures but otherwise takes no actions.","If your concentration is broken, the fey creature doesn''t disappear. Instead, you lose control of the fey creature, it becomes hostile toward you and your companions, and it might attack. An uncontrolled fey creature can''t be dismissed by you, and it disappears 1 hour after you summoned it.","The GM has the fey creature''s statistics."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, the challenge rating increases by 1 for each slot level above 6th."],"range":"90 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 minute","level":6,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"}],"subclasses":[],"url":"/api/2014/spells/conjure-fey","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-conjure-minor-elementals', 'spell', 'Conjure Minor Elementals', 'spell-conjure-minor-elementals', '{"index":"conjure-minor-elementals","name":"Conjure Minor Elementals","desc":["You summon elementals that appear in unoccupied spaces that you can see within range. You choose one the following options for what appears:","- One elemental of challenge rating 2 or lower","- Two elementals of challenge rating 1 or lower","- Four elementals of challenge rating 1/2 or lower","- Eight elementals of challenge rating 1/4 or lower.","An elemental summoned by this spell disappears when it drops to 0 hit points or when the spell ends.","The summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don''t issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.","The GM has the creatures'' statistics."],"higher_level":["When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot."],"range":"90 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 minute","level":4,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/conjure-minor-elementals","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-conjure-woodland-beings', 'spell', 'Conjure Woodland Beings', 'spell-conjure-woodland-beings', '{"index":"conjure-woodland-beings","name":"Conjure Woodland Beings","desc":["You summon fey creatures that appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:","- One fey creature of challenge rating 2 or lower","- Two fey creatures of challenge rating 1 or lower","- Four fey creatures of challenge rating 1/2 or lower","- Eight fey creatures of challenge rating 1/4 or lower","A summoned creature disappears when it drops to 0 hit points or when the spell ends.","The summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which have their own turns. They obey any verbal commands that you issue to them (no action required by you). If you don''t issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.","The GM has the creatures'' statistics."],"higher_level":["When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot."],"range":"60 feet","components":["V","S","M"],"material":"One holly berry per creature summoned.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":4,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[],"url":"/api/2014/spells/conjure-woodland-beings","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-contact-other-plane', 'spell', 'Contact Other Plane', 'spell-contact-other-plane', '{"higher_level":[],"index":"contact-other-plane","name":"Contact Other Plane","desc":["You mentally contact a demigod, the spirit of a long-dead sage, or some other mysterious entity from another plane. Contacting this extraplanar intelligence can strain or even break your mind. When you cast this spell, make a DC 15 intelligence saving throw. On a failure, you take 6d6 psychic damage and are insane until you finish a long rest. While insane, you can''t take actions, can''t understand what other creatures say, can''t read, and speak only in gibberish. A greater restoration spell cast on you ends this effect.","On a successful save, you can ask the entity up to five questions. You must ask your questions before the spell ends. The GM answers each question with one word, such as \"yes,\" \"no,\" \"maybe,\" \"never,\" \"irrelevant,\" or \"unclear\" (if the entity doesn''t know the answer to the question). If a one-word answer would be misleading, the GM might instead offer a short phrase as an answer."],"range":"Self","components":["V"],"ritual":true,"duration":"1 minute","concentration":false,"casting_time":"1 minute","level":5,"dc":{"dc_type":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"dc_success":"other","desc":"On a failure, you take 6d6 psychic damage and are insane until you finish a long rest."},"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/contact-other-plane","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-contagion', 'spell', 'Contagion', 'spell-contagion', '{"higher_level":[],"index":"contagion","name":"Contagion","desc":["Your touch inflicts disease. Make a melee spell attack against a creature within your reach. On a hit, you afflict the creature with a disease of your choice from any of the ones described below.","At the end of each of the target''s turns, it must make a constitution saving throw. After failing three of these saving throws, the disease''s effects last for the duration, and the creature stops making these saves. After succeeding on three of these saving throws, the creature recovers from the disease, and the spell ends.","Since this spell induces a natural disease in its target, any effect that removes a disease or otherwise ameliorates a disease''s effects apply to it.","***Blinding Sickness.*** Pain grips the creature''s mind, and its eyes turn milky white. The creature has disadvantage on wisdom checks and wisdom saving throws and is blinded.","***Filth Fever.*** A raging fever sweeps through the creature''s body. The creature has disadvantage on strength checks, strength saving throws, and attack rolls that use Strength.","***Flesh Rot.*** The creature''s flesh decays. The creature has disadvantage on Charisma checks and vulnerability to all damage.","***Mindfire.*** The creature''s mind becomes feverish. The creature has disadvantage on intelligence checks and intelligence saving throws, and the creature behaves as if under the effects of the confusion spell during combat.","***Seizure.*** The creature is overcome with shaking. The creature has disadvantage on dexterity checks, dexterity saving throws, and attack rolls that use Dexterity.","***Slimy Doom.*** The creature begins to bleed uncontrollably. The creature has disadvantage on constitution checks and constitution saving throws. In addition, whenever the creature takes damage, it is stunned until the end of its next turn."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"7 days","concentration":false,"casting_time":"1 action","level":5,"attack_type":"melee","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"other","desc":"After succeeding on three of these saving throws, the creature recovers from the disease, and the spell ends."},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/contagion","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-contingency', 'spell', 'Contingency', 'spell-contingency', '{"higher_level":[],"index":"contingency","name":"Contingency","desc":["Choose a spell of 5th level or lower that you can cast, that has a casting time of 1 action, and that can target you. You cast that spell--called the contingent spell--as part of casting contingency, expending spell slots for both, but the contingent spell doesn''t come into effect. Instead, it takes effect when a certain circumstance occurs. You describe that circumstance when you cast the two spells. For example, a contingency cast with water breathing might stipulate that water breathing comes into effect when you are engulfed in water or a similar liquid.","The contingent spell takes effect immediately after the circumstance is met for the first time, whether or not you want it to. and then contingency ends.","The contingent spell takes effect only on you, even if it can normally target others. You can use only one contingency spell at a time. If you cast this spell again, the effect of another contingency spell on you ends. Also, contingency ends on you if its material component is ever not on your person."],"range":"Self","components":["V","S","M"],"material":"A statuette of yourself carved from ivory and decorated with gems worth at least 1,500 gp.","ritual":false,"duration":"10 days","concentration":false,"casting_time":"10 minutes","level":6,"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/contingency","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-continual-flame', 'spell', 'Continual Flame', 'spell-continual-flame', '{"higher_level":[],"index":"continual-flame","name":"Continual Flame","desc":["A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn''t use oxygen. A continual flame can be covered or hidden but not smothered or quenched."],"range":"Touch","components":["V","S","M"],"material":"Ruby dust worth 50 gp, which the spell consumes.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/continual-flame","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-control-water', 'spell', 'Control Water', 'spell-control-water', '{"higher_level":[],"index":"control-water","name":"Control Water","desc":["Until the spell ends, you control any freestanding water inside an area you choose that is a cube up to 100 feet on a side. You can choose from any of the following effects when you cast this spell. As an action on your turn, you can repeat the same effect or choose a different one.","***Flood.*** You cause the water level of all standing water in the area to rise by as much as 20 feet. If the area includes a shore, the flooding water spills over onto dry land.","If you choose an area in a large body of water, you instead create a 20-foot tall wave that travels from one side of the area to the other and then crashes down. Any Huge or smaller vehicles in the wave''s path are carried with it to the other side. Any Huge or smaller vehicles struck by the wave have a 25 percent chance of capsizing.","The water level remains elevated until the spell ends or you choose a different effect. If this effect produced a wave, the wave repeats on the start of your next turn while the flood effect lasts.","***Part Water.*** You cause water in the area to move apart and create a trench. The trench extends across the spell''s area, and the separated water forms a wall to either side. The trench remains until the spell ends or you choose a different effect. The water then slowly fills in the trench over the course of the next round until the normal water level is restored.","***Redirect Flow.*** You cause flowing water in the area to move in a direction you choose, even if the water has to flow over obstacles, up walls, or in other unlikely directions. The water in the area moves as you direct it, but once it moves beyond the spell''s area, it resumes its flow based on the terrain conditions. The water continues to move in the direction you chose until the spell ends or you choose a different effect.","***Whirlpool.*** This effect requires a body of water at least 50 feet square and 25 feet deep. You cause a whirlpool to form in the center of the area. The whirlpool forms a vortex that is 5 feet wide at the base, up to 50 feet wide at the top, and 25 feet tall. Any creature or object in the water and within 25 feet of the vortex is pulled 10 feet toward it. A creature can swim away from the vortex by making a Strength (Athletics) check against your spell save DC.","When a creature enters the vortex for the first time on a turn or starts its turn there, it must make a strength saving throw. On a failed save, the creature takes 2d8 bludgeoning damage and is caught in the vortex until the spell ends. On a successful save, the creature takes half damage, and isn''t caught in the vortex. A creature caught in the vortex can use its action to try to swim away from the vortex as described above, but has disadvantage on the Strength (Athletics) check to do so.","The first time each turn that an object enters the vortex, the object takes 2d8 bludgeoning damage; this damage occurs each round it remains in the vortex."],"range":"300 feet","components":["V","S","M"],"material":"A drop of water and a pinch of dust.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_at_slot_level":{"4":"2d8"}},"dc":{"dc_type":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"dc_success":"half"},"area_of_effect":{"type":"cube","size":100},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/control-water","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-control-weather', 'spell', 'Control Weather', 'spell-control-weather', '{"higher_level":[],"index":"control-weather","name":"Control Weather","desc":["You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell. Moving to a place where you don''t have a clear path to the sky ends the spell early.","When you cast the spell, you change the current weather conditions, which are determined by the GM based on the climate and season. You can change precipitation, temperature, and wind. It takes 1d4 x 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal.","When you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction.","##### Precipitation","| Stage | Condition |","|---|---|","| 1 | Clear |","| 2 | Light clouds |","| 3 | Overcast or ground fog |","| 4 | Rain, hail, or snow |","| 5 | Torrential rain, driving hail, or blizzard |","##### Temperature","| Stage | Condition |","|---|---|","| 1 | Unbearable heat |","| 2 | Hot |","| 3 | Warm |","| 4 | Cool |","| 5 | Cold |","| 6 | Arctic cold |","##### Wind","| Stage | Condition |","|---|---|","| 1 | Calm |","| 2 | Moderate wind |","| 3 | Strong wind |","| 4 | Gale |","| 5 | Storm |"],"range":"Self","components":["V","S","M"],"material":"Burning incense and bits of earth and wood mixed in water.","ritual":false,"duration":"Up to 8 hours","concentration":true,"casting_time":"10 minutes","level":8,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/control-weather","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-counterspell', 'spell', 'Counterspell', 'spell-counterspell', '{"index":"counterspell","name":"Counterspell","desc":["You attempt to interrupt a creature in the process of casting a spell. If the creature is casting a spell of 3rd level or lower, its spell fails and has no effect. If it is casting a spell of 4th level or higher, make an ability check using your spellcasting ability. The DC equals 10 + the spell''s level. On a success, the creature''s spell fails and has no effect."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the interrupted spell has no effect if its level is less than or equal to the level of the spell slot you used."],"range":"60 feet","components":["S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 reaction","level":3,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/counterspell","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-create-food-and-water', 'spell', 'Create Food and Water', 'spell-create-food-and-water', '{"higher_level":[],"index":"create-food-and-water","name":"Create Food and Water","desc":["You create 45 pounds of food and 30 gallons of water on the ground or in containers within range, enough to sustain up to fifteen humanoids or five steeds for 24 hours. The food is bland but nourishing, and spoils if uneaten after 24 hours. The water is clean and doesn''t go bad."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/create-food-and-water","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-create-or-destroy-water', 'spell', 'Create or Destroy Water', 'spell-create-or-destroy-water', '{"index":"create-or-destroy-water","name":"Create or Destroy Water","desc":["You either create or destroy water.","***Create Water.*** You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot cube within range.","***Destroy Water.*** You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot cube within range."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, you create or destroy 10 additional gallons of water, or the size of the cube increases by 5 feet, for each slot level above 1st."],"range":"30 feet","components":["V","S","M"],"material":"A drop of water if creating water, or a few grains of sand if destroying it.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":1,"area_of_effect":{"type":"cube","size":30},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/create-or-destroy-water","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-create-undead', 'spell', 'Create Undead', 'spell-create-undead', '{"index":"create-undead","name":"Create Undead","desc":["You can cast this spell only at night. Choose up to three corpses of Medium or Small humanoids within range. Each corpse becomes a ghoul under your control. (The GM has game statistics for these creatures.)","As a bonus action on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.","The creature is under your control for 24 hours, after which it stops obeying any command you have given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell, rather than animating new ones."],"higher_level":["When you cast this spell using a 7th-level spell slot, you can animate or reassert control over four ghouls. When you cast this spell using an 8th-level spell slot, you can animate or reassert control over five ghouls or two ghasts or wights. When you cast this spell using a 9th-level spell slot, you can animate or reassert control over six ghouls, three ghasts or wights, or two mummies."],"range":"10 feet","components":["V","S","M"],"material":"One clay pot filled with grave dirt, one clay pot filled with brackish water, and one 150 gp black onyx stone for each corpse.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 minute","level":6,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/create-undead","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-creation', 'spell', 'Creation', 'spell-creation', '{"index":"creation","name":"Creation","desc":["You pull wisps of shadow material from the Shadowfell to create a nonliving object of vegetable matter within range: soft goods, rope, wood, or something similar. You can also use this spell to create mineral objects such as stone, crystal, or metal. The object created must be no larger than a 5-foot cube, and the object must be of a form and material that you have seen before.","The duration depends on the object''s material. If the object is composed of multiple materials, use the shortest duration.","| Material | Duration |","|---|---|","| Vegetable matter | 1 day |","| Stone or crystal | 12 hours |","| Precious metals | 1 hour |","| Gems | 10 minutes |","| Adamantine or mithral | 1 minute |","Using any material created by this spell as another spell''s material component causes that spell to fail."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the cube increases by 5 feet for each slot level above 5th."],"range":"30 feet","components":["V","S","M"],"material":"A tiny piece of matter of the same type of the item you plan to create.","ritual":false,"duration":"Special","concentration":false,"casting_time":"1 minute","level":5,"area_of_effect":{"type":"cube","size":5},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/creation","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-cure-wounds', 'spell', 'Cure Wounds', 'spell-cure-wounds', '{"index":"cure-wounds","name":"Cure Wounds","desc":["A creature you touch regains a number of hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d8 for each slot level above 1st."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":1,"heal_at_slot_level":{"1":"1d8 + MOD","2":"2d8 + MOD","3":"3d8 + MOD","4":"4d8 + MOD","5":"5d8 + MOD","6":"6d8 + MOD","7":"7d8 + MOD","8":"8d8 + MOD","9":"9d8 + MOD"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"life","name":"Life","url":"/api/2014/subclasses/life"}],"url":"/api/2014/spells/cure-wounds","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-dancing-lights', 'spell', 'Dancing Lights', 'spell-dancing-lights', '{"higher_level":[],"index":"dancing-lights","name":"Dancing Lights","desc":["You create up to four torch-sized lights within range, making them appear as torches, lanterns, or glowing orbs that hover in the air for the duration. You can also combine the four lights into one glowing vaguely humanoid form of Medium size. Whichever form you choose, each light sheds dim light in a 10-foot radius.","As a bonus action on your turn, you can move the lights up to 60 feet to a new spot within range. A light must be within 20 feet of another light created by this spell, and a light winks out if it exceeds the spell''s range."],"range":"120 feet","components":["V","S","M"],"material":"A bit of phosphorus or wychwood, or a glowworm.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":0,"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/dancing-lights","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-darkness', 'spell', 'Darkness', 'spell-darkness', '{"higher_level":[],"index":"darkness","name":"Darkness","desc":["Magical darkness spreads from a point you choose within range to fill a 15-foot-radius sphere for the duration. The darkness spreads around corners. A creature with darkvision can''t see through this darkness, and nonmagical light can''t illuminate it.","If the point you choose is on an object you are holding or one that isn''t being worn or carried, the darkness emanates from the object and moves with it. Completely covering the source of the darkness with an opaque object, such as a bowl or a helm, blocks the darkness.","If any of this spell''s area overlaps with an area of light created by a spell of 2nd level or lower, the spell that created the light is dispelled."],"range":"60 feet","components":["V","M"],"material":"Bat fur and a drop of pitch or piece of coal.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":2,"area_of_effect":{"type":"sphere","size":15},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/darkness","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-darkvision', 'spell', 'Darkvision', 'spell-darkvision', '{"higher_level":[],"index":"darkvision","name":"Darkvision","desc":["You touch a willing creature to grant it the ability to see in the dark. For the duration, that creature has darkvision out to a range of 60 feet."],"range":"Touch","components":["V","S","M"],"material":"Either a pinch of dried carrot or an agate.","ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/darkvision","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-daylight', 'spell', 'Daylight', 'spell-daylight', '{"higher_level":[],"index":"daylight","name":"Daylight","desc":["A 60-foot-radius sphere of light spreads out from a point you choose within range. The sphere is bright light and sheds dim light for an additional 60 feet.","If you chose a point on an object you are holding or one that isn''t being worn or carried, the light shines from the object and moves with it. Completely covering the affected object with an opaque object, such as a bowl or a helm, blocks the light.","If any of this spell''s area overlaps with an area of darkness created by a spell of 3rd level or lower, the spell that created the darkness is dispelled."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":3,"area_of_effect":{"type":"sphere","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/daylight","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-death-ward', 'spell', 'Death Ward', 'spell-death-ward', '{"higher_level":[],"index":"death-ward","name":"Death Ward","desc":["You touch a creature and grant it a measure of protection from death.","The first time the target would drop to 0 hit points as a result of taking damage, the target instead drops to 1 hit point, and the spell ends.","If the spell is still in effect when the target is subjected to an effect that would kill it instantaneously without dealing damage, that effect is instead negated against the target, and the spell ends."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":4,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"life","name":"Life","url":"/api/2014/subclasses/life"}],"url":"/api/2014/spells/death-ward","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-delayed-blast-fireball', 'spell', 'Delayed Blast Fireball', 'spell-delayed-blast-fireball', '{"index":"delayed-blast-fireball","name":"Delayed Blast Fireball","desc":["A beam of yellow light flashes from your pointing finger, then condenses to linger at a chosen point within range as a glowing bead for the duration. When the spell ends, either because your concentration is broken or because you decide to end it, the bead blossoms with a low roar into an explosion of flame that spreads around corners. Each creature in a 20-foot-radius sphere centered on that point must make a dexterity saving throw. A creature takes fire damage equal to the total accumulated damage on a failed save, or half as much damage on a successful one.","The spell''s base damage is 12d6. If at the end of your turn the bead has not yet detonated, the damage increases by 1d6.","If the glowing bead is touched before the interval has expired, the creature touching it must make a dexterity saving throw. On a failed save, the spell ends immediately, causing the bead to erupt in flame. On a successful save, the creature can throw the bead up to 40 feet. When it strikes a creature or a solid object, the spell ends, and the bead explodes.","The fire damages objects in the area and ignites flammable objects that aren''t being worn or carried."],"higher_level":["When you cast this spell using a spell slot of 8th level or higher, the base damage increases by 1d6 for each slot level above 7th."],"range":"150 feet","components":["V","S","M"],"material":"A tiny ball of bat guano and sulfur.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":7,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"7":"12d6","8":"13d6","9":"14d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":20},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/delayed-blast-fireball","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-demiplane', 'spell', 'Demiplane', 'spell-demiplane', '{"higher_level":[],"index":"demiplane","name":"Demiplane","desc":["You create a shadowy door on a flat solid surface that you can see within range. The door is large enough to allow Medium creatures to pass through unhindered. When opened, the door leads to a demiplane that appears to be an empty room 30 feet in each dimension, made of wood or stone. When the spell ends, the door disappears, and any creatures or objects inside the demiplane remain trapped there, as the door also disappears from the other side.","Each time you cast this spell, you can create a new demiplane, or have the shadowy door connect to a demiplane you created with a previous casting of this spell. Additionally, if you know the nature and contents of a demiplane created by a casting of this spell by another creature, you can have the shadowy door connect to its demiplane instead."],"range":"60 feet","components":["S"],"ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":8,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/demiplane","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-detect-evil-and-good', 'spell', 'Detect Evil and Good', 'spell-detect-evil-and-good', '{"higher_level":[],"index":"detect-evil-and-good","name":"Detect Evil and Good","desc":["For the duration, you know if there is an aberration, celestial, elemental, fey, fiend, or undead within 30 feet of you, as well as where the creature is located. Similarly, you know if there is a place or object within 30 feet of you that has been magically consecrated or desecrated.","The spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":1,"area_of_effect":{"type":"sphere","size":30},"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/detect-evil-and-good","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-detect-magic', 'spell', 'Detect Magic', 'spell-detect-magic', '{"higher_level":[],"index":"detect-magic","name":"Detect Magic","desc":["For the duration, you sense the presence of magic within 30 feet of you. If you sense magic in this way, you can use your action to see a faint aura around any visible creature or object in the area that bears magic, and you learn its school of magic, if any.","The spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."],"range":"Self","components":["V","S"],"ritual":true,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":1,"area_of_effect":{"type":"sphere","size":30},"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/detect-magic","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-detect-poison-and-disease', 'spell', 'Detect Poison and Disease', 'spell-detect-poison-and-disease', '{"higher_level":[],"index":"detect-poison-and-disease","name":"Detect Poison and Disease","desc":["For the duration, you can sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet of you. You also identify the kind of poison, poisonous creature, or disease in each case.","The spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."],"range":"Self","components":["V","S","M"],"material":"A yew leaf.","ritual":true,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":1,"area_of_effect":{"type":"sphere","size":30},"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/detect-poison-and-disease","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-detect-thoughts', 'spell', 'Detect Thoughts', 'spell-detect-thoughts', '{"higher_level":[],"index":"detect-thoughts","name":"Detect Thoughts","desc":["For the duration, you can read the thoughts of certain creatures. When you cast the spell and as your action on each turn until the spell ends, you can focus your mind on any one creature that you can see within 30 feet of you. If the creature you choose has an Intelligence of 3 or lower or doesn''t speak any language, the creature is unaffected.","You initially learn the surface thoughts of the creature - what is most on its mind in that moment. As an action, you can either shift your attention to another creature''s thoughts or attempt to probe deeper into the same creature''s mind. If you probe deeper, the target must make a Wisdom saving throw. If it fails, you gain insight into its reasoning (if any), its emotional state, and something that looms large in its mind (such as something it worries over, loves, or hates). If it succeeds, the spell ends. Either way, the target knows that you are probing into its mind, and unless you shift your attention to another creature''s thoughts, the creature can use its action on its turn to make an Intelligence check contested by your Intelligence check; if it succeeds, the spell ends.","Questions verbally directed at the target creature naturally shape the course of its thoughts, so this spell is particularly effective as part of an interrogation.","You can also use this spell to detect the presence of thinking creatures you can''t see. When you cast the spell or as your action during the duration, you can search for thoughts within 30 feet of you. The spell can penetrate barriers, but 2 feet of rock, 2 inches of any metal other than lead, or a thin sheet of lead blocks you. You can''t detect a creature with an Intelligence of 3 or lower or one that doesn''t speak any language.","Once you detect the presence of a creature in this way, you can read its thoughts for the rest of the duration as described above, even if you can''t see it, but it must still be within range."],"range":"Self","components":["V","S","M"],"material":"A copper coin.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/detect-thoughts","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-dimension-door', 'spell', 'Dimension Door', 'spell-dimension-door', '{"higher_level":[],"index":"dimension-door","name":"Dimension Door","desc":["You teleport yourself from your current location to any other spot within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as \"200 feet straight downward\" or \"upward to the northwest at a 45-degree angle, 300 feet.\"","You can bring along objects as long as their weight doesn''t exceed what you can carry. You can also bring one willing creature of your size or smaller who is carrying gear up to its carrying capacity. The creature must be within 5 feet of you when you cast this spell.","If you would arrive in a place already occupied by an object or a creature, you and any creature traveling with you each take 4d6 force damage, and the spell fails to teleport you."],"range":"500 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"force","name":"Force","url":"/api/2014/damage-types/force"},"damage_at_slot_level":{"4":"4d6"}},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/dimension-door","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-disguise-self', 'spell', 'Disguise Self', 'spell-disguise-self', '{"higher_level":[],"index":"disguise-self","name":"Disguise Self","desc":["You make yourself--including your clothing, armor, weapons, and other belongings on your person--look different until the spell ends or until you use your action to dismiss it. You can seem 1 foot shorter or taller and can appear thin, fat, or in between. You can''t change your body type, so you must adopt a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you.","The changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel your head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.","To discern that you are disguised, a creature can use its action to inspect your appearance and must succeed on an Intelligence (Investigation) check against your spell save DC."],"range":"Self","components":["V","S"],"ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/disguise-self","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-disintegrate', 'spell', 'Disintegrate', 'spell-disintegrate', '{"index":"disintegrate","name":"Disintegrate","desc":["A thin green ray springs from your pointing finger to a target that you can see within range. The target can be a creature, an object, or a creation of magical force, such as the wall created by wall of force.","A creature targeted by this spell must make a dexterity saving throw. On a failed save, the target takes 10d6 + 40 force damage. If this damage reduces the target to 0 hit points, it is disintegrated.","A disintegrated creature and everything it is wearing and carrying, except magic items, are reduced to a pile of fine gray dust. The creature can be restored to life only by means of a true resurrection or a wish spell.","This spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If the target is a Huge or larger object or creation of force, this spell disintegrates a 10-foot-cube portion of it. A magic item is unaffected by this spell."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, the damage increases by 3d6 for each slot level above 6th."],"range":"60 feet","components":["V","S","M"],"material":"A lodestone and a pinch of dust.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"force","name":"Force","url":"/api/2014/damage-types/force"},"damage_at_slot_level":{"6":"10d6 + 40"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"none"},"area_of_effect":{"type":"cube","size":10},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/disintegrate","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-dispel-evil-and-good', 'spell', 'Dispel Evil and Good', 'spell-dispel-evil-and-good', '{"higher_level":[],"index":"dispel-evil-and-good","name":"Dispel Evil and Good","desc":["Shimmering energy surrounds and protects you from fey, undead, and creatures originating from beyond the Material Plane. For the duration, celestials, elementals, fey, fiends, and undead have disadvantage on attack rolls against you.","You can end the spell early by using either of the following special functions.","***Break Enchantment.*** As your action, you touch a creature you can reach that is charmed, frightened, or possessed by a celestial, an elemental, a fey, a fiend, or an undead. The creature you touch is no longer charmed, frightened, or possessed by such creatures.","***Dismissal.*** As your action, make a melee spell attack against a celestial, an elemental, a fey, a fiend, or an undead you can reach. On a hit, you attempt to drive the creature back to its home plane. The creature must succeed on a charisma saving throw or be sent back to its home plane (if it isn''t there already). If they aren''t on their home plane, undead are sent to the Shadowfell, and fey are sent to the Feywild."],"range":"Self","components":["V","S","M"],"material":"Holy water or powdered silver and iron.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":5,"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"other","desc":"The creature must succeed on a charisma saving throw or be sent back to its home plane (if it isn''t there already)"},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[],"url":"/api/2014/spells/dispel-evil-and-good","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-dispel-magic', 'spell', 'Dispel Magic', 'spell-dispel-magic', '{"index":"dispel-magic","name":"Dispel Magic","desc":["Choose one creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher on the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell''s level. On a successful check, the spell ends."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, you automatically end the effects of a spell on the target if the spell''s level is equal to or less than the level of the spell slot you used."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"url":"/api/2014/spells/dispel-magic","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-divination', 'spell', 'Divination', 'spell-divination', '{"higher_level":[],"index":"divination","name":"Divination","desc":["Your magic and an offering put you in contact with a god or a god''s servants. You ask a single question concerning a specific goal, event, or activity to occur within 7 days. The GM offers a truthful reply. The reply might be a short phrase, a cryptic rhyme, or an omen.","The spell doesn''t take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.","If you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret."],"range":"Self","components":["V","S","M"],"material":"Incense and a sacrificial offering appropriate to your religion, together worth at least 25gp, which the spell consumes.","ritual":true,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":4,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/divination","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-divine-favor', 'spell', 'Divine Favor', 'spell-divine-favor', '{"higher_level":[],"index":"divine-favor","name":"Divine Favor","desc":["Your prayer empowers you with divine radiance. Until the spell ends, your weapon attacks deal an extra 1d4 radiant damage on a hit."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 bonus action","level":1,"damage":{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_at_slot_level":{"1":"1d4"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/divine-favor","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-divine-word', 'spell', 'Divine Word', 'spell-divine-word', '{"higher_level":[],"index":"divine-word","name":"Divine Word","desc":["You utter a divine word, imbued with the power that shaped the world at the dawn of creation. Choose any number of creatures you can see within range. Each creature that can hear you must make a Charisma saving throw. On a failed save, a creature suffers an effect based on its current hit points:","- 50 hit points or fewer: deafened for 1 minute","- 40 hit points or fewer: deafened and blinded for 10 minutes","- 30 hit points or fewer: blinded, deafened, and stunned for 1 hour","- 20 hit points or fewer: killed instantly","Regardless of its current hit points, a celestial, an elemental, a fey, or a fiend that fails its save is forced back to its plane of origin (if it isn''t there already) and can''t return to your current plane for 24 hours by any means short of a wish spell."],"range":"30 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 bonus action","level":7,"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"none","desc":"On a failed save, a creature suffers an effect based on its current hit points."},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/divine-word","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-dominate-beast', 'spell', 'Dominate Beast', 'spell-dominate-beast', '{"index":"dominate-beast","name":"Dominate Beast","desc":["You attempt to beguile a creature that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.","While the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn''t receive further direction from you, it defends and preserves itself to the best of its ability.","You can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn''t do anything that you don''t allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well. Each time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends."],"higher_level":["When you cast this spell with a 9th level spell slot, the duration is concentration, up to 8 hours."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"}],"subclasses":[],"url":"/api/2014/spells/dominate-beast","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-dominate-monster', 'spell', 'Dominate Monster', 'spell-dominate-monster', '{"index":"dominate-monster","name":"Dominate Monster","desc":["You attempt to beguile a creature that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.","While the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn''t receive further direction from you, it defends and preserves itself to the best of its ability.","You can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn''t do anything that you don''t allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.","Each time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends."],"higher_level":["When you cast this spell with a 9th-level spell slot, the duration is concentration, up to 8 hours."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":8,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none","desc":"On failure, the creature is charmed by you for the duration."},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/dominate-monster","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-dominate-person', 'spell', 'Dominate Person', 'spell-dominate-person', '{"index":"dominate-person","name":"Dominate Person","desc":["You attempt to beguile a humanoid that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.","While the target is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn''t receive further direction from you, it defends and preserves itself to the best of its ability.","You can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn''t do anything that you don''t allow it to do. During this time you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.","Each time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends."],"higher_level":["When you cast this spell using a 6th-level spell slot, the duration is concentration, up to 10 minutes. When you use a 7th-level spell slot, the duration is concentration, up to 1 hour. When you use a spell slot of 8th level or higher, the duration is concentration, up to 8 hours."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":5,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"other","desc":"Each time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends."},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/dominate-person","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-dream', 'spell', 'Dream', 'spell-dream', '{"higher_level":[],"index":"dream","name":"Dream","desc":["This spell shapes a creature''s dreams. Choose a creature known to you as the target of this spell. The target must be on the same plane of existence as you. Creatures that don''t sleep, such as elves, can''t be contacted by this spell. You, or a willing creature you touch, enters a trance state, acting as a messenger.","While in the trance, the messenger is aware of his or her surroundings, but can''t take actions or move.","If the target is asleep, the messenger appears in the target''s dreams and can converse with the target as long as it remains asleep, through the duration of the spell. The messenger can also shape the environment of the dream, creating landscapes, objects, and other images. The messenger can emerge from the trance at any time, ending the effect of the spell early. The target recalls the dream perfectly upon waking. If the target is awake when you cast the spell, the messenger knows it, and can either end the trance (and the spell) or wait for the target to fall asleep, at which point the messenger appears in the target''s dreams.","You can make the messenger appear monstrous and terrifying to the target. If you do, the messenger can deliver a message of no more than ten words and then the target must make a wisdom saving throw. On a failed save, echoes of the phantasmal monstrosity spawn a nightmare that lasts the duration of the target''s sleep and prevents the target from gaining any benefit from that rest. In addition, when the target wakes up, it takes 3d6 psychic damage.","If you have a body part, lock of hair, clipping from a nail, or similar portion of the target''s body, the target makes its saving throw with disadvantage."],"range":"Special","components":["V","S","M"],"material":"A handful of sand, a dab of ink, and a writing quill plucked from a sleeping bird.","ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 minute","level":5,"damage":{"damage_type":{"index":"psychic","name":"Psychic","url":"/api/2014/damage-types/psychic"},"damage_at_slot_level":{"5":"3d6"}},"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none","desc":"On a failed save, echoes of the phantasmal monstrosity spawn a nightmare that lasts the duration of the target''s sleep and prevents the target from gaining any benefit from that rest."},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/dream","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-druidcraft', 'spell', 'Druidcraft', 'spell-druidcraft', '{"higher_level":[],"index":"druidcraft","name":"Druidcraft","desc":["Whispering to the spirits of nature, you create one of the following effects within ''range'':","- You create a tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round.","- You instantly make a flower bloom, a seed pod open, or a leaf bud bloom.","- You create an instantaneous, harmless sensory effect, such as falling leaves, a puff of wind, the sound of a small animal, or the faint order of skunk. The effect must fit in a 5-foot cube.","- You instantly light or snuff out a candle, a torch, or a small campfire."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/druidcraft","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-earthquake', 'spell', 'Earthquake', 'spell-earthquake', '{"higher_level":[],"index":"earthquake","name":"Earthquake","desc":["You create a seismic disturbance at a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point and shakes creatures and structures in contact with the ground in that area.","The ground in the area becomes difficult terrain. Each creature on the ground that is concentrating must make a constitution saving throw. On a failed save, the creature''s concentration is broken.","When you cast this spell and at the end of each turn you spend concentrating on it, each creature on the ground in the area must make a dexterity saving throw. On a failed save, the creature is knocked prone.","This spell can have additional effects depending on the terrain in the area, as determined by the GM.","Fissures. Fissures open throughout the spell''s area at the start of your next turn after you cast the spell. A total of 1d6 such fissures open in locations chosen by the GM. Each is 1d10 x 10 feet deep, 10 feet wide, and extends from one edge of the spell''s area to the opposite side. A creature standing on a spot where a fissure opens must succeed on a dexterity saving throw or fall in. A creature that successfully saves moves with the fissure''s edge as it opens.","A fissure that opens beneath a structure causes it to automatically collapse (see below).","Structures. The tremor deals 50 bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the start of each of your turns until the spell ends. If a structure drops to 0 hit points, it collapses and potentially damages nearby creatures. A creature within half the distance of a structure''s height must make a dexterity saving throw. On a failed save, the creature takes 5d6 bludgeoning damage, is knocked prone, and is buried in the rubble, requiring a DC 20 Strength (Athletics) check as an action to escape. The GM can adjust the DC higher or lower, depending on the nature of the rubble. On a successful save, the creature takes half as much damage and doesn''t fall prone or become buried."],"range":"500 feet","components":["V","S","M"],"material":"A pinch of dirt, a piece of rock, and a lump of clay.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":8,"area_of_effect":{"type":"sphere","size":100},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"}],"subclasses":[],"url":"/api/2014/spells/earthquake","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-eldritch-blast', 'spell', 'Eldritch Blast', 'spell-eldritch-blast', '{"higher_level":[],"index":"eldritch-blast","name":"Eldritch Blast","desc":["A beam of crackling energy streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 force damage. The spell creates more than one beam when you reach higher levels: two beams at 5th level, three beams at 11th level, and four beams at 17th level. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"attack_type":"ranged","damage":{"damage_type":{"index":"force","name":"Force","url":"/api/2014/damage-types/force"},"damage_at_character_level":{"1":"1d10","5":"1d10","11":"1d10","17":"1d10"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/eldritch-blast","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-enhance-ability', 'spell', 'Enhance Ability', 'spell-enhance-ability', '{"index":"enhance-ability","name":"Enhance Ability","desc":["You touch a creature and bestow upon it a magical enhancement. Choose one of the following effects; the target gains that effect until the spell ends.","***Bear''s Endurance.*** The target has advantage on constitution checks. It also gains 2d6 temporary hit points, which are lost when the spell ends.","***Bull''s Strength.*** The target has advantage on strength checks, and his or her carrying capacity doubles.","***Cat''s Grace.*** The target has advantage on dexterity checks. It also doesn''t take damage from falling 20 feet or less if it isn''t incapacitated.","***Eagle''s Splendor.*** The target has advantage on Charisma checks.","***Fox''s Cunning.*** The target has advantage on intelligence checks.","***Owl''s Wisdom.*** The target has advantage on wisdom checks."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."],"range":"Touch","components":["V","S","M"],"material":"Fur or a feather from a beast.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/enhance-ability","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-enlarge-reduce', 'spell', 'Enlarge/Reduce', 'spell-enlarge-reduce', '{"higher_level":[],"index":"enlarge-reduce","name":"Enlarge/Reduce","desc":["You cause a creature or an object you can see within range to grow larger or smaller for the duration. Choose either a creature or an object that is neither worn nor carried. If the target is unwilling, it can make a Constitution saving throw. On a success, the spell has no effect.","If the target is a creature, everything it is wearing and carrying changes size with it. Any item dropped by an affected creature returns to normal size at once.","***Enlarge.*** The target''s size doubles in all dimensions, and its weight is multiplied by eight. This growth increases its size by one category-from Medium to Large, for example. If there isn''t enough room for the target to double its size, the creature or object attains the maximum possible size in the space available. Until the spell ends, the target also has advantage on Strength checks and Strength saving throws. The target''s weapons also grow to match its new size. While these weapons are enlarged, the target''s attacks with them deal 1d4 extra damage.","***Reduce.*** The target''s size is halved in all dimensions, and its weight is reduced to one-eighth of normal. This reduction decreases its size by one category-from Medium to Small, for example. Until the spell ends, the target also has disadvantage on Strength checks and Strength saving throws. The target''s weapons also shrink to match its new size. While these weapons are reduced, the target''s attacks with them deal 1d4 less damage (this can''t reduce the damage below 1)."],"range":"30 feet","components":["V","S","M"],"material":"A pinch iron powder.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"none"},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/enlarge-reduce","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-entangle', 'spell', 'Entangle', 'spell-entangle', '{"higher_level":[],"index":"entangle","name":"Entangle","desc":["Grasping weeds and vines sprout from the ground in a 20-foot square starting form a point within range. For the duration, these plants turn the ground in the area into difficult terrain.","A creature in the area when you cast the spell must succeed on a strength saving throw or be restrained by the entangling plants until the spell ends. A creature restrained by the plants can use its action to make a Strength check against your spell save DC. On a success, it frees itself.","When the spell ends, the conjured plants wilt away."],"range":"90 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":1,"dc":{"dc_type":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"dc_success":"none"},"area_of_effect":{"type":"cube","size":20},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/entangle","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-enthrall', 'spell', 'Enthrall', 'spell-enthrall', '{"higher_level":[],"index":"enthrall","name":"Enthrall","desc":["You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a wisdom saving throw. Any creature that can''t be charmed succeeds on this saving throw automatically, and if you or your companions are fighting a creature, it has advantage on the save. On a failed save, the target has disadvantage on Wisdom (Perception) checks made to perceive any creature other than you until the spell ends or until the target can no longer hear you. The spell ends if you are incapacitated or can no longer speak."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":2,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/enthrall","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-etherealness', 'spell', 'Etherealness', 'spell-etherealness', '{"index":"etherealness","name":"Etherealness","desc":["You step into the border regions of the Ethereal Plane, in the area where it overlaps with your current plane. You remain in the Border Ethereal for the duration or until you use your action to dismiss the spell. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can see and hear the plane you originated from, but everything there looks gray, and you can''t see anything more than 60 feet away.","While on the Ethereal Plane, you can only affect and be affected by other creatures on that plane. Creatures that aren''t on the Ethereal Plane can''t perceive you and can''t interact with you, unless a special ability or magic has given them the ability to do so.","You ignore all objects and effects that aren''t on the Ethereal Plane, allowing you to move through objects you perceive on the plane you originated from.","When the spell ends, you immediately return to the plane you originated from in the spot you currently occupy. If you occupy the same spot as a solid object or creature when this happens, you are immediately shunted to the nearest unoccupied space that you can occupy and take force damage equal to twice the number of feet you are moved.","This spell has no effect if you cast it while you are on the Ethereal Plane or a plane that doesn''t border it, such as one of the Outer Planes."],"higher_level":["When you cast this spell using a spell slot of 8th level or higher, you can target up to three willing creatures (including you) for each slot level above 7th. The creatures must be within 10 feet of you when you cast the spell."],"range":"Self","components":["V","S"],"ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":7,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/etherealness","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-expeditious-retreat', 'spell', 'Expeditious Retreat', 'spell-expeditious-retreat', '{"higher_level":[],"index":"expeditious-retreat","name":"Expeditious Retreat","desc":["This spell allows you to move at an incredible pace. When you cast this spell, and then as a bonus action on each of your turns until the spell ends, you can take the Dash action."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 bonus action","level":1,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/expeditious-retreat","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-eyebite', 'spell', 'Eyebite', 'spell-eyebite', '{"higher_level":[],"index":"eyebite","name":"Eyebite","desc":["For the spell''s duration, your eyes become an inky void imbued with dread power. One creature of your choice within 60 feet of you that you can see must succeed on a wisdom saving throw or be affected by one of the following effects of your choice for the duration. On each of your turns until the spell ends, you can use your action to target another creature but can''t target a creature again if it has succeeded on a saving throw against this casting of eyebite.","***Asleep.*** The target falls unconscious. It wakes up if it takes any damage or if another creature uses its action to shake the sleeper awake.","***Panicked.*** The target is frightened of you. On each of its turns, the frightened creature must take the Dash action and move away from you by the safest and shortest available route, unless there is nowhere to move. If the target moves to a place at least 60 feet away from you where it can no longer see you, this effect ends.","***Sickened.*** The target has disadvantage on attack rolls and ability checks. At the end of each of its turns, it can make another wisdom saving throw. If it succeeds, the effect ends."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":6,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none","desc":"On failure, the target can be affected by one of the following effects of your choice for the duration. [Asleep. The target falls unconscious. It wakes up if it takes any damage or if another creature uses its action to shake the sleeper awake.] [Panicked. The target is frightened of you. On each of its turns, the frightened creature must take the Dash action and move away from you by the safest and shortest available route, unless there is nowhere to move. If the target moves to a place at least 60 feet away from you where it can no longer see you, this effect ends.] [Sickened. The target has disadvantage on attack rolls and ability checks. At the end of each of its turns, it can make another wisdom saving throw. If it succeeds, the effect ends.]"},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/eyebite","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-fabricate', 'spell', 'Fabricate', 'spell-fabricate', '{"higher_level":[],"index":"fabricate","name":"Fabricate","desc":["You convert raw materials into products of the same material. For example, you can fabricate a wooden bridge from a clump of trees, a rope from a patch of hemp, and clothes from flax or wool.","Choose raw materials that you can see within range. You can fabricate a Large or smaller object (contained within a 10-foot cube, or eight connected 5-foot cubes), given a sufficient quantity of raw material. If you are working with metal, stone, or another mineral substance, however, the fabricated object can be no larger than Medium (contained within a single 5-foot cube). The quality of objects made by the spell is commensurate with the quality of the raw materials.","Creatures or magic items can''t be created or transmuted by this spell. You also can''t use it to create items that ordinarily require a high degree of craftsmanship, such as jewelry, weapons, glass, or armor, unless you have proficiency with the type of artisan''s tools used to craft such objects."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"10 minutes","level":4,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/fabricate","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-faerie-fire', 'spell', 'Faerie Fire', 'spell-faerie-fire', '{"higher_level":[],"index":"faerie-fire","name":"Faerie Fire","desc":["Each object in a 20-foot cube within range is outlined in blue, green, or violet light (your choice). Any creature in the area when the spell is cast is also outlined in light if it fails a dexterity saving throw. For the duration, objects and affected creatures shed dim light in a 10-foot radius.","Any attack roll against an affected creature or object has advantage if the attacker can see it, and the affected creature or object can''t benefit from being invisible."],"range":"60 feet","components":["V"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":1,"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"none"},"area_of_effect":{"type":"cube","size":20},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/faerie-fire","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-faithful-hound', 'spell', 'Faithful Hound', 'spell-faithful-hound', '{"higher_level":[],"index":"faithful-hound","name":"Faithful Hound","desc":["You conjure a phantom watchdog in an unoccupied space that you can see within range, where it remains for the duration, until you dismiss it as an action, or until you move more than 100 feet away from it.","The hound is invisible to all creatures except you and can''t be harmed. When a Small or larger creature comes within 30 feet of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound sees invisible creatures and can see into the Ethereal Plane. It ignores illusions.","At the start of each of your turns, the hound attempts to bite one creature within 5 feet of it that is hostile to you. The hound''s attack bonus is equal to your spellcasting ability modifier + your proficiency bonus. On a hit, it deals 4d8 piercing damage."],"range":"30 feet","components":["V","S","M"],"material":"A tiny silver whistle, a piece of bone, and a thread","ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":4,"attack_type":"melee","damage":{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_at_slot_level":{"4":"4d8"}},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/faithful-hound","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-false-life', 'spell', 'False Life', 'spell-false-life', '{"index":"false-life","name":"False Life","desc":["Bolstering yourself with a necromantic facsimile of life, you gain 1d4 + 4 temporary hit points for the duration."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, you gain 5 additional temporary hit points for each slot level above 1st."],"range":"Self","components":["V","S","M"],"material":"A small amount of alcohol or distilled spirits.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":1,"heal_at_slot_level":{"1":"1d4 + 4","2":"1d4 + 9","3":"1d4 + 14","4":"1d4 + 19","5":"1d4 + 24","6":"1d4 + 29","7":"1d4 + 34","8":"1d4 + 39","9":"1d4 + 44"},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/false-life","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-fear', 'spell', 'Fear', 'spell-fear', '{"higher_level":[],"index":"fear","name":"Fear","desc":["You project a phantasmal image of a creature''s worst fears. Each creature in a 30-foot cone must succeed on a wisdom saving throw or drop whatever it is holding and become frightened for the duration.","While frightened by this spell, a creature must take the Dash action and move away from you by the safest available route on each of its turns, unless there is nowhere to move. If the creature ends its turn in a location where it doesn''t have line of sight to you, the creature can make a wisdom saving throw. On a successful save, the spell ends for that creature."],"range":"Self","components":["V","S","M"],"material":"A white feather or the heart of a hen.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none","desc":"On fail, A creature drop whatever it is holding and become frightened for the duration."},"area_of_effect":{"type":"cone","size":30},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/fear","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-feather-fall', 'spell', 'Feather Fall', 'spell-feather-fall', '{"higher_level":[],"index":"feather-fall","name":"Feather Fall","desc":["Choose up to five falling creatures within range. A falling creature''s rate of descent slows to 60 feet per round until the spell ends. If the creature lands before the spell ends, it takes no falling damage and can land on its feet, and the spell ends for that creature."],"range":"60 feet","components":["V","M"],"material":"A small feather or a piece of down.","ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 reaction","level":1,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/feather-fall","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-feeblemind', 'spell', 'Feeblemind', 'spell-feeblemind', '{"higher_level":[],"index":"feeblemind","name":"Feeblemind","desc":["You blast the mind of a creature that you can see within range, attempting to shatter its intellect and personality. The target takes 4d6 psychic damage and must make an intelligence saving throw.","On a failed save, the creature''s Intelligence and Charisma scores become 1. The creature can''t cast spells, activate magic items, understand language, or communicate in any intelligible way. The creature can, however, identify its friends, follow them, and even protect them.","At the end of every 30 days, the creature can repeat its saving throw against this spell. If it succeeds on its saving throw, the spell ends.","The spell can also be ended by greater restoration, heal, or wish."],"range":"150 feet","components":["V","S","M"],"material":"A handful of clay, crystal, glass, or mineral spheres.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":8,"damage":{"damage_type":{"index":"psychic","name":"Psychic","url":"/api/2014/damage-types/psychic"},"damage_at_slot_level":{"8":"4d6"}},"dc":{"dc_type":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"dc_success":"other","desc":"The target always takes the damage. On a failed save, the creature''s Intelligence and Charisma scores become 1."},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/feeblemind","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-find-familiar', 'spell', 'Find Familiar', 'spell-find-familiar', '{"higher_level":[],"index":"find-familiar","name":"Find Familiar","desc":["You gain the service of a familiar, a spirit that takes an animal form you choose: bat, cat, crab, frog (toad), hawk, lizard, octopus, owl, poisonous snake, fish (quipper), rat, raven, sea horse, spider, or weasel. Appearing in an unoccupied space within range, the familiar has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of a beast.","Your familiar acts independently of you, but it always obeys your commands. In combat, it rolls its own initiative and acts on its own turn. A familiar can''t attack, but it can take other actions as normal.","When the familiar drops to 0 hit points, it disappears, leaving behind no physical form. It reappears after you cast this spell again.","While your familiar is within 100 feet of you, you can communicate with it telepathically. Additionally, as an action, you can see through your familiar''s eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses that the familiar has. During this time, you are deaf and blind with regard to your own senses.","As an action, you can temporarily dismiss your familiar. It disappears into a pocket dimension where it awaits your summons. Alternatively, you can dismiss it forever. As an action while it is temporarily dismissed, you can cause it to reappear in any unoccupied space within 30 feet of you.","You can''t have more than one familiar at a time. If you cast this spell while you already have a familiar, you instead cause it to adopt a new form. Choose one of the forms from the above list. Your familiar transforms into the chosen creature.","Finally, when you cast a spell with a range of touch, your familiar can deliver the spell as if it had cast the spell. Your familiar must be within 100 feet of you, and it must use its reaction to deliver the spell when you cast it. If the spell requires an attack roll, you use your action modifier for the roll."],"range":"10 feet","components":["V","S","M"],"material":"10gp worth of charcoal, incense, and herbs that must be consumed by fire in a brass brazier.","ritual":true,"duration":"Instantaneous","concentration":false,"casting_time":"1 hour","level":1,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/find-familiar","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-find-steed', 'spell', 'Find Steed', 'spell-find-steed', '{"higher_level":[],"index":"find-steed","name":"Find Steed","desc":["You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes on a form that you choose, such as a warhorse, a pony, a camel, an elk, or a mastiff. (Your GM might allow other animals to be summoned as steeds.) The steed has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of its normal type. Additionally, if your steed has an Intelligence of 5 or less, its Intelligence becomes 6, and it gains the ability to understand one language of your choice that you speak.","Your steed serves you as a mount, both in combat and out, and you have an instinctive bond with it that allows you to fight as a seamless unit. While mounted on your steed, you can make any spell you cast that targets only you also target your steed.","When the steed drops to 0 hit points, it disappears, leaving behind no physical form. You can also dismiss your steed at any time as an action, causing it to disappear. In either case, casting this spell again summons the same steed, restored to its hit point maximum.","While your steed is within 1 mile of you, you can communicate with it telepathically.","You can''t have more than one steed bonded by this spell at a time. As an action, you can release the steed from its bond at any time, causing it to disappear."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"10 minutes","level":2,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/find-steed","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-find-the-path', 'spell', 'Find the Path', 'spell-find-the-path', '{"higher_level":[],"index":"find-the-path","name":"Find the Path","desc":["This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence. If you name a destination on another plane of existence, a destination that moves (such as a mobile fortress), or a destination that isn''t specific (such as \"a green dragon''s lair\"), the spell fails.","For the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. While you are traveling there, whenever you are presented with a choice of paths along the way, you automatically determine which path is the shortest and most direct route (but not necessarily the safest route) to the destination."],"range":"Self","components":["V","S","M"],"material":"A set of divinatory tools--such as bones, ivory sticks, cards, teeth, or carved runes--worth 100gp and an object from the location you wish to find.","ritual":false,"duration":"Up to 24 hours","concentration":true,"casting_time":"1 minute","level":6,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/find-the-path","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-find-traps', 'spell', 'Find Traps', 'spell-find-traps', '{"higher_level":[],"index":"find-traps","name":"Find Traps","desc":["You sense the presence of any trap within range that is within line of sight. A trap, for the purpose of this spell, includes anything that would inflict a sudden or unexpected effect you consider harmful or undesirable, which was specifically intended as such by its creator. Thus, the spell would sense an area affected by the alarm spell, a glyph of warding, or a mechanical pit trap, but it would not reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole.","This spell merely reveals that a trap is present. You don''t learn the location of each trap, but you do learn the general nature of the danger posed by a trap you sense."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/find-traps","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-finger-of-death', 'spell', 'Finger of Death', 'spell-finger-of-death', '{"higher_level":[],"index":"finger-of-death","name":"Finger of Death","desc":["You send negative energy coursing through a creature that you can see within range, causing it searing pain. The target must make a constitution saving throw. It takes 7d8 + 30 necrotic damage on a failed save, or half as much damage on a successful one.","A humanoid killed by this spell rises at the start of your next turn as a zombie that is permanently under your command, following your verbal orders to the best of its ability."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":7,"damage":{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_at_slot_level":{"7":"7d8 + 30"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/finger-of-death","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-fire-bolt', 'spell', 'Fire Bolt', 'spell-fire-bolt', '{"higher_level":[],"index":"fire-bolt","name":"Fire Bolt","desc":["You hurl a mote of fire at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn''t being worn or carried.","This spell''s damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"attack_type":"ranged","damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_character_level":{"1":"1d10","5":"2d10","11":"3d10","17":"4d10"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/fire-bolt","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-fire-shield', 'spell', 'Fire Shield', 'spell-fire-shield', '{"higher_level":[],"index":"fire-shield","name":"Fire Shield","desc":["Thin and vaporous flame surround your body for the duration of the spell, radiating a bright light bright light in a 10-foot radius and dim light for an additional 10 feet. You can end the spell using an action to make it disappear.","The flames are around you a heat shield or cold, your choice. The heat shield gives you cold damage resistance and the cold resistance to fire damage.","In addition, whenever a creature within 5 feet of you hits you with a melee attack, flames spring from the shield. The attacker then suffers 2d8 points of fire damage or cold, depending on the model."],"range":"Self","components":["V","S","M"],"material":"A little phosphorus or a firefly.","ritual":false,"duration":"10 minutes","concentration":false,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"4":"2d8"}},"area_of_effect":{"type":"sphere","size":5},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/fire-shield","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-fire-storm', 'spell', 'Fire Storm', 'spell-fire-storm', '{"higher_level":[],"index":"fire-storm","name":"Fire Storm","desc":["A storm made up of sheets of roaring flame appears in a location you choose within range. The area of the storm consists of up to ten 10-foot cubes, which you can arrange as you wish. Each cube must have at least one face adjacent to the face of another cube. Each creature in the area must make a dexterity saving throw. It takes 7d10 fire damage on a failed save, or half as much damage on a successful one.","The fire damages objects in the area and ignites flammable objects that aren''t being worn or carried. If you choose, plant life in the area is unaffected by this spell."],"range":"150 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":7,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"7":"7d10"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"cube","size":100},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"}],"subclasses":[],"url":"/api/2014/spells/fire-storm","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-fireball', 'spell', 'Fireball', 'spell-fireball', '{"index":"fireball","name":"Fireball","desc":["A bright streak flashes from your pointing finger to a point you choose within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot-radius sphere centered on that point must make a dexterity saving throw. A target takes 8d6 fire damage on a failed save, or half as much damage on a successful one.","The fire spreads around corners. It ignites flammable objects in the area that aren''t being worn or carried."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."],"range":"150 feet","components":["V","S","M"],"material":"A tiny ball of bat guano and sulfur.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":3,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"3":"8d6","4":"9d6","5":"10d6","6":"11d6","7":"12d6","8":"13d6","9":"14d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":20},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/fireball","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-flame-blade', 'spell', 'Flame Blade', 'spell-flame-blade', '{"index":"flame-blade","name":"Flame Blade","desc":["You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke the blade again as a bonus action.","You can use your action to make a melee spell attack with the fiery blade. On a hit, the target takes 3d6 fire damage.","The flaming blade sheds bright light in a 10-foot radius and dim light for an additional 10 feet."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for every two slot levels above 2nd."],"range":"Self","components":["V","S","M"],"material":"Leaf of sumac.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 bonus action","level":2,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"2":"3d6","4":"4d6","6":"5d6","8":"6d6"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/flame-blade","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-flame-strike', 'spell', 'Flame Strike', 'spell-flame-strike', '{"index":"flame-strike","name":"Flame Strike","desc":["A vertical column of divine fire roars down from the heavens in a location you specify. Each creature in a 10-foot-radius, 40-foot-high cylinder centered on a point within range must make a dexterity saving throw. A creature takes 4d6 fire damage and 4d6 radiant damage on a failed save, or half as much damage on a successful one."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the fire damage or the radiant damage (your choice) increases by 1d6 for each slot level above 5th."],"range":"60 feet","components":["V","S","M"],"material":"Pinch of sulfur.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":5,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"5":"4d6 + 4d6","6":"4d6 + 5d6","7":"4d6 + 6d6","8":"4d6 + 7d6","9":"4d6 + 8d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"cylinder","size":40},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"},{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/flame-strike","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-flaming-sphere', 'spell', 'Flaming Sphere', 'spell-flaming-sphere', '{"index":"flaming-sphere","name":"Flaming Sphere","desc":["A 5-foot-diameter sphere of fire appears in an unoccupied space of your choice within range and lasts for the duration. Any creature that ends its turn within 5 feet of the sphere must make a dexterity saving throw. The creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.","As a bonus action, you can move the sphere up to 30 feet. If you ram the sphere into a creature, that creature must make the saving throw against the sphere''s damage, and the sphere stops moving this turn.","When you move the sphere, you can direct it over barriers up to 5 feet tall and jump it across pits up to 10 feet wide. The sphere ignites flammable objects not being worn or carried, and it sheds bright light in a 20-foot radius and dim light for an additional 20 feet."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd."],"range":"60 feet","components":["V","S","M"],"material":"A bit of tallow, a pinch of brimstone, and a dusting of powdered iron.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"2":"2d6","3":"3d6","4":"4d6","5":"5d6","6":"6d6","7":"7d6","8":"8d6","9":"9d6"}},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/flaming-sphere","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-flesh-to-stone', 'spell', 'Flesh to Stone', 'spell-flesh-to-stone', '{"higher_level":[],"index":"flesh-to-stone","name":"Flesh to Stone","desc":["You attempt to turn one creature that you can see within range into stone. If the target''s body is made of flesh, the creature must make a constitution saving throw. On a failed save, it is restrained as its flesh begins to harden. On a successful save, the creature isn''t affected.","A creature restrained by this spell must make another constitution saving throw at the end of each of its turns. If it successfully saves against this spell three times, the spell ends. If it fails its saves three times, it is turned to stone and subjected to the petrified condition for the duration. The successes and failures don''t need to be consecutive; keep track of both until the target collects three of a kind.","If the creature is physically broken while petrified, it suffers from similar deformities if it reverts to its original state.","If you maintain your concentration on this spell for the entire possible duration, the creature is turned to stone until the effect is removed."],"range":"60 feet","components":["V","S","M"],"material":"A pinch of lime, water, and earth.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":6,"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"none","desc":"On a failed save, the target is restrained as its flesh begins to harden."},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/flesh-to-stone","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-floating-disk', 'spell', 'Floating Disk', 'spell-floating-disk', '{"higher_level":[],"index":"floating-disk","name":"Floating Disk","desc":["This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration, and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.","The disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. If can move across uneven terrain, up or down stairs, slopes and the like, but it can''t cross an elevation change of 10 feet or more. For example, the disk can''t move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom.","If you move more than 100 feet away from the disk (typically because it can''t move around an obstacle to follow you), the spell ends."],"range":"30 feet","components":["V","S","M"],"material":"A drop of mercury.","ritual":true,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/floating-disk","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-fly', 'spell', 'Fly', 'spell-fly', '{"index":"fly","name":"Fly","desc":["You touch a willing creature. The target gains a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft, unless it can stop the fall."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd."],"range":"Touch","components":["V","S","M"],"material":"A wing feather from any bird.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":3,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/fly","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-fog-cloud', 'spell', 'Fog Cloud', 'spell-fog-cloud', '{"index":"fog-cloud","name":"Fog Cloud","desc":["You create a 20-foot-radius sphere of fog centered on a point within range. The sphere spreads around corners, and its area is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the radius of the fog increases by 20 feet for each slot level above 1st."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":1,"area_of_effect":{"type":"sphere","size":20},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/fog-cloud","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-forbiddance', 'spell', 'Forbiddance', 'spell-forbiddance', '{"higher_level":[],"index":"forbiddance","name":"Forbiddance","desc":["You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can''t teleport into the area or use portals, such as those created by the gate spell, to enter the area. The spell proofs the area against planar travel, and therefore prevents creatures from accessing the area by way of the Astral Plane, Ethereal Plane, Feywild, Shadowfell, or the plane shift spell.","In addition, the spell damages types of creatures that you choose when you cast it. Choose one or more of the following: celestials, elementals, fey, fiends, and undead. When a chosen creature enters the spell''s area for the first time on a turn or starts its turn there, the creature takes 5d10 radiant or necrotic damage (your choice when you cast this spell).","When you cast this spell, you can designate a password. A creature that speaks the password as it enters the area takes no damage from the spell.","The spell''s area can''t overlap with the area of another forbiddance spell. If you cast forbiddance every day for 30 days in the same location, the spell lasts until it is dispelled, and the material components are consumed on the last casting."],"range":"Touch","components":["V","S","M"],"material":"A sprinkling of holy water, rare incense, and powdered ruby worth at least 1,000 gp.","ritual":true,"duration":"24 hours","concentration":false,"casting_time":"10 minutes","level":6,"area_of_effect":{"type":"cube","size":40000},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/forbiddance","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-forcecage', 'spell', 'Forcecage', 'spell-forcecage', '{"higher_level":[],"index":"forcecage","name":"Forcecage","desc":["An immobile, invisible, cube-shaped prison composed of magical force springs into existence around an area you choose within range. The prison can be a cage or a solid box, as you choose.","A prison in the shape of a cage can be up to 20 feet on a side and is made from 1/2-inch diameter bars spaced 1/2 inch apart.","A prison in the shape of a box can be up to 10 feet on a side, creating a solid barrier that prevents any matter from passing through it and blocking any spells cast into or out from the area.","When you cast the spell, any creature that is completely inside the cage''s area is trapped. Creatures only partially within the area, or those too large to fit inside the area, are pushed away from the center of the area until they are completely outside the area.","A creature inside the cage can''t leave it by nonmagical means. If the creature tries to use teleportation or interplanar travel to leave the cage, it must first make a charisma saving throw. On a success, the creature can use that magic to exit the cage. On a failure, the creature can''t exit the cage and wastes the use of the spell or effect. The cage also extends into the Ethereal Plane, blocking ethereal travel.","This spell can''t be dispelled by dispel magic."],"range":"100 feet","components":["V","S","M"],"material":"Ruby dust worth 1,500 gp.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":7,"area_of_effect":{"type":"cube","size":20},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/forcecage","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-foresight', 'spell', 'Foresight', 'spell-foresight', '{"higher_level":[],"index":"foresight","name":"Foresight","desc":["You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target can''t be surprised and has advantage on attack rolls, ability checks, and saving throws. Additionally, other creatures have disadvantage on attack rolls against the target for the duration.","This spell immediately ends if you cast it again before its duration ends."],"range":"Touch","components":["V","S","M"],"material":"A hummingbird feather.","ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 minute","level":9,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/foresight","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-freedom-of-movement', 'spell', 'Freedom of Movement', 'spell-freedom-of-movement', '{"higher_level":[],"index":"freedom-of-movement","name":"Freedom of Movement","desc":["You touch a willing creature. For the duration, the target''s movement is unaffected by difficult terrain, and spells and other magical effects can neither reduce the target''s speed nor cause the target to be paralyzed or restrained.","The target can also spend 5 feet of movement to automatically escape from nonmagical restraints, such as manacles or a creature that has it grappled. Finally, being underwater imposes no penalties on the target''s movement or attacks."],"range":"Touch","components":["V","S","M"],"material":"A leather strap, bound around the arm or a similar appendage.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":4,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"},{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"url":"/api/2014/spells/freedom-of-movement","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-freezing-sphere', 'spell', 'Freezing Sphere', 'spell-freezing-sphere', '{"index":"freezing-sphere","name":"Freezing Sphere","desc":["A frigid globe of cold energy streaks from your fingertips to a point of your choice within range, where it explodes in a 60-foot-radius sphere. Each creature within the area must make a constitution saving throw. On a failed save, a creature takes 10d6 cold damage. On a successful save, it takes half as much damage.","If the globe strikes a body of water or a liquid that is principally water (not including water-based creatures), it freezes the liquid to a depth of 6 inches over an area 30 feet square. This ice lasts for 1 minute. Creatures that were swimming on the surface of frozen water are trapped in the ice. A trapped creature can use an action to make a Strength check against your spell save DC to break free.","You can refrain from firing the globe after completing the spell, if you wish. A small globe about the size of a sling stone, cool to the touch, appears in your hand. At any time, you or a creature you give the globe to can throw the globe (to a range of 40 feet) or hurl it with a sling (to the sling''s normal range). It shatters on impact, with the same effect as the normal casting of the spell. You can also set the globe down without shattering it. After 1 minute, if the globe hasn''t already shattered, it explodes."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d6 for each slot level above 6th."],"range":"300 feet","components":["V","S","M"],"material":"A small crystal sphere.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"cold","name":"Cold","url":"/api/2014/damage-types/cold"},"damage_at_slot_level":{"6":"10d6"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/freezing-sphere","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-gaseous-form', 'spell', 'Gaseous Form', 'spell-gaseous-form', '{"higher_level":[],"index":"gaseous-form","name":"Gaseous Form","desc":["You transform a willing creature you touch, along with everything it''s wearing and carrying, into a misty cloud for the duration. The spell ends if the creature drops to 0 hit points. An incorporeal creature isn''t affected.","While in this form, the target''s only method of movement is a flying speed of 10 feet. The target can enter and occupy the space of another creature. The target has resistance to nonmagical damage, and it has advantage on Strength, Dexterity, and constitution saving throws. The target can pass through small holes, narrow openings, and even mere cracks, though it treats liquids as though they were solid surfaces. The target can''t fall and remains hovering in the air even when stunned or otherwise incapacitated.","While in the form of a misty cloud, the target can''t talk or manipulate objects, and any objects it was carrying or holding can''t be dropped, used, or otherwise interacted with. The target can''t attack or cast spells."],"range":"Touch","components":["V","S","M"],"material":"A bit of gauze and a wisp of smoke.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":3,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/gaseous-form","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-gate', 'spell', 'Gate', 'spell-gate', '{"higher_level":[],"index":"gate","name":"Gate","desc":["You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration.","The portal has a front and a back on each plane where it appears. Travel through the portal is possible only by moving through its front. Anything that does so is instantly transported to the other plane, appearing in the unoccupied space nearest to the portal.","Deities and other planar rulers can prevent portals created by this spell from opening in their presence or anywhere within their domains.","When you cast this spell, you can speak the name of a specific creature (a pseudonym, title, or nickname doesn''t work). If that creature is on a plane other than the one you are on, the portal opens in the named creature''s immediate vicinity and draws the creature through it to the nearest unoccupied space on your side of the portal. You gain no special power over the creature, and it is free to act as the GM deems appropriate. It might leave, attack you, or help you."],"range":"60 feet","components":["V","S","M"],"material":"A diamond worth at least 5,000gp.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":9,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/gate","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-geas', 'spell', 'Geas', 'spell-geas', '{"index":"geas","name":"Geas","desc":["You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a wisdom saving throw or become charmed by you for the duration. While the creature is charmed by you, it takes 5d10 psychic damage each time it acts in a manner directly counter to your instructions, but no more than once each day. A creature that can''t understand you is unaffected by the spell.","You can issue any command you choose, short of an activity that would result in certain death. Should you issue a suicidal command, the spell ends.","You can end the spell early by using an action to dismiss it. A remove curse, greater restoration, or wish spell also ends it."],"higher_level":["When you cast this spell using a spell slot of 7th or 8th level, the duration is 1 year. When you cast this spell using a spell slot of 9th level, the spell lasts until it is ended by one of the spells mentioned above."],"range":"60 feet","components":["V"],"ritual":false,"duration":"30 days","concentration":false,"casting_time":"1 minute","level":5,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/geas","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-gentle-repose', 'spell', 'Gentle Repose', 'spell-gentle-repose', '{"higher_level":[],"index":"gentle-repose","name":"Gentle Repose","desc":["You touch a corpse or other remains. For the duration, the target is protected from decay and can''t become undead.","The spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don''t count against the time limit of spells such as raise dead."],"range":"Touch","components":["V","S","M"],"material":"A pinch of salt and one copper piece placed on each of the corpse''s eyes, which must remain there for the duration.","ritual":true,"duration":"10 days","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/gentle-repose","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-giant-insect', 'spell', 'Giant Insect', 'spell-giant-insect', '{"higher_level":[],"index":"giant-insect","name":"Giant Insect","desc":["You transform up to ten centipedes, three spiders, five wasps, or one scorpion within range into giant versions of their natural forms for the duration. A centipede becomes a giant centipede, a spider becomes a giant spider, a wasp becomes a giant wasp, and a scorpion becomes a giant scorpion.","Each creature obeys your verbal commands, and in combat, they act on your turn each round. The GM has the statistics for these creatures and resolves their actions and movement.","A creature remains in its giant size for the duration, until it drops to 0 hit points, or until you use an action to dismiss the effect on it.","The GM might allow you to choose different targets. For example, if you transform a bee, its giant version might have the same statistics as a giant wasp."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":4,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/giant-insect","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-glibness', 'spell', 'Glibness', 'spell-glibness', '{"higher_level":[],"index":"glibness","name":"Glibness","desc":["Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful."],"range":"Self","components":["V"],"ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":8,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"}],"subclasses":[],"url":"/api/2014/spells/glibness","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-globe-of-invulnerability', 'spell', 'Globe of Invulnerability', 'spell-globe-of-invulnerability', '{"index":"globe-of-invulnerability","name":"Globe of Invulnerability","desc":["An immobile, faintly shimmering barrier springs into existence in a 10-foot radius around you and remains for the duration.","Any spell of 5th level or lower cast from outside the barrier can''t affect creatures or objects within it, even if the spell is cast using a higher level spell slot. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from the areas affected by such spells."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, the barrier blocks spells of one level higher for each slot level above 6th."],"range":"Self","components":["V","S","M"],"material":"A glass or crystal bead that shatters when the spell ends.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":6,"area_of_effect":{"type":"sphere","size":10},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/globe-of-invulnerability","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-glyph-of-warding', 'spell', 'Glyph of Warding', 'spell-glyph-of-warding', '{"index":"glyph-of-warding","name":"Glyph of Warding","desc":["When you cast this spell, you inscribe a glyph that harms other creatures, either upon a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph. If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.","The glyph is nearly invisible and requires a successful Intelligence (Investigation) check against your spell save DC to be found.","You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or standing on the glyph, removing another object covering the glyph, approaching within a certain distance of the glyph, or manipulating the object on which the glyph is inscribed. For glyphs inscribed within an object, the most common triggers include opening that object, approaching within a certain distance of the object, or seeing or reading the glyph. Once a glyph is triggered, this spell ends.","You can further refine the trigger so the spell activates only under certain circumstances or according to physical characteristics (such as height or weight), creature kind (for example, the ward could be set to affect aberrations or drow), or alignment. You can also set conditions for creatures that don''t trigger the glyph, such as those who say a certain password.","When you inscribe the glyph, choose *explosive runes* or a *spell glyph*.","***Explosive Runes.*** When triggered, the glyph erupts with magical energy in a 20-foot-radius sphere centered on the glyph. The sphere spreads around corners. Each creature in the area must make a Dexterity saving throw. A creature takes 5d8 acid, cold, fire, lightning, or thunder damage on a failed saving throw (your choice when you create the glyph), or half as much damage on a successful one.","***Spell Glyph.*** You can store a prepared spell of 3rd level or lower in the glyph by casting it as part of creating the glyph. The spell must target a single creature or an area. The spell being stored has no immediate effect when cast in this way. When the glyph is triggered, the stored spell is cast. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on that creature. If the spell summons hostile creatures or creates harmful objects or traps, they appear as close as possible to the intruder and attack it. If the spell requires concentration, it lasts until the end of its full duration."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the damage of an explosive runes glyph increases by 1d8 for each slot level above 3rd. If you create a spell glyph, you can store any spell of up to the same level as the slot you use for the glyph of warding."],"range":"Touch","components":["V","S","M"],"material":"Incense and powdered diamond worth at least 200 gp, which the spell consumes.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"1 hour","level":3,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/glyph-of-warding","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-goodberry', 'spell', 'Goodberry', 'spell-goodberry', '{"higher_level":[],"index":"goodberry","name":"Goodberry","desc":["Up to ten berries appear in your hand and are infused with magic for the duration. A creature can use its action to eat one berry. Eating a berry restores 1 hit point, and the berry provides enough nourishment to sustain a creature for a day.","The berries lose their potency if they have not been consumed within 24 hours of the casting of this spell."],"range":"Touch","components":["V","S","M"],"material":"A sprig of mistletoe.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[],"url":"/api/2014/spells/goodberry","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-grease', 'spell', 'Grease', 'spell-grease', '{"higher_level":[],"index":"grease","name":"Grease","desc":["Slick grease covers the ground in a 10-foot square centered on a point within range and turns it into difficult terrain for the duration.","When the grease appears, each creature standing in its area must succeed on a dexterity saving throw or fall prone. A creature that enters the area or ends its turn there must also succeed on a dexterity saving throw or fall prone."],"range":"60 feet","components":["V","S","M"],"material":"A bit of pork rind or butter.","ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":1,"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"none"},"area_of_effect":{"type":"cube","size":10},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/grease","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-greater-invisibility', 'spell', 'Greater Invisibility', 'spell-greater-invisibility', '{"higher_level":[],"index":"greater-invisibility","name":"Greater Invisibility","desc":["You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target''s person."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/greater-invisibility","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-greater-restoration', 'spell', 'Greater Restoration', 'spell-greater-restoration', '{"higher_level":[],"index":"greater-restoration","name":"Greater Restoration","desc":["You imbue a creature you touch with positive energy to undo a debilitating effect. You can reduce the target''s exhaustion level by one, or end one of the following effects on the target:","- One effect that charmed or petrified the target","- One curse, including the target''s attunement to a cursed magic item","- Any reduction to one of the target''s ability scores","- One effect reducing the target''s hit point maximum"],"range":"Touch","components":["V","S","M"],"material":"Diamond dust worth at least 100gp, which the spell consumes.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":5,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/greater-restoration","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-guardian-of-faith', 'spell', 'Guardian of Faith', 'spell-guardian-of-faith', '{"higher_level":[],"index":"guardian-of-faith","name":"Guardian of Faith","desc":["A Large spectral guardian appears and hovers for the duration in an unoccupied space of your choice that you can see within range. The guardian occupies that space and is indistinct except for a gleaming sword and shield emblazoned with the symbol of your deity.","Any creature hostile to you that moves to a space within 10 feet of the guardian for the first time on a turn must succeed on a dexterity saving throw. The creature takes 20 radiant damage on a failed save, or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage."],"range":"30 feet","components":["V"],"ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_at_slot_level":{"4":"20"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"cylinder","size":10},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/guardian-of-faith","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-guards-and-wards', 'spell', 'Guards and Wards', 'spell-guards-and-wards', '{"higher_level":[],"index":"guards-and-wards","name":"Guards and Wards","desc":["You create a ward that protects up to 2,500 square feet of floor space (an area 50 feet square, or one hundred 5-foot squares or twenty-five 10-foot squares). The warded area can be up to 20 feet tall, and shaped as you desire. You can ward several stories of a stronghold by dividing the area among them, as long as you can walk into each contiguous area while you are casting the spell.","When you cast this spell, you can specify individuals that are unaffected by any or all of the effects that you choose. You can also specify a password that, when spoken aloud, makes the speaker immune to these effects.","Guards and wards creates the following effects within the warded area.","***Corridors.*** Fog fills all the warded corridors, making them heavily obscured. In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you will believe it is going in the opposite direction from the one it chooses.","***Doors.*** All doors in the warded area are magically locked, as if sealed by an arcane lock spell. In addition, you can cover up to ten doors with an illusion (equivalent to the illusory object function of the minor illusion spell) to make them appear as plain sections of wall.","***Stairs.*** Webs fill all stairs in the warded area from top to bottom, as the web spell. These strands regrow in 10 minutes if they are burned or torn away while guards and wards lasts.","***Other Spell Effect.*** You can place your choice of one of the following magical effects within the warded area of the stronghold.","- Place dancing lights in four corridors. You can designate a simple program that the lights repeat as long as guards and wards lasts.","- Place magic mouth in two locations.","- Place stinking cloud in two locations. The vapors appear in the places you designate; they return within 10 minutes if dispersed by wind while guards and wards lasts.","- Place a constant gust of wind in one corridor or room.","- Place a suggestion in one location. You select an area of up to 5 feet square, and any creature that enters or passes through the area receives the suggestion mentally.","The whole warded area radiates magic. A dispel magic cast on a specific effect, if successful, removes only that effect.","You can create a permanently guarded and warded structure by casting this spell there every day for one year."],"range":"Touch","components":["V","S","M"],"material":"Burning incense, a small measure of brimstone and oil, a knotted string, a small amount of umber hulk blood, and a small silver rod worth at least 10 gp.","ritual":false,"duration":"24 hours","concentration":false,"casting_time":"10 minutes","level":6,"area_of_effect":{"type":"cube","size":2500},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/guards-and-wards","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-guidance', 'spell', 'Guidance', 'spell-guidance', '{"higher_level":[],"index":"guidance","name":"Guidance","desc":["You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":0,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/guidance","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-guiding-bolt', 'spell', 'Guiding Bolt', 'spell-guiding-bolt', '{"index":"guiding-bolt","name":"Guiding Bolt","desc":["A flash of light streaks toward a creature of your choice within range. Make a ranged spell attack against the target. On a hit, the target takes 4d6 radiant damage, and the next attack roll made against this target before the end of your next turn has advantage, thanks to the mystical dim light glittering on the target until then."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 action","level":1,"attack_type":"ranged","damage":{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_at_slot_level":{"1":"4d6","2":"5d6","3":"6d6","4":"7d6","5":"8d6","6":"9d6","7":"10d6","8":"11d6","9":"12d6"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/guiding-bolt","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-gust-of-wind', 'spell', 'Gust of Wind', 'spell-gust-of-wind', '{"higher_level":[],"index":"gust-of-wind","name":"Gust of Wind","desc":["A line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the spell''s duration. Each creature that starts its turn in the line must succeed on a strength saving throw or be pushed 15 feet away from you in a direction following the line.","Any creature in the line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.","The gust disperses gas or vapor, and it extinguishes candles, torches, and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.","As a bonus action on each of your turns before the spell ends, you can change the direction in which the line blasts from you."],"range":"Self","components":["V","S","M"],"material":"A legume seed.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"dc":{"dc_type":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"dc_success":"none"},"area_of_effect":{"type":"line","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/gust-of-wind","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-hallow', 'spell', 'Hallow', 'spell-hallow', '{"higher_level":[],"index":"hallow","name":"Hallow","desc":["You touch a point and infuse an area around it with holy (or unholy) power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect a hallow spell. The affected area is subject to the following effects.","First, celestials, elementals, fey, fiends, and undead can''t enter the area, nor can such creatures charm, frighten, or possess creatures within it. Any creature charmed, frightened, or possessed by such a creature is no longer charmed, frightened, or possessed upon entering the area. You can exclude one or more of those types of creatures from this effect.","Second, you can bind an extra effect to the area. Choose the effect from the following list, or choose an effect offered by the GM. Some of these effects apply to creatures in the area; you can designate whether the effect applies to all creatures, creatures that follow a specific deity or leader, or creatures of a specific sort, such as ores or trolls. When a creature that would be affected enters the spell''s area for the first time on a turn or starts its turn there, it can make a charisma saving throw. On a success, the creature ignores the extra effect until it leaves the area.","***Courage.*** Affected creatures can''t be frightened while in the area.","***Darkness.*** Darkness fills the area. Normal light, as well as magical light created by spells of a lower level than the slot you used to cast this spell, can''t illuminate the area.","***Daylight.*** Bright light fills the area. Magical darkness created by spells of a lower level than the slot you used to cast this spell can''t extinguish the light.","***Energy Protection.*** Affected creatures in the area have resistance to one damage type of your choice, except for bludgeoning, piercing, or slashing.","***Energy Vulnerability.*** Affected creatures in the area have vulnerability to one damage type of your choice, except for bludgeoning, piercing, or slashing.","***Everlasting Rest.*** Dead bodies interred in the area can''t be turned into undead.","***Extradimensional Interference.*** Affected creatures can''t move or travel using teleportation or by extradimensional or interplanar means.","***Fear.*** Affected creatures are frightened while in the area.","***Silence.*** No sound can emanate from within the area, and no sound can reach into it.","***Tongues.*** Affected creatures can communicate with any other creature in the area, even if they don''t share a common language."],"range":"Touch","components":["V","S","M"],"material":"Herbs, oils, and incense worth at least 1,000 gp, which the spell consumes.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"24 hours","level":5,"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"none"},"area_of_effect":{"type":"sphere","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/hallow","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-hallucinatory-terrain', 'spell', 'Hallucinatory Terrain', 'spell-hallucinatory-terrain', '{"higher_level":[],"index":"hallucinatory-terrain","name":"Hallucinatory Terrain","desc":["You make natural terrain in a 150-foot cube in range look, sound, and smell like some other sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren''t changed in appearance.","The tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to see through the illusion. If the difference isn''t obvious by touch, a creature carefully examining the illusion can attempt an Intelligence (Investigation) check against your spell save DC to disbelieve it. A creature who discerns the illusion for what it is, sees it as a vague image superimposed on the terrain."],"range":"300 feet","components":["V","S","M"],"material":"A stone, a twig, and a bit of green plant.","ritual":false,"duration":"24 hours","concentration":false,"casting_time":"10 minutes","level":4,"area_of_effect":{"type":"cube","size":150},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/hallucinatory-terrain","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-harm', 'spell', 'Harm', 'spell-harm', '{"higher_level":[],"index":"harm","name":"Harm","desc":["You unleash a virulent disease on a creature that you can see within range. The target must make a constitution saving throw. On a failed save, it takes 14d6 necrotic damage, or half as much damage on a successful save. The damage can''t reduce the target''s hit points below 1. If the target fails the saving throw, its hit point maximum is reduced for 1 hour by an amount equal to the necrotic damage it took. Any effect that removes a disease allows a creature''s hit point maximum to return to normal before that time passes."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_at_slot_level":{"6":"14d6"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/harm","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-haste', 'spell', 'Haste', 'spell-haste', '{"higher_level":[],"index":"haste","name":"Haste","desc":["Choose a willing creature that you can see within range. Until the spell ends, the target''s speed is doubled, it gains a +2 bonus to AC, it has advantage on dexterity saving throws, and it gains an additional action on each of its turns. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object action.","When the spell ends, the target can''t move or take actions until after its next turn, as a wave of lethargy sweeps over it."],"range":"30 feet","components":["V","S","M"],"material":"A shaving of licorice root.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/haste","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-heal', 'spell', 'Heal', 'spell-heal', '{"index":"heal","name":"Heal","desc":["Choose a creature that you can see within range. A surge of positive energy washes through the creature, causing it to regain 70 hit points. This spell also ends blindness, deafness, and any diseases affecting the target. This spell has no effect on constructs or undead."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, the amount of healing increases by 10 for each slot level above 6th."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":6,"heal_at_slot_level":{"6":"70","7":"80","8":"90","9":"100"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/heal","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-healing-word', 'spell', 'Healing Word', 'spell-healing-word', '{"index":"healing-word","name":"Healing Word","desc":["A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d4 for each slot level above 1st."],"range":"60 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 bonus action","level":1,"heal_at_slot_level":{"1":"1d4 + MOD","2":"2d4 + MOD","3":"3d4 + MOD","4":"4d4 + MOD","5":"5d4 + MOD","6":"6d4 + MOD","7":"7d4 + MOD","8":"8d4 + MOD","9":"9d4 + MOD"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/healing-word","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-heat-metal', 'spell', 'Heat Metal', 'spell-heat-metal', '{"index":"heat-metal","name":"Heat Metal","desc":["Choose a manufactured metal object, such as a metal weapon or a suit of heavy or medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 fire damage when you cast the spell. Until the spell ends, you can use a bonus action on each of your subsequent turns to cause this damage again.","If a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a constitution saving throw or drop the object if it can. If it doesn''t drop the object, it has disadvantage on attack rolls and ability checks until the start of your next turn."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."],"range":"60 feet","components":["V","S","M"],"material":"A piece of iron and a flame.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"2":"2d8","3":"3d8","4":"4d8","5":"5d8","6":"6d8","7":"7d8","8":"8d8","9":"9d8"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"other","desc":"Can choose to not drop the object"},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/heat-metal","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-hellish-rebuke', 'spell', 'Hellish Rebuke', 'spell-hellish-rebuke', '{"index":"hellish-rebuke","name":"Hellish Rebuke","desc":["You point your finger, and the creature that damaged you is momentarily surrounded by hellish flames. The creature must make a dexterity saving throw. It takes 2d10 fire damage on a failed save, or half as much damage on a successful one."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 reaction","level":1,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"1":"2d10","2":"3d10","3":"4d10","4":"5d10","5":"6d10","6":"7d10","7":"8d10","8":"9d10","9":"10d10"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"}],"subclasses":[],"url":"/api/2014/spells/hellish-rebuke","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-heroes-feast', 'spell', 'Heroes'' Feast', 'spell-heroes-feast', '{"higher_level":[],"index":"heroes-feast","name":"Heroes'' Feast","desc":["You bring forth a great feast, including magnificent food and drink. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don''t set in until this hour is over. Up to twelve other creatures can partake of the feast.","A creature that partakes of the feast gains several benefits. The creature is cured of all diseases and poison, becomes immune to poison and being frightened, and makes all wisdom saving throws with advantage. Its hit point maximum also increases by 2d10, and it gains the same number of hit points. These benefits last for 24 hours."],"range":"30 feet","components":["V","S","M"],"material":"A gem-encrusted bowl worth at least 1,000gp, which the spell consumes.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"10 minutes","level":6,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/heroes-feast","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-heroism', 'spell', 'Heroism', 'spell-heroism', '{"higher_level":[],"index":"heroism","name":"Heroism","desc":["A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to being frightened and gains temporary hit points equal to your spellcasting ability modifier at the start of each of its turns. When the spell ends, the target loses any remaining temporary hit points from this spell."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":1,"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/heroism","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-hideous-laughter', 'spell', 'Hideous Laughter', 'spell-hideous-laughter', '{"higher_level":[],"index":"hideous-laughter","name":"Hideous Laughter","desc":["A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a wisdom saving throw or fall prone, becoming incapacitated and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn''t affected.","At the end of each of its turns, and each time it takes damage, the target can make another wisdom saving throw. The target had advantage on the saving throw if it''s triggered by damage. On a success, the spell ends."],"range":"30 feet","components":["V","S","M"],"material":"Tiny tarts and a feather that is waved in the air.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":1,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/hideous-laughter","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-hold-monster', 'spell', 'Hold Monster', 'spell-hold-monster', '{"index":"hold-monster","name":"Hold Monster","desc":["Choose a creature you can see and reach. The target must make a saving throw of Wisdom or be paralyzed for the duration of the spell. This spell has no effect against the undead. At the end of each round, the target can make a new saving throw of Wisdom. If successful, the spell ends for the creature."],"higher_level":["When you cast this spell using a level 6 or higher location, you can target an additional creature for each level of location beyond the fifth. The creatures must be within 30 feet o f each other when you target them."],"range":"90 feet","components":["V","S","M"],"material":"A small piece of iron.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":5,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/hold-monster","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-hold-person', 'spell', 'Hold Person', 'spell-hold-person', '{"index":"hold-person","name":"Hold Person","desc":["Choose a humanoid that you can see within range. The target must succeed on a wisdom saving throw or be paralyzed for the duration. At the end of each of its turns, the target can make another wisdom saving throw. On a success, the spell ends on the target."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, you can target one additional humanoid for each slot level above 2nd. The humanoids must be within 30 feet of each other when you target them."],"range":"60 feet","components":["V","S","M"],"material":"A small, straight piece of iron.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/hold-person","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-holy-aura', 'spell', 'Holy Aura', 'spell-holy-aura', '{"higher_level":[],"index":"holy-aura","name":"Holy Aura","desc":["Divine light washes out from you and coalesces in a soft radiance in a 30-foot radius around you. Creatures of your choice in that radius when you cast this spell shed dim light in a 5-foot radius and have advantage on all saving throws, and other creatures have disadvantage on attack rolls against them until the spell ends. In addition, when a fiend or an undead hits an affected creature with a melee attack, the aura flashes with brilliant light. The attacker must succeed on a constitution saving throw or be blinded until the spell ends."],"range":"Self","components":["V","S","M"],"material":"A tiny reliquary worth at least 1,000gp containing a sacred relic, such as a scrap of cloth from a saint''s robe or a piece of parchment from a religious text.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":8,"area_of_effect":{"type":"sphere","size":30},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/holy-aura","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-hunters-mark', 'spell', 'Hunter''s Mark', 'spell-hunters-mark', '{"index":"hunters-mark","name":"Hunter''s Mark","desc":["You choose a creature you can see within range and mystically mark it as your quarry. Until the spell ends, you deal an extra 1d6 damage to the target whenever you hit it with a weapon attack, and you have advantage on any Wisdom (Perception) or Wisdom (Survival) check you make to find it. If the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to mark a new creature."],"higher_level":["When you cast this spell using a spell slot of 3rd or 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours."],"range":"90 feet","components":["V"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 bonus action","level":1,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[],"url":"/api/2014/spells/hunters-mark","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-hypnotic-pattern', 'spell', 'Hypnotic Pattern', 'spell-hypnotic-pattern', '{"higher_level":[],"index":"hypnotic-pattern","name":"Hypnotic Pattern","desc":["You create a twisting pattern of colors that weaves through the air inside a 30-foot cube within range. The pattern appears for a moment and vanishes. Each creature in the area who sees the pattern must make a wisdom saving throw. On a failed save, the creature becomes charmed for the duration. While charmed by this spell, the creature is incapacitated and has a speed of 0.","The spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor."],"range":"120 feet","components":["S","M"],"material":"A glowing stick of incense or a crystal vial filled with phosphorescent material.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none","desc":"On a failed save, the creature becomes charmed for the duration."},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/hypnotic-pattern","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-ice-storm', 'spell', 'Ice Storm', 'spell-ice-storm', '{"index":"ice-storm","name":"Ice Storm","desc":["A hail of rock-hard ice pounds to the ground in a 20-foot-radius, 40-foot-high cylinder centered on a point within range. Each creature in the cylinder must make a dexterity saving throw. A creature takes 2d8 bludgeoning damage and 4d6 cold damage on a failed save, or half as much damage on a successful one.","Hailstones turn the storm''s area of effect into difficult terrain until the end of your next turn."],"higher_level":["When you cast this spell using a spell slot of 5th level or higher, the bludgeoning damage increases by 1d8 for each slot level above 4th."],"range":"300 feet","components":["V","S","M"],"material":"A pinch of dust and a few drops of water.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_at_slot_level":{"4":"2d8 + 4d6","5":"3d8 + 4d6","6":"4d8 + 4d6","7":"5d8 + 4d6","8":"6d8 + 4d6","9":"7d8 + 4d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"cylinder","size":20},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/ice-storm","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-identify', 'spell', 'Identify', 'spell-identify', '{"higher_level":[],"index":"identify","name":"Identify","desc":["You choose one object that you must touch throughout the casting of the spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has, if any. You learn whether any spells are affecting the item and what they are. If the item was created by a spell, you learn which spell created it.","If you instead touch a creature throughout the casting, you learn what spells, if any, are currently affecting it."],"range":"Touch","components":["V","S","M"],"material":"A pearl worth at least 100gp and an owl feather.","ritual":true,"duration":"Instantaneous","concentration":false,"casting_time":"1 minute","level":1,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/identify","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-illusory-script', 'spell', 'Illusory Script', 'spell-illusory-script', '{"higher_level":[],"index":"illusory-script","name":"Illusory Script","desc":["You write on parchment, paper, or some other suitable writing material and imbue it with a potent illusion that lasts for the duration.","To you and any creatures you designate when you cast the spell, the writing appears normal, written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, you can cause the writing to appear to be an entirely different message, written in a different hand and language, though the language must be one you know.","Should the spell be dispelled, the original script and the illusion both disappear.","A creature with truesight can read the hidden message."],"range":"Touch","components":["S","M"],"material":"A lead-based ink worth at least 10gp, which this spell consumes.","ritual":true,"duration":"10 days","concentration":false,"casting_time":"1 minute","level":1,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/illusory-script","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-imprisonment', 'spell', 'Imprisonment', 'spell-imprisonment', '{"higher_level":[],"index":"imprisonment","name":"Imprisonment","desc":["You create a magical restraint to hold a creature that you can see within range. The target must succeed on a wisdom saving throw or be bound by the spell; if it succeeds, it is immune to this spell if you cast it again. While affected by this spell, the creature doesn''t need to breathe, eat, or drink, and it doesn''t age. Divination spells can''t locate or perceive the target.","When you cast the spell, you choose one of the following forms of imprisonment.","***Burial.*** The target is entombed far beneath the earth in a sphere of magical force that is just large enough to contain the target. Nothing can pass through the sphere, nor can any creature teleport or use planar travel to get into or out of it.","The special component for this version of the spell is a small mithral orb.","***Chaining.*** Heavy chains, firmly rooted in the ground, hold the target in place. The target is restrained until the spell ends, and it can''t move or be moved by any means until then.","The special component for this version of the spell is a fine chain of precious metal.","***Hedged Prison.*** The spell transports the target into a tiny demiplane that is warded against teleportation and planar travel. The demiplane can be a labyrinth, a cage, a tower, or any similar confined structure or area of your choice.","The special component for this version of the spell is a miniature representation of the prison made from jade.","***Minimus Containment.*** The target shrinks to a height of 1 inch and is imprisoned inside a gemstone or similar object. Light can pass through the gemstone normally (allowing the target to see out and other creatures to see in), but nothing else can pass through, even by means of teleportation or planar travel. The gemstone can''t be cut or broken while the spell remains in effect.","The special component for this version of the spell is a large, transparent gemstone, such as a corundum, diamond, or ruby.","***Slumber.*** The target falls asleep and can''t be awoken.","The special component for this version of the spell consists of rare soporific herbs.","***Ending the Spell.*** During the casting of the spell, in any of its versions, you can specify a condition that will cause the spell to end and release the target. The condition can be as specific or as elaborate as you choose, but the GM must agree that the condition is reasonable and has a likelihood of coming to pass. The conditions can be based on a creature''s name, identity, or deity but otherwise must be based on observable actions or qualities and not based on intangibles such as level, class, or hit points.","A dispel magic spell can end the spell only if it is cast as a 9th-level spell, targeting either the prison or the special component used to create it.","You can use a particular special component to create only one prison at a time. If you cast the spell again using the same component, the target of the first casting is immediately freed from its binding."],"range":"30 feet","components":["V","S","M"],"material":"A vellum depiction or a carved statuette in the likeness of the target, and a special component that varies according to the version of the spell you choose, worth at least 500gp per Hit Die of the target.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"1 minute","level":9,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none","desc":"If the creature succeeds, it is immune to this spell if you cast it again"},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/imprisonment","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-incendiary-cloud', 'spell', 'Incendiary Cloud', 'spell-incendiary-cloud', '{"higher_level":[],"index":"incendiary-cloud","name":"Incendiary Cloud","desc":["A swirling cloud of smoke shot through with white-hot embers appears in a 20-foot-radius sphere centered on a point within range. The cloud spreads around corners and is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.","When the cloud appears, each creature in it must make a dexterity saving throw. A creature takes 10d8 fire damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell''s area for the first time on a turn or ends its turn there.","The cloud moves 10 feet directly away from you in a direction that you choose at the start of each of your turns."],"range":"150 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":8,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"8":"10d8"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":20},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/incendiary-cloud","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-inflict-wounds', 'spell', 'Inflict Wounds', 'spell-inflict-wounds', '{"index":"inflict-wounds","name":"Inflict Wounds","desc":["Make a melee spell attack against a creature you can reach. On a hit, the target takes 3d10 necrotic damage."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":1,"attack_type":"melee","damage":{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_at_slot_level":{"1":"3d10","2":"4d10","3":"5d10","4":"6d10","5":"7d10","6":"8d10","7":"9d10","8":"10d10","9":"11d10"}},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/inflict-wounds","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-insect-plague', 'spell', 'Insect Plague', 'spell-insect-plague', '{"index":"insect-plague","name":"Insect Plague","desc":["Swarming, biting locusts fill a 20-foot-radius sphere centered on a point you choose within range. The sphere spreads around corners. The sphere remains for the duration, and its area is lightly obscured. The sphere''s area is difficult terrain.","When the area appears, each creature in it must make a constitution saving throw. A creature takes 4d10 piercing damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell''s area for the first time on a turn or ends its turn there."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d10 for each slot level above 5th."],"range":"300 feet","components":["V","S","M"],"material":"A few grains of sugar, some kernels of grain, and a smear of fat.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":5,"damage":{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_at_slot_level":{"5":"4d10","6":"5d10","7":"6d10","8":"7d10","9":"8d10"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":20},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/insect-plague","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-instant-summons', 'spell', 'Instant Summons', 'spell-instant-summons', '{"higher_level":[],"index":"instant-summons","name":"Instant Summons","desc":["You touch an object weighing 10 pounds or less whose longest dimension is 6 feet or less. The spell leaves an invisible mark on its surface and invisibly inscribes the name of the item on the sapphire you use as the material component. Each time you cast this spell, you must use a different sapphire.","At any time thereafter, you can use your action to speak the item''s name and crush the sapphire. The item instantly appears in your hand regardless of physical or planar distances, and the spell ends.","If another creature is holding or carrying the item, crushing the sapphire doesn''t transport the item to you, but instead you learn who the creature possessing the object is and roughly where that creature is located at that moment.","Dispel magic or a similar effect successfully applied to the sapphire ends this spell''s effect."],"range":"Touch","components":["V","S","M"],"material":"A sapphire worth 1,000 gp.","ritual":true,"duration":"Until dispelled","concentration":false,"casting_time":"1 minute","level":6,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/instant-summons","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-invisibility', 'spell', 'Invisibility', 'spell-invisibility', '{"index":"invisibility","name":"Invisibility","desc":["A creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target''s person. The spell ends for a target that attacks or casts a spell."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."],"range":"Touch","components":["V","S","M"],"material":"An eyelash encased in gum arabic.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/invisibility","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-irresistible-dance', 'spell', 'Irresistible Dance', 'spell-irresistible-dance', '{"higher_level":[],"index":"irresistible-dance","name":"Irresistible Dance","desc":["Choose one creature that you can see within range. The target begins a comic dance in place: shuffling, tapping its feet, and capering for the duration. Creatures that can''t be charmed are immune to this spell.","A dancing creature must use all its movement to dance without leaving its space and has disadvantage on dexterity saving throws and attack rolls. While the target is affected by this spell, other creatures have advantage on attack rolls against it. As an action, a dancing creature makes a wisdom saving throw to regain control of itself. On a successful save, the spell ends."],"range":"30 feet","components":["V"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":6,"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/irresistible-dance","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-jump', 'spell', 'Jump', 'spell-jump', '{"higher_level":[],"index":"jump","name":"Jump","desc":["You touch a creature. The creature''s jump distance is tripled until the spell ends."],"range":"Touch","components":["V","S","M"],"material":"A grasshopper''s hind leg.","ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/jump","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-knock', 'spell', 'Knock', 'spell-knock', '{"higher_level":[],"index":"knock","name":"Knock","desc":["Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.","A target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.","If you choose a target that is held shut with arcane lock, that spell is suppressed for 10 minutes, during which time the target can be opened and shut normally.","When you cast the spell, a loud knock, audible from as far away as 300 feet, emanates from the target object."],"range":"60 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/knock","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-legend-lore', 'spell', 'Legend Lore', 'spell-legend-lore', '{"higher_level":[],"index":"legend-lore","name":"Legend Lore","desc":["Name or describe a person, place, or object. The spell brings to your mind a brief summary of the significant lore about the thing you named. The lore might consist of current tales, forgotten stories, or even secret lore that has never been widely known. If the thing you named isn''t of legendary importance, you gain no information. The more information you already have about the thing, the more precise and detailed the information you receive is.","The information you learn is accurate but might be couched in figurative language. For example, if you have a mysterious magic axe on hand the spell might yield this information: \"Woe to the evildoer whose hand touches the axe, for even the haft slices the hand of the evil ones. Only a true Child of Stone, lover and beloved of Moradin, may awaken the true powers of the axe, and only with the sacred word *Rudnogg* on the lips.\""],"range":"Self","components":["V","S","M"],"material":"Incense worth at least 250 gp, which the spell consumes, and four ivory strips worth at least 50 gp each.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"10 minutes","level":5,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/legend-lore","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-lesser-restoration', 'spell', 'Lesser Restoration', 'spell-lesser-restoration', '{"higher_level":[],"index":"lesser-restoration","name":"Lesser Restoration","desc":["You touch a creature and can end either one disease or one condition afflicting it. The condition can be blinded, deafened, paralyzed, or poisoned."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"life","name":"Life","url":"/api/2014/subclasses/life"},{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"url":"/api/2014/spells/lesser-restoration","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-levitate', 'spell', 'Levitate', 'spell-levitate', '{"higher_level":[],"index":"levitate","name":"Levitate","desc":["One creature or object of your choice that you can see within range rises vertically, up to 20 feet, and remains suspended there for the duration. The spell can levitate a target that weighs up to 500 pounds. An unwilling creature that succeeds on a constitution saving throw is unaffected.","The target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target''s altitude by up to 20 feet in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can use your action to move the target, which must remain within the spell''s range.","When the spell ends, the target floats gently to the ground if it is still aloft."],"range":"60 feet","components":["V","S","M"],"material":"Either a small leather loop or a piece of golden wire bent into a cup shape with a long shank on one end.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/levitate","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-light', 'spell', 'Light', 'spell-light', '{"higher_level":[],"index":"light","name":"Light","desc":["You touch one object that is no larger than 10 feet in any dimension. Until the spell ends, the object sheds bright light in a 20-foot radius and dim light for an additional 20 feet. The light can be colored as you like. Completely covering the object with something opaque blocks the light. The spell ends if you cast it again or dismiss it as an action.","If you target an object held or worn by a hostile creature, that creature must succeed on a dexterity saving throw to avoid the spell."],"range":"Touch","components":["V","M"],"material":"A firefly or phosphorescent moss.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":0,"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"none"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/light","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-lightning-bolt', 'spell', 'Lightning Bolt', 'spell-lightning-bolt', '{"index":"lightning-bolt","name":"Lightning Bolt","desc":["A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you in a direction you choose. Each creature in the line must make a dexterity saving throw. A creature takes 8d6 lightning damage on a failed save, or half as much damage on a successful one.","The lightning ignites flammable objects in the area that aren''t being worn or carried."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."],"range":"Self","components":["V","S","M"],"material":"A bit of fur and a rod of amber, crystal, or glass.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":3,"damage":{"damage_type":{"index":"lightning","name":"Lightning","url":"/api/2014/damage-types/lightning"},"damage_at_slot_level":{"3":"8d6","4":"9d6","5":"10d6","6":"11d6","7":"12d6","8":"13d6","9":"14d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"line","size":100},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/lightning-bolt","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-locate-animals-or-plants', 'spell', 'Locate Animals or Plants', 'spell-locate-animals-or-plants', '{"higher_level":[],"index":"locate-animals-or-plants","name":"Locate Animals or Plants","desc":["Describe or name a specific kind of beast or plant. Concentrating on the voice of nature in your surroundings, you learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present."],"range":"Self","components":["V","S","M"],"material":"A bit of fur from a bloodhound.","ritual":true,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/locate-animals-or-plants","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-locate-creature', 'spell', 'Locate Creature', 'spell-locate-creature', '{"higher_level":[],"index":"locate-creature","name":"Locate Creature","desc":["Describe or name a creature that is familiar to you. You sense the direction to the creature''s location, as long as that creature is within 1,000 feet of you. If the creature is moving, you know the direction of its movement.","The spell can locate a specific creature known to you, or the nearest creature of a specific kind (such as a human or a unicorn), so long as you have seen such a creature up close--within 30 feet--at least once. If the creature you described or named is in a different form, such as being under the effects of a polymorph spell, this spell doesn''t locate the creature.","This spell can''t locate a creature if running water at least 10 feet wide blocks a direct path between you and the creature."],"range":"Self","components":["V","S","M"],"material":"A bit of fur from a bloodhound.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":4,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/locate-creature","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-locate-object', 'spell', 'Locate Object', 'spell-locate-object', '{"higher_level":[],"index":"locate-object","name":"Locate Object","desc":["Describe or name an object that is familiar to you. You sense the direction to the object''s location, as long as that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.","The spell can locate a specific object known to you, as long as you have seen it up close--within 30 feet--at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.","This spell can''t locate an object if any thickness of lead, even a thin sheet, blocks a direct path between you and the object."],"range":"Self","components":["V","S","M"],"material":"A forked twig.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/locate-object","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-longstrider', 'spell', 'Longstrider', 'spell-longstrider', '{"index":"longstrider","name":"Longstrider","desc":["You touch a creature. The target''s speed increases by 10 feet until the spell ends."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each spell slot above 1st."],"range":"Touch","components":["V","S","M"],"material":"A pinch of dirt.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/longstrider","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mage-armor', 'spell', 'Mage Armor', 'spell-mage-armor', '{"higher_level":[],"index":"mage-armor","name":"Mage Armor","desc":["You touch a willing creature who isn''t wearing armor, and a protective magical force surrounds it until the spell ends. The target''s base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or if you dismiss the spell as an action."],"range":"Touch","components":["V","S","M"],"material":"A piece of cured leather.","ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/mage-armor","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mage-hand', 'spell', 'Mage Hand', 'spell-mage-hand', '{"higher_level":[],"index":"mage-hand","name":"Mage Hand","desc":["A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration or until you dismiss it as an action. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again.","You can use your action to control the hand. You can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial. You can move the hand up to 30 feet each time you use it.","The hand can''t attack, activate magic items, or carry more than 10 pounds."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":0,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/mage-hand","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-magic-circle', 'spell', 'Magic Circle', 'spell-magic-circle', '{"index":"magic-circle","name":"Magic Circle","desc":["You create a 10-foot radius, 20-foot-tall cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear whenever the cylinder intersects with the floor or other surface.","Choose one or more of the following types of creatures: celestials, elementals, fey, fiends, or undead. The circle affects a creature of the chosen type in the following ways:","- The creature can''t willingly enter the cylinder by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a charisma saving throw.","- The creature has disadvantage on attack rolls against targets within the cylinder.","- Targets within the cylinder can''t be charmed, frightened, or possessed by the creature.","When you cast this spell, you can elect to cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the cylinder and protecting targets outside it."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the duration increases by 1 hour for each slot level above 3rd."],"range":"10 feet","components":["V","S","M"],"material":"Holy water or powdered silver and iron worth at least 100 gp, which the spell consumes.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 minute","level":3,"area_of_effect":{"type":"cylinder","size":10},"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"other","desc":"If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a Charisma saving throw."},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/magic-circle","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-magic-jar', 'spell', 'Magic Jar', 'spell-magic-jar', '{"higher_level":[],"index":"magic-jar","name":"Magic Jar","desc":["Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell''s material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container''s space. You can''t move or use reactions. The only action you can take is to project your soul up to 100 feet out of the container, either returning to your living body (and ending the spell) or attempting to possess a humanoids body.","You can attempt to possess any humanoid within 100 feet of you that you can see (creatures warded by a protection from evil and good or magic circle spell can''t be possessed). The target must make a charisma saving throw. On a failure, your soul moves into the target''s body, and the target''s soul becomes trapped in the container. On a success, the target resists your efforts to possess it, and you can''t attempt to possess it again for 24 hours.","Once you possess a creature''s body, you control it. Your game statistics are replaced by the statistics of the creature, though you retain your alignment and your Intelligence, Wisdom, and Charisma scores. You retain the benefit of your own class features. If the target has any class levels, you can''t use any of its class features.","Meanwhile, the possessed creature''s soul can perceive from the container using its own senses, but it can''t move or take actions at all.","While possessing a body, you can use your action to return from the host body to the container if it is within 100 feet of you, returning the host creature''s soul to its body. If the host body dies while you''re in it, the creature dies, and you must make a charisma saving throw against your own spellcasting DC. On a success, you return to the container if it is within 100 feet of you. Otherwise, you die.","If the container is destroyed or the spell ends, your soul immediately returns to your body. If your body is more than 100 feet away from you or if your body is dead when you attempt to return to it, you die. If another creature''s soul is in the container when it is destroyed, the creature''s soul returns to its body if the body is alive and within 100 feet. Otherwise, that creature dies.","When the spell ends, the container is destroyed."],"range":"Self","components":["V","S","M"],"material":"A gem, crystal, reliquary, or some other ornamental container worth at least 500 gp.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"1 minute","level":6,"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"other","desc":"On a failure, your soul moves into the target''s body, and the target''s soul becomes trapped in the container. On a success, the target resists your efforts to possess it, and you can''t attempt to possess it again for 24 hours."},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/magic-jar","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-magic-missile', 'spell', 'Magic Missile', 'spell-magic-missile', '{"index":"magic-missile","name":"Magic Missile","desc":["You create three glowing darts of magical force. Each dart hits a creature of your choice that you can see within range. A dart deals 1d4 + 1 force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the spell creates one more dart for each slot level above 1st."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":1,"damage":{"damage_type":{"index":"force","name":"Force","url":"/api/2014/damage-types/force"},"damage_at_slot_level":{"1":"3d4 + 3","2":"4d4 + 4","3":"5d4 + 5","4":"6d4 + 6","5":"7d4 + 7","6":"8d4 + 8","7":"9d4 + 9","8":"10d4 + 10","9":"11d4 + 11"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/magic-missile","updated_at":"2026-05-29T02:18:25.917Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-magic-mouth', 'spell', 'Magic Mouth', 'spell-magic-mouth', '{"higher_level":[],"index":"magic-mouth","name":"Magic Mouth","desc":["You plant a message to an object in the range of the spell. The message is verbalized when the trigger conditions are met. Choose an object that you see, and that is not worn or carried by another creature. Then say the message, which should not exceed 25 words but listening can take up to 10 minutes. Finally, establish the circumstances that trigger the spell to deliver your message.","When these conditions are satisfied, a magical mouth appears on the object and it articulates the message imitating your voice, the same tone used during implantation of the message. If the selected object has a mouth or something that approaches such as the mouth of a statue, the magic mouth come alive at this point, giving the illusion that the words come from the mouth of the object.","When you cast this spell, you may decide that the spell ends when the message is delivered or it can persist and repeat the message whenever circumstances occur.","The triggering circumstance can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it."],"range":"30 feet","components":["V","S","M"],"material":"A honeycomb and jade dust of at least 10 inches, the spell consumes.","ritual":true,"duration":"Until dispelled","concentration":false,"casting_time":"1 minute","level":2,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/magic-mouth","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-magic-weapon', 'spell', 'Magic Weapon', 'spell-magic-weapon', '{"index":"magic-weapon","name":"Magic Weapon","desc":["You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the bonus increases to +2. When you use a spell slot of 6th level or higher, the bonus increases to +3."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 bonus action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/magic-weapon","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-magnificent-mansion', 'spell', 'Magnificent Mansion', 'spell-magnificent-mansion', '{"higher_level":[],"index":"magnificent-mansion","name":"Magnificent Mansion","desc":["You conjure an extradimensional dwelling in range that lasts for the duration. You choose where its one entrance is located. The entrance shimmers faintly and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the portal remains open. You can open or close the portal if you are within 30 feet of it. While closed, the portal is invisible.","Beyond the portal is a magnificent foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm.","You can create any floor plan you like, but the space can''t exceed 50 cubes, each cube being 10 feet on each side. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine course banquet for up to 100 people. A staff of 100 near-transparent servants attends all who enter. You decide the visual appearance of these servants and their attire. They are completely obedient to your orders. Each servant can perform any task a normal human servant could perform, but they can''t attack or take any action that would directly harm another creature. Thus the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can go anywhere in the mansion but can''t leave it. Furnishings and other objects created by this spell dissipate into smoke if removed from the mansion. When the spell ends, any creatures inside the extradimensional space are expelled into the open spaces nearest to the entrance."],"range":"300 feet","components":["V","S","M"],"material":"A miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp.","ritual":false,"duration":"24 hours","concentration":false,"casting_time":"1 minute","level":7,"area_of_effect":{"type":"cube","size":5},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/magnificent-mansion","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-major-image', 'spell', 'Major Image', 'spell-major-image', '{"index":"major-image","name":"Major Image","desc":["You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot cube. The image appears at a spot that you can see within range and lasts for the duration. It seems completely real, including sounds, smells, and temperature appropriate to the thing depicted. You can''t create sufficient heat or cold to cause damage, a sound loud enough to deal thunder damage or deafen a creature, or a smell that might sicken a creature (like a troglodyte''s stench).","As long as you are within range of the illusion, you can use your action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.","Physical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the spell lasts until dispelled, without requiring your concentration."],"range":"120 feet","components":["V","S","M"],"material":"A bit of fleece.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":3,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/major-image","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mass-cure-wounds', 'spell', 'Mass Cure Wounds', 'spell-mass-cure-wounds', '{"index":"mass-cure-wounds","name":"Mass Cure Wounds","desc":["A wave of healing energy washes out from a point of your choice within range. Choose up to six creatures in a 30-foot-radius sphere centered on that point. Each target regains hit points equal to 3d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs."],"higher_level":["When you cast this spell using a spell slot of 6th level or higher, the healing increases by 1d8 for each slot level above 5th."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":5,"heal_at_slot_level":{"5":"3d8 + MOD","6":"4d8 + MOD","7":"5d8 + MOD","8":"6d8 + MOD","9":"7d8 + MOD"},"area_of_effect":{"type":"sphere","size":30},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"life","name":"Life","url":"/api/2014/subclasses/life"}],"url":"/api/2014/spells/mass-cure-wounds","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mass-heal', 'spell', 'Mass Heal', 'spell-mass-heal', '{"higher_level":[],"index":"mass-heal","name":"Mass Heal","desc":["A flood of healing energy flows from you into injured creatures around you. You restore up to 700 hit points, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell are also cured of all diseases and any effect making them blinded or deafened. This spell has no effect on undead or constructs."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":9,"heal_at_slot_level":{"9":"700"},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/mass-heal","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mass-healing-word', 'spell', 'Mass Healing Word', 'spell-mass-healing-word', '{"index":"mass-healing-word","name":"Mass Healing Word","desc":["As you call out words of restoration, up to six creatures of your choice that you can see within range regain hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the healing increases by 1d4 for each slot level above 3rd."],"range":"60 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 bonus action","level":3,"heal_at_slot_level":{"3":"1d4 + MOD","4":"2d4 + MOD","5":"3d4 + MOD","6":"4d4 + MOD","7":"5d4 + MOD","8":"6d4 + MOD","9":"7d4 + MOD"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/mass-healing-word","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mass-suggestion', 'spell', 'Mass Suggestion', 'spell-mass-suggestion', '{"index":"mass-suggestion","name":"Mass Suggestion","desc":["You suggest a course of activity (limited to a sentence or two) and magically influence up to twelve creatures of your choice that you can see within range and that can hear and understand you. Creatures that can''t be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act automatically negates the effect of the spell.","Each target must make a wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.","You can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a group of soldiers give all their money to the first beggar they meet. If the condition isn''t met before the spell ends, the activity isn''t performed.","If you or any of your companions damage a creature affected by this spell, the spell ends for that creature."],"higher_level":["When you cast this spell using a 7th-level spell slot, the duration is 10 days. When you use an 8th-level spell slot, the duration is 30 days. When you use a 9th-level spell slot, the duration is a year and a day."],"range":"60 feet","components":["V","M"],"material":"A snake''s tongue and either a bit of honeycomb or a drop of sweet oil.","ritual":false,"duration":"24 hours","concentration":false,"casting_time":"1 action","level":6,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/mass-suggestion","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-maze', 'spell', 'Maze', 'spell-maze', '{"higher_level":[],"index":"maze","name":"Maze","desc":["You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze.","The target can use its action to attempt to escape. When it does so, it makes a DC 20 Intelligence check. If it succeeds, it escapes, and the spell ends (a minotaur or goristro demon automatically succeeds).","When the spell ends, the target reappears in the space it left or, if that space is occupied, in the nearest unoccupied space."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":8,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/maze","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-meld-into-stone', 'spell', 'Meld Into Stone', 'spell-meld-into-stone', '{"higher_level":[],"index":"meld-into-stone","name":"Meld Into Stone","desc":["You step into a stone object or surface large enough to fully contain your body, melding yourself and all the equipment you carry with the stone for the duration. Using your movement, you step into the stone at a point you can touch. Nothing of your presence remains visible or otherwise detectable by nonmagical senses.","While merged with the stone, you can''t see what occurs outside it, and any Wisdom (Perception) checks you make to hear sounds outside it are made with disadvantage. You remain aware of the passage of time and can cast spells on yourself while merged in the stone. You can use your movement to leave the stone where you entered it, which ends the spell. You otherwise can''t move.","Minor physical damage to the stone doesn''t harm you, but its partial destruction or a change in its shape (to the extent that you no longer fit within it) expels you and deals 6d6 bludgeoning damage to you. The stone''s complete destruction (or transmutation into a different substance) expels you and deals 50 bludgeoning damage to you. If expelled, you fall prone in an unoccupied space closest to where you first entered."],"range":"Touch","components":["V","S"],"ritual":true,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/meld-into-stone","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mending', 'spell', 'Mending', 'spell-mending', '{"higher_level":[],"index":"mending","name":"Mending","desc":["This spell repairs a single break or tear in an object you touch, such as a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no longer than 1 foot in any dimension, you mend it, leaving no trace of the former damage.","This spell can physically repair a magic item or construct, but the spell can''t restore magic to such an object."],"range":"Touch","components":["V","S","M"],"material":"Two lodestones.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 minute","level":0,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/mending","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-message', 'spell', 'Message', 'spell-message', '{"higher_level":[],"index":"message","name":"Message","desc":["You point your finger toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.","You can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence, 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood blocks the spell. The spell doesn''t have to follow a straight line and can travel freely around corners or through openings."],"range":"120 feet","components":["V","S","M"],"material":"A short piece of copper wire.","ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 action","level":0,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/message","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-meteor-swarm', 'spell', 'Meteor Swarm', 'spell-meteor-swarm', '{"higher_level":[],"index":"meteor-swarm","name":"Meteor Swarm","desc":["Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius sphere centered on each point you choose must make a dexterity saving throw. The sphere spreads around corners. A creature takes 20d6 fire damage and 20d6 bludgeoning damage on a failed save, or half as much damage on a successful one. A creature in the area of more than one fiery burst is affected only once.","The spell damages objects in the area and ignites flammable objects that aren''t being worn or carried."],"range":"1 mile","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":9,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"9":"20d6 + 20d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":40},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/meteor-swarm","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mind-blank', 'spell', 'Mind Blank', 'spell-mind-blank', '{"higher_level":[],"index":"mind-blank","name":"Mind Blank","desc":["Until the spell ends, one willing creature you touch is immune to psychic damage, any effect that would sense its emotions or read its thoughts, divination spells, and the charmed condition. The spell even foils wish spells and spells or effects of similar power used to affect the target''s mind or to gain information about the target."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"24 hours","concentration":false,"casting_time":"1 action","level":8,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/mind-blank","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-minor-illusion', 'spell', 'Minor Illusion', 'spell-minor-illusion', '{"higher_level":[],"index":"minor-illusion","name":"Minor Illusion","desc":["You create a sound or an image of an object within range that lasts for the duration. The illusion also ends if you dismiss it as an action or cast this spell again.","If you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else''s voice, a lion''s roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.","If you create an image of an object--such as a chair, muddy footprints, or a small chest--it must be no larger than a 5-foot cube. The image can''t create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, because things can pass through it.","If a creature uses its action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature."],"range":"30 feet","components":["S","M"],"material":"A bit of fleece.","ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":0,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/minor-illusion","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mirage-arcane', 'spell', 'Mirage Arcane', 'spell-mirage-arcane', '{"higher_level":[],"index":"mirage-arcane","name":"Mirage Arcane","desc":["You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. The terrain''s general shape remains the same, however. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road.","Similarly, you can alter the appearance of structures, or add them where none are present. The spell doesn''t disguise, conceal, or add creatures.","The illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into difficult terrain (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell''s area disappears immediately.","Creatures with truesight can see through the illusion to the terrain''s true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion''s presence, the creature can still physically interact with the illusion."],"range":"Sight","components":["V","S"],"ritual":false,"duration":"10 days","concentration":false,"casting_time":"10 minutes","level":7,"area_of_effect":{"type":"cube","size":5280},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/mirage-arcane","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mirror-image', 'spell', 'Mirror Image', 'spell-mirror-image', '{"higher_level":[],"index":"mirror-image","name":"Mirror Image","desc":["Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it''s impossible to track which image is real. You can use your action to dismiss the illusory duplicates.","Each time a creature targets you with an attack during the spell''s duration, roll a d20 to determine whether the attack instead targets one of your duplicates.","If you have three duplicates, you must roll a 6 or higher to change the attack''s target to a duplicate. With two duplicates, you must roll an 8 or higher. With one duplicate, you must roll an 11 or higher.","A duplicate''s AC equals 10 + your Dexterity modifier. If an attack hits a duplicate, the duplicate is destroyed. A duplicate can be destroyed only by an attack that hits it. It ignores all other damage and effects. The spell ends when all three duplicates are destroyed.","A creature is unaffected by this spell if it can''t see, if it relies on senses other than sight, such as blindsight, or if it can perceive illusions as false, as with truesight."],"range":"Self","components":["V","S"],"ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/mirror-image","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-mislead', 'spell', 'Mislead', 'spell-mislead', '{"higher_level":[],"index":"mislead","name":"Mislead","desc":["You become invisible at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends if you attack or cast a spell.","You can use your action to move your illusory double up to twice your speed and make it gesture, speak, and behave in whatever way you choose.","You can see through its eyes and hear through its ears as if you were located where it is. On each of your turns as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings."],"range":"Self","components":["S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":5,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/mislead","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-misty-step', 'spell', 'Misty Step', 'spell-misty-step', '{"higher_level":[],"index":"misty-step","name":"Misty Step","desc":["Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see."],"range":"Self","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 bonus action","level":2,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/misty-step","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-modify-memory', 'spell', 'Modify Memory', 'spell-modify-memory', '{"index":"modify-memory","name":"Modify Memory","desc":["You attempt to reshape another creature''s memories. One creature that you can see must make a wisdom saving throw. If you are fighting the creature, it has advantage on the saving throw. On a failed save, the target becomes charmed by you for the duration. The charmed target is incapacitated and unaware of its surroundings, though it can still hear you. If it takes any damage or is targeted by another spell, this spell ends, and none of the target''s memories are modified.","While this charm lasts, you can affect the target''s memory of an event that it experienced within the last 24 hours and that lasted no more than 10 minutes. You can permanently eliminate all memory of the event, allow the target to recall the event with perfect clarity and exacting detail, change its memory of the details of the event, or create a memory of some other event.","You must speak to the target to describe how its memories are affected, and it must be able to understand your language for the modified memories to take root. Its mind fills in any gaps in the details of your description. If the spell ends before you have finished describing the modified memories, the creature''s memory isn''t altered. Otherwise, the modified memories take hold when the spell ends.","A modified memory doesn''t necessarily affect how a creature behaves, particularly if the memory contradicts the creature''s natural inclinations, alignment, or beliefs. An illogical modified memory, such as implanting a memory of how much the creature enjoyed dousing itself in acid, is dismissed, perhaps as a bad dream. The GM might deem a modified memory too nonsensical to affect a creature in a significant manner.","A remove curse or greater restoration spell cast on the target restores the creature''s true memory."],"higher_level":["If you cast this spell using a spell slot of 6th level or higher, you can alter the target''s memories of an event that took place up to 7 days ago (6th level), 30 days ago (7th level), 1 year ago (8th level), or any time in the creature''s past (9th level)."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":5,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/modify-memory","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-moonbeam', 'spell', 'Moonbeam', 'spell-moonbeam', '{"index":"moonbeam","name":"Moonbeam","desc":["A silvery beam of pale light shines down in a 5-foot radius, 40-foot-high cylinder centered on a point within range. Until the spell ends, dim light fills the cylinder.","When a creature enters the spell''s area for the first time on a turn or starts its turn there, it is engulfed in ghostly flames that cause searing pain, and it must make a constitution saving throw. It takes 2d10 radiant damage on a failed save, or half as much damage on a successful one.","A shapechanger makes its saving throw with disadvantage. If it fails, it also instantly reverts to its original form and can''t assume a different form until it leaves the spell''s light.","On each of your turns after you cast this spell, you can use an action to move the beam 60 feet in any direction."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1dl0 for each slot level above 2nd."],"range":"120 feet","components":["V","S","M"],"material":"Several seeds of any moonseed plant and a piece of opalescent feldspar.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"damage":{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_at_slot_level":{"2":"2d10","3":"3d10","4":"4d10","5":"5d10","6":"6d10","7":"7d10","8":"8d10","9":"9d10"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"area_of_effect":{"type":"cylinder","size":5},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/moonbeam","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-move-earth', 'spell', 'Move Earth', 'spell-move-earth', '{"higher_level":[],"index":"move-earth","name":"Move Earth","desc":["Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area''s elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can''t exceed half the area''s largest dimension. So, if you affect a 40-foot square, you can create a pillar up to 20 feet high, raise or lower the square''s elevation by up to 20 feet, dig a trench up to 20 feet deep, and so on. It takes 10 minutes for these changes to complete.","At the end of every 10 minutes you spend concentrating on the spell, you can choose a new area of terrain to affect.","Because the terrain''s transformation occurs slowly, creatures in the area can''t usually be trapped or injured by the ground''s movement.","This spell can''t manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse.","Similarly, this spell doesn''t directly affect plant growth. The moved earth carries any plants along with it."],"range":"120 feet","components":["V","S","M"],"material":"An iron blade and a small bag containing a mixture of soils--clay, loam, and sand.","ritual":false,"duration":"Up to 2 hours","concentration":true,"casting_time":"1 action","level":6,"area_of_effect":{"type":"cone","size":40},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/move-earth","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-nondetection', 'spell', 'Nondetection', 'spell-nondetection', '{"higher_level":[],"index":"nondetection","name":"Nondetection","desc":["For the duration, you hide a target that you touch from divination magic. The target can be a willing creature or a place or an object no larger than 10 feet in any dimension. The target can''t be targeted by any divination magic or perceived through magical scrying sensors."],"range":"Touch","components":["V","S","M"],"material":"A pinch of diamond dust worth 25 gp sprinkled over the target, which the spell consumes.","ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/nondetection","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-pass-without-trace', 'spell', 'Pass Without Trace', 'spell-pass-without-trace', '{"higher_level":[],"index":"pass-without-trace","name":"Pass Without Trace","desc":["A veil of shadows and silence radiates from you, masking you and your companions from detection. For the duration, each creature you choose within 30 feet of you (including you) has a +10 bonus to Dexterity (Stealth) checks and can''t be tracked except by magical means. A creature that receives this bonus leaves behind no tracks or other traces of its passage."],"range":"Self","components":["V","S","M"],"material":"Ashes from a burned leaf of mistletoe and a sprig of spruce.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/pass-without-trace","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-passwall', 'spell', 'Passwall', 'spell-passwall', '{"higher_level":[],"index":"passwall","name":"Passwall","desc":["A passage appears at a point of your choice that you can see on a wooden, plaster, or stone surface (such as a wall, a ceiling, or a floor) within range, and lasts for the duration. You choose the opening''s dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it.","When the opening disappears, any creatures or objects still in the passage created by the spell are safely ejected to an unoccupied space nearest to the surface on which you cast the spell."],"range":"30 feet","components":["V","S","M"],"material":"A pinch of sesame seeds.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":5,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/passwall","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-phantasmal-killer', 'spell', 'Phantasmal Killer', 'spell-phantasmal-killer', '{"index":"phantasmal-killer","name":"Phantasmal Killer","desc":["You tap into the nightmares of a creature you can see within range and create an illusory manifestation of its deepest fears, visible only to that creature. The target must make a wisdom saving throw. On a failed save, the target becomes frightened for the duration. At the start of each of the target''s turns before the spell ends, the target must succeed on a wisdom saving throw or take 4d10 psychic damage. On a successful save, the spell ends."],"higher_level":["When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d10 for each slot level above 4th."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"psychic","name":"Psychic","url":"/api/2014/damage-types/psychic"},"damage_at_slot_level":{"4":"4d10"}},"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/phantasmal-killer","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-phantom-steed', 'spell', 'Phantom Steed', 'spell-phantom-steed', '{"higher_level":[],"index":"phantom-steed","name":"Phantom Steed","desc":["A Large quasi-real, horselike creature appears on the ground in an unoccupied space of your choice within range. You decide the creature''s appearance, but it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is carried more than 10 feet away from the steed.","For the duration, you or a creature you choose can ride the steed. The creature uses the statistics for a riding horse, except it has a speed of 100 feet and can travel 10 miles in an hour, or 13 miles at a fast pace. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends if you use an action to dismiss it or if the steed takes any damage."],"range":"30 feet","components":["V","S"],"ritual":true,"duration":"1 hour","concentration":false,"casting_time":"1 minute","level":3,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/phantom-steed","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-planar-ally', 'spell', 'Planar Ally', 'spell-planar-ally', '{"higher_level":[],"index":"planar-ally","name":"Planar Ally","desc":["You beseech an otherworldly entity for aid. The being must be known to you: a god, a primordial, a demon prince, or some other being of cosmic power. That entity sends a celestial, an elemental, or a fiend loyal to it to aid you, making the creature appear in an unoccupied space within range. If you know a specific creature''s name, you can speak that name when you cast this spell to request that creature, though you might get a different creature anyway (GM''s choice).","When the creature appears, it is under no compulsion to behave in any particular way. You can ask the creature to perform a service in exchange for payment, but it isn''t obliged to do so. The requested task could range from simple (fly us across the chasm, or help us fight a battle) to complex (spy on our enemies, or protect us during our foray into the dungeon). You must be able to communicate with the creature to bargain for its services.","Payment can take a variety of forms. A celestial might require a sizable donation of gold or magic items to an allied temple, while a fiend might demand a living sacrifice or a gift of treasure. Some creatures might exchange their service for a quest undertaken by you.","As a rule of thumb, a task that can be measured in minutes requires a payment worth 100 gp per minute. A task measured in hours requires 1,000 gp per hour. And a task measured in days (up to 10 days) requires 10,000 gp per day. The GM can adjust these payments based on the circumstances under which you cast the spell. If the task is aligned with the creature''s ethos, the payment might be halved or even waived. Nonhazardous tasks typically require only half the suggested payment, while especially dangerous tasks might require a greater gift. Creatures rarely accept tasks that seem suicidal.","After the creature completes the task, or when the agreed-upon duration of service expires, the creature returns to its home plane after reporting back to you, if appropriate to the task and if possible. If you are unable to agree on a price for the creature''s service, the creature immediately returns to its home plane.","A creature enlisted to join your group counts as a member of it, receiving a full share of experience points awarded."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"10 minutes","level":6,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/planar-ally","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-planar-binding', 'spell', 'Planar Binding', 'spell-planar-binding', '{"index":"planar-binding","name":"Planar Binding","desc":["With this spell, you attempt to bind a celestial, an elemental, a fey, or a fiend to your service. The creature must be within range for the entire casting of the spell. (Typically, the creature is first summoned into the center of an inverted magic circle in order to keep it trapped while this spell is cast.) At the completion of the casting, the target must make a charisma saving throw. On a failed save, it is bound to serve you for the duration. If the creature was summoned or created by another spell, that spell''s duration is extended to match the duration of this spell.","A bound creature must follow your instructions to the best of its ability. You might command the creature to accompany you on an adventure, to guard a location, or to deliver a message. The creature obeys the letter of your instructions, but if the creature is hostile to you, it strives to twist your words to achieve its own objectives. If the creature carries out your instructions completely before the spell ends, it travels to you to report this fact if you are on the same plane of existence. If you are on a different plane of existence, it returns to the place where you bound it and remains there until the spell ends."],"higher_level":["When you cast this spell using a spell slot of a higher level, the duration increases to 10 days with a 6th-level slot, to 30 days with a 7th-level slot, to 180 days with an 8th-level slot, and to a year and a day with a 9th-level spell slot."],"range":"60 feet","components":["V","S","M"],"material":"A jewel worth at least 1,000 gp, which the spell consumes.","ritual":false,"duration":"24 hours","concentration":false,"casting_time":"1 hour","level":5,"dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"none"},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/planar-binding","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-plane-shift', 'spell', 'Plane Shift', 'spell-plane-shift', '{"higher_level":[],"index":"plane-shift","name":"Plane Shift","desc":["You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as the City of Brass on the Elemental Plane of Fire or the palace of Dispater on the second level of the Nine Hells, and you appear in or near that destination. If you are trying to reach the City of Brass, for example, you might arrive in its Street of Steel, before its Gate of Ashes, or looking at the city from across the Sea of Fire, at the GM''s discretion.","Alternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle.","You can use this spell to banish an unwilling creature to another plane. Choose a creature within your reach and make a melee spell attack against it. On a hit, the creature must make a charisma saving throw. If the creature fails this save, it is transported to a random location on the plane of existence you specify. A creature so transported must find its own way back to your current plane of existence."],"range":"Touch","components":["V","S","M"],"material":"A forked, metal rod worth at least 250 gp, attuned to a particular plane of existence.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":7,"attack_type":"melee","dc":{"dc_type":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc_success":"none","desc":"If the creature fails this save, it is transported to a random location on the plane of existence you specify. A creature so transported must find its own way back to your current plane of existence."},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/plane-shift","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-plant-growth', 'spell', 'Plant Growth', 'spell-plant-growth', '{"higher_level":[],"index":"plant-growth","name":"Plant Growth","desc":["This spell channels vitality into plants within a specific area. There are two possible uses for the spell, granting either immediate or long-term benefits.","If you cast this spell using 1 action, choose a point within range. All normal plants in a 100-foot radius centered on that point become thick and overgrown. A creature moving through the area must spend 4 feet of movement for every 1 foot it moves.","You can exclude one or more areas of any size within the spell''s area from being affected.","If you cast this spell over 8 hours, you enrich the land. All plants in a half-mile radius centered on a point within range become enriched for 1 year. The plants yield twice the normal amount of food when harvested."],"range":"150 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/plant-growth","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-poison-spray', 'spell', 'Poison Spray', 'spell-poison-spray', '{"higher_level":[],"index":"poison-spray","name":"Poison Spray","desc":["You extend your hand toward a creature you can see within range and project a puff of noxious gas from your palm. The creature must succeed on a constitution saving throw or take 1d12 poison damage.","This spell''s damage increases by 1d12 when you reach 5th level (2d12), 11th level (3d12), and 17th level (4d12)."],"range":"10 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"damage":{"damage_type":{"index":"poison","name":"Poison","url":"/api/2014/damage-types/poison"},"damage_at_character_level":{"1":"1d12","5":"2d12","11":"3d12","17":"4d12"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"none"},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/poison-spray","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-polymorph', 'spell', 'Polymorph', 'spell-polymorph', '{"higher_level":[],"index":"polymorph","name":"Polymorph","desc":["This spell transforms a creature that you can see within range into a new form. An unwilling creature must make a wisdom saving throw to avoid the effect. A shapechanger automatically succeeds on this saving throw.","The transformation lasts for the duration, or until the target drops to 0 hit points or dies. The new form can be any beast whose challenge rating is equal to or less than the target''s (or the target''s level, if it doesn''t have a challenge rating). The target''s game statistics, including mental ability scores, are replaced by the statistics of the chosen beast. It retains its alignment and personality.","The target assumes the hit points of its new form. When it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn''t reduce the creature''s normal form to 0 hit points, it isn''t knocked unconscious.","The creature is limited in the actions it can perform by the nature of its new form, and it can''t speak, cast spells, or take any other action that requires hands or speech.","The target''s gear melds into the new form. The creature can''t activate, use, wield, or otherwise benefit from any of its equipment."],"range":"60 feet","components":["V","S","M"],"material":"A caterpillar cocoon.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":4,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/polymorph","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-power-word-kill', 'spell', 'Power Word Kill', 'spell-power-word-kill', '{"higher_level":[],"index":"power-word-kill","name":"Power Word Kill","desc":["You utter a word of power that can compel one creature you can see within range to die instantly. If the creature you choose has 100 hit points or fewer, it dies. Otherwise, the spell has no effect."],"range":"60 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":9,"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/power-word-kill","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-power-word-stun', 'spell', 'Power Word Stun', 'spell-power-word-stun', '{"higher_level":[],"index":"power-word-stun","name":"Power Word Stun","desc":["You speak a word of power that can overwhelm the mind of one creature you can see within range, leaving it dumbfounded. If the target has 150 hit points or fewer, it is stunned. Otherwise, the spell has no effect.","The stunned target must make a constitution saving throw at the end of each of its turns. On a successful save, this stunning effect ends."],"range":"60 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":8,"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/power-word-stun","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-prayer-of-healing', 'spell', 'Prayer of Healing', 'spell-prayer-of-healing', '{"index":"prayer-of-healing","name":"Prayer of Healing","desc":["Up to six creatures of your choice that you can see within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, the healing increases by 1d8 for each slot level above 2nd."],"range":"30 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"10 minutes","level":2,"heal_at_slot_level":{"2":"2d8 + MOD","3":"3d8 + MOD","4":"4d8 + MOD","5":"5d8 + MOD","6":"6d8 + MOD","7":"7d8 + MOD","8":"8d8 + MOD","9":"9d8 + MOD"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/prayer-of-healing","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-prestidigitation', 'spell', 'Prestidigitation', 'spell-prestidigitation', '{"higher_level":[],"index":"prestidigitation","name":"Prestidigitation","desc":["This spell is a minor magical trick that novice spellcasters use for practice. You create one of the following magical effects within ''range'':","You create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.","You instantaneously light or snuff out a candle, a torch, or a small campfire.","You instantaneously clean or soil an object no larger than 1 cubic foot.","You chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.","You make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.","You create a nonmagical trinket or an illusory image that can fit in your hand and that lasts until the end of your next turn.","If you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action."],"range":"10 feet","components":["V","S"],"ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":0,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/prestidigitation","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-prismatic-spray', 'spell', 'Prismatic Spray', 'spell-prismatic-spray', '{"higher_level":[],"index":"prismatic-spray","name":"Prismatic Spray","desc":["Eight multicolored rays of light flash from your hand. Each ray is a different color and has a different power and purpose. Each creature in a 60-foot cone must make a dexterity saving throw. For each target, roll a d8 to determine which color ray affects it.","***1. Red.*** The target takes 10d6 fire damage on a failed save, or half as much damage on a successful one.","***2. Orange.*** The target takes 10d6 acid damage on a failed save, or half as much damage on a successful one.","***3. Yellow.*** The target takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.","***4. Green.*** The target takes 10d6 poison damage on a failed save, or half as much damage on a successful one.","***5. Blue.*** The target takes 10d6 cold damage on a failed save, or half as much damage on a successful one.","***6. Indigo.*** On a failed save, the target is restrained. It must then make a constitution saving throw at the end of each of its turns. If it successfully saves three times, the spell ends. If it fails its save three times, it permanently turns to stone and is subjected to the petrified condition. The successes and failures don''t need to be consecutive; keep track of both until the target collects three of a kind.","***7. Violet.*** On a failed save, the target is blinded. It must then make a wisdom saving throw at the start of your next turn. A successful save ends the blindness. If it fails that save, the creature is transported to another plane of existence of the GM''s choosing and is no longer blinded. (Typically, a creature that is on a plane that isn''t its home plane is banished home, while other creatures are usually cast into the Astral or Ethereal planes.)","***8. Special.*** The target is struck by two rays. Roll twice more, rerolling any 8."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":7,"damage":{"damage_at_slot_level":{"7":"10d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"other","desc":"For each target, roll a d8 to determine which color ray affects it."},"area_of_effect":{"type":"cone","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/prismatic-spray","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-prismatic-wall', 'spell', 'Prismatic Wall', 'spell-prismatic-wall', '{"higher_level":[],"index":"prismatic-wall","name":"Prismatic Wall","desc":["A shimmering, multicolored plane of light forms a vertical opaque wall--up to 90 feet long, 30 feet high, and 1 inch thick--centered on a point you can see within range. Alternatively, you can shape the wall into a sphere up to 30 feet in diameter centered on a point you choose within range. The wall remains in place for the duration. If you position the wall so that it passes through a space occupied by a creature, the spell fails, and your action and the spell slot are wasted.","The wall sheds bright light out to a range of 100 feet and dim light for an additional 100 feet. You and creatures you designate at the time you cast the spell can pass through and remain near the wall without harm. If another creature that can see the wall moves to within 20 feet of it or starts its turn there, the creature must succeed on a constitution saving throw or become blinded for 1 minute.","The wall consists of seven layers, each with a different color. When a creature attempts to reach into or pass through the wall, it does so one layer at a time through all the wall''s layers. As it passes or reaches through each layer, the creature must make a dexterity saving throw or be affected by that layer''s properties as described below.","The wall can be destroyed, also one layer at a time, in order from red to violet, by means specific to each layer. Once a layer is destroyed, it remains so for the duration of the spell. A rod of cancellation destroys a prismatic wall, but an antimagic field has no effect on it.","***1. Red.*** The creature takes 10d6 fire damage on a failed save, or half as much damage on a successful one. While this layer is in place, nonmagical ranged attacks can''t pass through the wall. The layer can be destroyed by dealing at least 25 cold damage to it.","***2. Orange.*** The creature takes 10d6 acid damage on a failed save, or half as much damage on a successful one. While this layer is in place, magical ranged attacks can''t pass through the wall. The layer is destroyed by a strong wind.","***3. Yellow.*** The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one. This layer can be destroyed by dealing at least 60 force damage to it.","***4. Green.*** The creature takes 10d6 poison damage on a failed save, or half as much damage on a successful one. A passwall spell, or another spell of equal or greater level that can open a portal on a solid surface, destroys this layer.","***5. Blue.*** The creature takes 10d6 cold damage on a failed save, or half as much damage on a successful one. This layer can be destroyed by dealing at least 25 fire damage to it.","***6. Indigo.*** On a failed save, the creature is restrained. It must then make a constitution saving throw at the end of each of its turns. If it successfully saves three times, the spell ends. If it fails its save three times, it permanently turns to stone and is subjected to the petrified condition. The successes and failures don''t need to be consecutive; keep track of both until the creature collects three of a kind.","While this layer is in place, spells can''t be cast through the wall. The layer is destroyed by bright light shed by a daylight spell or a similar spell of equal or higher level.","***7. Violet.*** On a failed save, the creature is blinded. It must then make a wisdom saving throw at the start of your next turn. A successful save ends the blindness. If it fails that save, the creature is transported to another plane of the GM''s choosing and is no longer blinded. (Typically, a creature that is on a plane that isn''t its home plane is banished home, while other creatures are usually cast into the Astral or Ethereal planes.) This layer is destroyed by a dispel magic spell or a similar spell of equal or higher level that can end spells and magical effects."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"10 minutes","concentration":false,"casting_time":"1 action","level":9,"area_of_effect":{"type":"line","size":90},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/prismatic-wall","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-private-sanctum', 'spell', 'Private Sanctum', 'spell-private-sanctum', '{"index":"private-sanctum","name":"Private Sanctum","desc":["You make an area within range magically secure. The area is a cube that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration or until you use an action to dismiss it.","When you cast the spell, you decide what sort of security the spell provides, choosing any or all of the following properties:","- Sound can''t pass through the barrier at the edge of the warded area.","- The barrier of the warded area appears dark and foggy, preventing vision (including darkvision) through it.","- Sensors created by divination spells can''t appear inside the protected area or pass through the barrier at its perimeter.","- Creatures in the area can''t be targeted by divination spells.","- Nothing can teleport into or out of the warded area.","- Planar travel is blocked within the warded area.","Casting this spell on the same spot every day for a year makes this effect permanent."],"higher_level":["When you cast this spell using a spell slot of 5th level or higher, you can increase the size of the cube by 100 feet for each slot level beyond 4th. Thus you could protect a cube that can be up to 200 feet on one side by using a spell slot of 5th level."],"range":"120 feet","components":["V","S","M"],"material":"A thin sheet of lead, a piece of opaque glass, a wad of cotton or cloth, and powdered chrysolite.","ritual":false,"duration":"24 hours","concentration":false,"casting_time":"10 minutes","level":4,"area_of_effect":{"type":"cube","size":100},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/private-sanctum","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-produce-flame', 'spell', 'Produce Flame', 'spell-produce-flame', '{"higher_level":[],"index":"produce-flame","name":"Produce Flame","desc":["A flickering flame appears in your hand. The flame remains there for the duration and harms neither you nor your equipment. The flame sheds bright light in a 10-foot radius and dim light for an additional 10 feet. The spell ends if you dismiss it as an action or if you cast it again.","You can also attack with the flame, although doing so ends the spell. When you cast this spell, or as an action on a later turn, you can hurl the flame at a creature within 30 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 fire damage.","This spell''s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."],"range":"Self","components":["V","S"],"ritual":false,"duration":"10 minutes","concentration":false,"casting_time":"1 action","level":0,"attack_type":"ranged","damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_character_level":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/produce-flame","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-programmed-illusion', 'spell', 'Programmed Illusion', 'spell-programmed-illusion', '{"higher_level":[],"index":"programmed-illusion","name":"Programmed Illusion","desc":["You create an illusion of an object, a creature, or some other visible phenomenon within range that activates when a specific condition occurs. The illusion is imperceptible until then. It must be no larger than a 30-foot cube, and you decide when you cast the spell how the illusion behaves and what sounds it makes. This scripted performance can last up to 5 minutes.","When the condition you specify occurs, the illusion springs into existence and performs in the manner you described. Once the illusion finishes performing, it disappears and remains dormant for 10 minutes. After this time, the illusion can be activated again.","The triggering condition can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the area. For example, you could create an illusion of yourself to appear and warn off others who attempt to open a trapped door, or you could set the illusion to trigger only when a creature says the correct word or phrase.","Physical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature."],"range":"120 feet","components":["V","S","M"],"material":"A bit of fleece and jade dust worth at least 25 gp.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"1 action","level":6,"area_of_effect":{"type":"cube","size":30},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/programmed-illusion","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-project-image', 'spell', 'Project Image', 'spell-project-image', '{"higher_level":[],"index":"project-image","name":"Project Image","desc":["You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you but is intangible. If the illusion takes any damage, it disappears, and the spell ends.","You can use your action to move this illusion up to twice your speed, and make it gesture, speak, and behave in whatever way you choose. It mimics your mannerisms perfectly.","You can see through its eyes and hear through its ears as if you were in its space. On your turn as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings.","Physical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature."],"range":"500 miles","components":["V","S","M"],"material":"A small replica of you made from materials worth at least 5 gp.","ritual":false,"duration":"Up to 24 hours","concentration":true,"casting_time":"1 action","level":7,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/project-image","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-protection-from-energy', 'spell', 'Protection From Energy', 'spell-protection-from-energy', '{"higher_level":[],"index":"protection-from-energy","name":"Protection From Energy","desc":["For the duration, the willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":3,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/protection-from-energy","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-protection-from-evil-and-good', 'spell', 'Protection from Evil and Good', 'spell-protection-from-evil-and-good', '{"higher_level":[],"index":"protection-from-evil-and-good","name":"Protection from Evil and Good","desc":["Until the spell ends, one willing creature you touch is protected against certain types of creatures: aberrations, celestials, elementals, fey, fiends, and undead.","The protection grants several benefits. Creatures of those types have disadvantage on attack rolls against the target. The target also can''t be charmed, frightened, or possessed by them. If the target is already charmed, frightened, or possessed by such a creature, the target has advantage on any new saving throw against the relevant effect."],"range":"Touch","components":["V","S","M"],"material":"Holy water or powdered silver and iron, which the spell consumes.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":1,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"url":"/api/2014/spells/protection-from-evil-and-good","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-protection-from-poison', 'spell', 'Protection from Poison', 'spell-protection-from-poison', '{"higher_level":[],"index":"protection-from-poison","name":"Protection from Poison","desc":["You touch a creature. If it is poisoned, you neutralize the poison. If more than one poison afflicts the target, you neutralize one poison that you know is present, or you neutralize one at random.","For the duration, the target has advantage on saving throws against being poisoned, and it has resistance to poison damage."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/protection-from-poison","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-purify-food-and-drink', 'spell', 'Purify Food and Drink', 'spell-purify-food-and-drink', '{"higher_level":[],"index":"purify-food-and-drink","name":"Purify Food and Drink","desc":["All nonmagical food and drink within a 5-foot radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease."],"range":"10 feet","components":["V","S"],"ritual":true,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/purify-food-and-drink","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-raise-dead', 'spell', 'Raise Dead', 'spell-raise-dead', '{"higher_level":[],"index":"raise-dead","name":"Raise Dead","desc":["You return a dead creature you touch to life, provided that it has been dead no longer than 10 days. If the creature''s soul is both willing and at liberty to rejoin the body, the creature returns to life with 1 hit point.","This spell also neutralizes any poisons and cures nonmagical diseases that affected the creature at the time it died. This spell doesn''t, however, remove magical diseases, curses, or similar effects; if these aren''t first removed prior to casting the spell, they take effect when the creature returns to life. The spell can''t return an undead creature to life.","This spell closes all mortal wounds, but it doesn''t restore missing body parts. If the creature is lacking body parts or organs integral for its survival--its head, for instance--the spell automatically fails.","Coming back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears."],"range":"Touch","components":["V","S","M"],"material":"A diamond worth at least 500gp, which the spell consumes.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 hour","level":5,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"life","name":"Life","url":"/api/2014/subclasses/life"}],"url":"/api/2014/spells/raise-dead","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-ray-of-enfeeblement', 'spell', 'Ray of Enfeeblement', 'spell-ray-of-enfeeblement', '{"higher_level":[],"index":"ray-of-enfeeblement","name":"Ray of Enfeeblement","desc":["A black beam of enervating energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target deals only half damage with weapon attacks that use Strength until the spell ends.","At the end of each of the target''s turns, it can make a constitution saving throw against the spell. On a success, the spell ends."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":2,"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"none"},"attack_type":"ranged","school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/ray-of-enfeeblement","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-ray-of-frost', 'spell', 'Ray of Frost', 'spell-ray-of-frost', '{"higher_level":[],"index":"ray-of-frost","name":"Ray of Frost","desc":["A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn.","The spell''s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"attack_type":"ranged","damage":{"damage_type":{"index":"cold","name":"Cold","url":"/api/2014/damage-types/cold"},"damage_at_character_level":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/ray-of-frost","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-regenerate', 'spell', 'Regenerate', 'spell-regenerate', '{"higher_level":[],"index":"regenerate","name":"Regenerate","desc":["You touch a creature and stimulate its natural healing ability. The target regains 4d8 + 15 hit points. For the duration of the spell, the target regains 1 hit point at the start of each of its turns (10 hit points each minute).","The target''s severed body members (fingers, legs, tails, and so on), if any, are restored after 2 minutes. If you have the severed part and hold it to the stump, the spell instantaneously causes the limb to knit to the stump."],"range":"Touch","components":["V","S","M"],"material":"A prayer wheel and holy water.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 minute","level":7,"heal_at_slot_level":{"7":"4d8 + 15"},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/regenerate","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-reincarnate', 'spell', 'Reincarnate', 'spell-reincarnate', '{"higher_level":[],"index":"reincarnate","name":"Reincarnate","desc":["You touch a dead humanoid or a piece of a dead humanoid. Provided that the creature has been dead no longer than 10 days, the spell forms a new adult body for it and then calls the soul to enter that body. If the target''s soul isn''t free or willing to do so, the spell fails.","The magic fashions a new body for the creature to inhabit, which likely causes the creature''s race to change. The GM rolls a d 100 and consults the following table to determine what form the creature takes when restored to life, or the GM chooses a form.","| d100 | Race |","|---|---|","| 01-04 | Dragonborn |","| 05-13 | Dwarf, hill |","| 14-21 | Dwarf, mountain |","| 22-25 | Elf, dark |","| 26-34 | Elf, high |","| 35-42 | Elf, wood |","| 43-46 | Gnome, forest |","| 47-52 | Gnome, rock |","| 53-56 | Half-elf |","| 57-60 | Half-orc |","| 61-68 | Halfling, lightfoot |","| 69-76 | Halfling, stout |","| 77-96 | Human |","| 97-00 | Tiefling |","The reincarnated creature recalls its former life and experiences. It retains the capabilities it had in its original form, except it exchanges its original race for the new one and changes its racial traits accordingly."],"range":"Touch","components":["V","S","M"],"material":"Rare oils and unguents worth at least 1,000 gp, which the spell consumes.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 hour","level":5,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/reincarnate","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-remove-curse', 'spell', 'Remove Curse', 'spell-remove-curse', '{"higher_level":[],"index":"remove-curse","name":"Remove Curse","desc":["At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner''s attunement to the object so it can be removed or discarded."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/remove-curse","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-resilient-sphere', 'spell', 'Resilient Sphere', 'spell-resilient-sphere', '{"higher_level":[],"index":"resilient-sphere","name":"Resilient Sphere","desc":["A sphere of shimmering force encloses a creature or object of Large size or smaller within range. An unwilling creature must make a dexterity saving throw. On a failed save, the creature is enclosed for the duration.","Nothing--not physical objects, energy, or other spell effects--can pass through the barrier, in or out, though a creature in the sphere can breathe there. The sphere is immune to all damage, and a creature or object inside can''t be damaged by attacks or effects originating from outside, nor can a creature inside the sphere damage anything outside it.","The sphere is weightless and just large enough to contain the creature or object inside. An enclosed creature can use its action to push against the sphere''s walls and thus roll the sphere at up to half the creature''s speed. Similarly, the globe can be picked up and moved by other creatures.","A disintegrate spell targeting the globe destroys it without harming anything inside it."],"range":"30 feet","components":["V","S","M"],"material":"A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"none"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/resilient-sphere","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-resistance', 'spell', 'Resistance', 'spell-resistance', '{"higher_level":[],"index":"resistance","name":"Resistance","desc":["You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one saving throw of its choice. It can roll the die before or after making the saving throw. The spell then ends."],"range":"Touch","components":["V","S","M"],"material":"A miniature cloak.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":0,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/resistance","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-resurrection', 'spell', 'Resurrection', 'spell-resurrection', '{"higher_level":[],"index":"resurrection","name":"Resurrection","desc":["You touch a dead creature that has been dead for no more than a century, that didn''t die of old age, and that isn''t undead. If its soul is free and willing, the target returns to life with all its hit points.","This spell neutralizes any poisons and cures normal diseases afflicting the creature when it died. It doesn''t, however, remove magical diseases, curses, and the like; if such effects aren''t removed prior to casting the spell, they afflict the target on its return to life.","This spell closes all mortal wounds and restores any missing body parts.","Coming back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears.","Casting this spell to restore life to a creature that has been dead for one year or longer taxes you greatly. Until you finish a long rest, you can''t cast spells again, and you have disadvantage on all attack rolls, ability checks, and saving throws."],"range":"Touch","components":["V","S","M"],"material":"A diamond worth at least 1,000gp, which the spell consumes.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 hour","level":7,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/resurrection","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-reverse-gravity', 'spell', 'Reverse Gravity', 'spell-reverse-gravity', '{"higher_level":[],"index":"reverse-gravity","name":"Reverse Gravity","desc":["This spell reverses gravity in a 50-foot-radius, 100-foot high cylinder centered on a point within range. All creatures and objects that aren''t somehow anchored to the ground in the area fall upward and reach the top of the area when you cast this spell. A creature can make a dexterity saving throw to grab onto a fixed object it can reach, thus avoiding the fall.","If some solid object (such as a ceiling) is encountered in this fall, falling objects and creatures strike it just as they would during a normal downward fall. If an object or creature reaches the top of the area without striking anything, it remains there, oscillating slightly, for the duration.","At the end of the duration, affected objects and creatures fall back down."],"range":"100 feet","components":["V","S","M"],"material":"A lodestone and iron filings.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":7,"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"other","desc":"A creature can make a dexterity saving throw to grab onto a fixed object it can reach, thus avoiding the fall."},"area_of_effect":{"type":"cylinder","size":50},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/reverse-gravity","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-revivify', 'spell', 'Revivify', 'spell-revivify', '{"higher_level":[],"index":"revivify","name":"Revivify","desc":["You touch a creature that has died within the last minute. That creature returns to life with 1 hit point. This spell can''t return to life a creature that has died of old age, nor can it restore any missing body parts."],"range":"Touch","components":["V","S","M"],"material":"Diamonds worth 300gp, which the spell consumes.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"life","name":"Life","url":"/api/2014/subclasses/life"}],"url":"/api/2014/spells/revivify","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-rope-trick', 'spell', 'Rope Trick', 'spell-rope-trick', '{"higher_level":[],"index":"rope-trick","name":"Rope Trick","desc":["You touch a length of rope that is up to 60 feet long. One end of the rope then rises into the air until the whole rope hangs perpendicular to the ground. At the upper end of the rope, an invisible entrance opens to an extradimensional space that lasts until the spell ends.","The extradimensional space can be reached by climbing to the top of the rope. The space can hold as many as eight Medium or smaller creatures. The rope can be pulled into the space, making the rope disappear from view outside the space.","Attacks and spells can''t cross through the entrance into or out of the extradimensional space, but those inside can see out of it as if through a 3-foot-by-5-foot window centered on the rope.","Anything inside the extradimensional space drops out when the spell ends."],"range":"Touch","components":["V","S","M"],"material":"Powdered corn extract and a twisted loop of parchment.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/rope-trick","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-sacred-flame', 'spell', 'Sacred Flame', 'spell-sacred-flame', '{"higher_level":[],"index":"sacred-flame","name":"Sacred Flame","desc":["Flame-like radiance descends on a creature that you can see within range. The target must succeed on a dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw.","The spell''s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"damage":{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_at_character_level":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"none"},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/sacred-flame","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-sanctuary', 'spell', 'Sanctuary', 'spell-sanctuary', '{"higher_level":[],"index":"sanctuary","name":"Sanctuary","desc":["You ward a creature within range against attack. Until the spell ends, any creature who targets the warded creature with an attack or a harmful spell must first make a wisdom saving throw. On a failed save, the creature must choose a new target or lose the attack or spell. This spell doesn''t protect the warded creature from area effects, such as the explosion of a fireball.","If the warded creature makes an attack or casts a spell that affects an enemy creature, this spell ends."],"range":"30 feet","components":["V","S","M"],"material":"A small silver mirror.","ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 bonus action","level":1,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"url":"/api/2014/spells/sanctuary","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-scorching-ray', 'spell', 'Scorching Ray', 'spell-scorching-ray', '{"index":"scorching-ray","name":"Scorching Ray","desc":["You create three rays of fire and hurl them at targets within range. You can hurl them at one target or several.","Make a ranged spell attack for each ray. On a hit, the target takes 2d6 fire damage."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, you create one additional ray for each slot level above 2nd."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":2,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"2":"2d6"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/scorching-ray","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-scrying', 'spell', 'Scrying', 'spell-scrying', '{"higher_level":[],"index":"scrying","name":"Scrying","desc":["You can see and hear a particular creature you choose that is on the same plane of existence as you. The target must make a wisdom saving throw, which is modified by how well you know the target and the sort of physical connection you have to it. If a target knows you''re casting this spell, it can fail the saving throw voluntarily if it wants to be observed.","| Knowledge | Save Modifier |","|---|---|","| Secondhand (you have heard of the target) | +5 |","| Firsthand (you have met the target) | +0 |","| Familiar (you know the target well) | -5 |","","| Connection | Save Modifier |","|---|---|","| Likeness or picture | -2 |","| Possession or garment | -4 |","| Body part, lock of hair, bit of nail, or the like | -10 |","On a successful save, the target isn''t affected, and you can''t use this spell against it again for 24 hours.","On a failed save, the spell creates an invisible sensor within 10 feet of the target. You can see and hear through the sensor as if you were there. The sensor moves with the target, remaining within 10 feet of it for the duration. A creature that can see invisible objects sees the sensor as a luminous orb about the size of your fist.","Instead of targeting a creature, you can choose a location you have seen before as the target of this spell. When you do, the sensor appears at that location and doesn''t move."],"range":"Self","components":["V","S","M"],"material":"A focus worth at least 1,000 gp, such as a crystal ball, a silver mirror, or a font filled with holy water.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"10 minutes","level":5,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/scrying","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-secret-chest', 'spell', 'Secret Chest', 'spell-secret-chest', '{"higher_level":[],"index":"secret-chest","name":"Secret Chest","desc":["You hide a chest, and all its contents, on the Ethereal Plane. You must touch the chest and the miniature replica that serves as a material component for the spell. The chest can contain up to 12 cubic feet of nonliving material (3 feet by 2 feet by 2 feet).","While the chest remains on the Ethereal Plane, you can use an action and touch the replica to recall the chest. It appears in an unoccupied space on the ground within 5 feet of you. You can send the chest back to the Ethereal Plane by using an action and touching both the chest and the replica.","After 60 days, there is a cumulative 5 percent chance per day that the spell''s effect ends. This effect ends if you cast this spell again, if the smaller replica chest is destroyed, or if you choose to end the spell as an action. If the spell ends and the larger chest is on the Ethereal Plane, it is irretrievably lost."],"range":"Touch","components":["V","S","M"],"material":"An exquisite chest, 3 feet by 2 feet by 2 feet, constructed from rare materials worth at least 5,000 gp, and a Tiny replica made from the same materials worth at least 50 gp.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":4,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/secret-chest","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-see-invisibility', 'spell', 'See Invisibility', 'spell-see-invisibility', '{"higher_level":[],"index":"see-invisibility","name":"See Invisibility","desc":["For the duration of the spell, you see invisible creatures and objects as if they were visible, and you can see through Ethereal. The ethereal objects and creatures appear ghostly translucent."],"range":"Self","components":["V","S","M"],"material":"A dash of talc and a small amount of silver powder.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/see-invisibility","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-seeming', 'spell', 'Seeming', 'spell-seeming', '{"higher_level":[],"index":"seeming","name":"Seeming","desc":["This spell allows you to change the appearance of any number of creatures that you can see within range. You give each target you choose a new, illusory appearance. An unwilling target can make a charisma saving throw, and if it succeeds, it is unaffected by this spell.","The spell disguises physical appearance as well as clothing, armor, weapons, and equipment. You can make each creature seem 1 foot shorter or taller and appear thin, fat, or in between. You can''t change a target''s body type, so you must choose a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you. The spell lasts for the duration, unless you use your action to dismiss it sooner.","The changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to a creature''s outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel the creature''s head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.","A creature can use its action to inspect a target and make an Intelligence (Investigation) check against your spell save DC. If it succeeds, it becomes aware that the target is disguised."],"range":"30 feet","components":["V","S"],"ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 action","level":5,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/seeming","updated_at":"2026-04-01T20:35:39.217Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-sending', 'spell', 'Sending', 'spell-sending', '{"higher_level":[],"index":"sending","name":"Sending","desc":["You send a short message of twenty-five words or less to a creature with which you are familiar. The creature hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables creatures with Intelligence scores of at least 1 to understand the meaning of your message.","You can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn''t arrive."],"range":"Unlimited","components":["V","S","M"],"material":"A short piece of fine copper wire.","ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/sending","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-sequester', 'spell', 'Sequester', 'spell-sequester', '{"higher_level":[],"index":"sequester","name":"Sequester","desc":["By means of this spell, a willing creature or an object can be hidden away, safe from detection for the duration. When you cast the spell and touch the target, it becomes invisible and can''t be targeted by divination spells or perceived through scrying sensors created by divination spells.","If the target is a creature, it falls into a state of suspended animation. Time ceases to flow for it, and it doesn''t grow older.","You can set a condition for the spell to end early. The condition can be anything you choose, but it must occur or be visible within 1 mile of the target. Examples include \"after 1,000 years\" or \"when the tarrasque awakens.\" This spell also ends if the target takes any damage."],"range":"Touch","components":["V","S","M"],"material":"A powder composed of diamond, emerald, ruby, and sapphire dust worth at least 5,000 gp, which the spell consumes.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"1 action","level":7,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/sequester","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-shapechange', 'spell', 'Shapechange', 'spell-shapechange', '{"higher_level":[],"index":"shapechange","name":"Shapechange","desc":["You assume the form of a different creature for the duration. The new form can be of any creature with a challenge rating equal to your level or lower. The creature can''t be a construct or an undead, and you must have seen the sort of creature at least once. You transform into an average example of that creature, one without any class levels or the Spellcasting trait.","Your game statistics are replaced by the statistics of the chosen creature, though you retain your alignment and Intelligence, Wisdom, and Charisma scores. You also retain all of your skill and saving throw proficiencies, in addition to gaining those of the creature. If the creature has the same proficiency as you and the bonus listed in its statistics is higher than yours, use the creature''s bonus in place of yours. You can''t use any legendary actions or lair actions of the new form.","You assume the hit points and Hit Dice of the new form. When you revert to your normal form, you return to the number of hit points you had before you transformed. If you revert as a result of dropping to 0 hit points, any excess damage carries over to your normal form. As long as the excess damage doesn''t reduce your normal form to 0 hit points, you aren''t knocked unconscious.","You retain the benefit of any features from your class, race, or other source and can use them, provided that your new form is physically capable of doing so. You can''t use any special senses you have (for example, darkvision) unless your new form also has that sense. You can only speak if the creature can normally speak.","When you transform, you choose whether your equipment falls to the ground, merges into the new form, or is worn by it. Worn equipment functions as normal. The GM determines whether it is practical for the new form to wear a piece of equipment, based on the creature''s shape and size. Your equipment doesn''t change shape or size to match the new form, and any equipment that the new form can''t wear must either fall to the ground or merge into your new form. Equipment that merges has no effect in that state.","During this spell''s duration, you can use your action to assume a different form following the same restrictions and rules for the original form, with one exception: if your new form has more hit points than your current one, your hit points remain at their current value."],"range":"Self","components":["V","S","M"],"material":"A jade circlet worth at least 1,500 gp, which you must place on your head before you cast the spell.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":9,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/shapechange","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-shatter', 'spell', 'Shatter', 'spell-shatter', '{"index":"shatter","name":"Shatter","desc":["A sudden loud ringing noise, painfully intense, erupts from a point of your choice within range. Each creature in a 10-foot-radius sphere centered on that point must make a Constitution saving throw. A creature takes 3d8 thunder damage on a failed save, or half as much damage on a successful one. A creature made of inorganic material such as stone, crystal, or metal has disadvantage on this saving throw.","A non-magical item that is not worn or carried also suffers damage if it is in the area of the spell."],"higher_level":["When you cast this spell using a 3 or higher level spell slot, the damage of the spell increases by 1d8 for each level of higher spell slot 2."],"range":"60 feet","components":["V","S","M"],"material":"A burst of mica.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":2,"damage":{"damage_type":{"index":"thunder","name":"Thunder","url":"/api/2014/damage-types/thunder"},"damage_at_slot_level":{"2":"3d8","3":"4d8","4":"5d8","5":"6d8","6":"7d8","7":"8d8","8":"9d8","9":"10d8"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":10},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/shatter","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-shield', 'spell', 'Shield', 'spell-shield', '{"higher_level":[],"index":"shield","name":"Shield","desc":["An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from magic missile."],"range":"Self","components":["V","S"],"ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 reaction","level":1,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/shield","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-shield-of-faith', 'spell', 'Shield of Faith', 'spell-shield-of-faith', '{"higher_level":[],"index":"shield-of-faith","name":"Shield of Faith","desc":["A shimmering field appears and surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration."],"range":"60 feet","components":["V","S","M"],"material":"A small parchment with a bit of holy text written on it.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 bonus action","level":1,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/shield-of-faith","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-shillelagh', 'spell', 'Shillelagh', 'spell-shillelagh', '{"higher_level":[],"index":"shillelagh","name":"Shillelagh","desc":["The wood of a club or a quarterstaff you are holding is imbued with nature''s power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon''s damage die becomes a d8. The weapon also becomes magical, if it isn''t already. The spell ends if you cast it again or if you let go of the weapon."],"range":"Touch","components":["V","S","M"],"material":"Mistletoe, a shamrock leaf, and a club or quarterstaff.","ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 bonus action","level":0,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/shillelagh","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-shocking-grasp', 'spell', 'Shocking Grasp', 'spell-shocking-grasp', '{"higher_level":[],"index":"shocking-grasp","name":"Shocking Grasp","desc":["Lightning springs from your hand to deliver a shock to a creature you try to touch. Make a melee spell attack against the target. You have advantage on the attack roll if the target is wearing armor made of metal. On a hit, the target takes 1d8 lightning damage, and it can''t take reactions until the start of its next turn.","The spell''s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"attack_type":"melee","damage":{"damage_type":{"index":"lightning","name":"Lightning","url":"/api/2014/damage-types/lightning"},"damage_at_character_level":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/shocking-grasp","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-silence', 'spell', 'Silence', 'spell-silence', '{"higher_level":[],"index":"silence","name":"Silence","desc":["For the duration, no sound can be created within or pass through a 20-foot-radius sphere centered on a point you choose within range. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are deafened while entirely inside it.","Casting a spell that includes a verbal component is impossible there."],"range":"120 feet","components":["V","S"],"ritual":true,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":2,"area_of_effect":{"type":"sphere","size":20},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/silence","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-silent-image', 'spell', 'Silent Image', 'spell-silent-image', '{"higher_level":[],"index":"silent-image","name":"Silent Image","desc":["You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn''t accompanied by sound, smell, or other sensory effects.","You can use your action to cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking.","Physical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image."],"range":"60 feet","components":["V","S","M"],"material":"A bit of fleece.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":1,"area_of_effect":{"type":"cube","size":15},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/silent-image","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-simulacrum', 'spell', 'Simulacrum', 'spell-simulacrum', '{"higher_level":[],"index":"simulacrum","name":"Simulacrum","desc":["You shape an illusory duplicate of one beast or humanoid that is within range for the entire casting time of the spell. The duplicate is a creature, partially real and formed from ice or snow, and it can take actions and otherwise be affected as a normal creature. It appears to be the same as the original, but it has half the creature''s hit point maximum and is formed without any equipment. Otherwise, the illusion uses all the statistics of the creature it duplicates.","The simulacrum is friendly to you and creatures you designate. It obeys your spoken commands, moving and acting in accordance with your wishes and acting on your turn in combat. The simulacrum lacks the ability to learn or become more powerful, so it never increases its level or other abilities, nor can it regain expended spell slots.","If the simulacrum is damaged, you can repair it in an alchemical laboratory, using rare herbs and minerals worth 100 gp per hit point it regains. The simulacrum lasts until it drops to 0 hit points, at which point it reverts to snow and melts instantly.","If you cast this spell again, any currently active duplicates you created with this spell are instantly destroyed."],"range":"Touch","components":["V","S","M"],"material":"Snow or ice in quantities sufficient to made a life-size copy of the duplicated creature; some hair, fingernail clippings, or other piece of that creature''s body placed inside the snow or ice; and powdered ruby worth 1,500 gp, sprinkled over the duplicate and consumed by the spell.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"12 hours","level":7,"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/simulacrum","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-sleep', 'spell', 'Sleep', 'spell-sleep', '{"index":"sleep","name":"Sleep","desc":["This spell sends creatures into a magical slumber. Roll 5d8; the total is how many hit points of creatures this spell can affect. Creatures within 20 feet of a point you choose within range are affected in ascending order of their current hit points (ignoring unconscious creatures).","Starting with the creature that has the lowest current hit points, each creature affected by this spell falls unconscious until the spell ends, the sleeper takes damage, or someone uses an action to shake or slap the sleeper awake. Subtract each creature''s hit points from the total before moving on to the creature with the next lowest hit points. A creature''s hit points must be equal to or less than the remaining total for that creature to be affected.","Undead and creatures immune to being charmed aren''t affected by this spell."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d8 for each slot level above 1st."],"range":"90 feet","components":["V","S","M"],"material":"A pinch of fine sand, rose petals, or a cricket.","ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":1,"damage":{"damage_at_slot_level":{"1":"5d8"}},"area_of_effect":{"type":"sphere","size":20},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/sleep","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-sleet-storm', 'spell', 'Sleet Storm', 'spell-sleet-storm', '{"higher_level":[],"index":"sleet-storm","name":"Sleet Storm","desc":["Until the spell ends, freezing rain and sleet fall in a 20-foot-tall cylinder with a 40-foot radius centered on a point you choose within range. The area is heavily obscured, and exposed flames in the area are doused.","The ground in the area is covered with slick ice, making it difficult terrain. When a creature enters the spell''s area for the first time on a turn or starts its turn there, it must make a dexterity saving throw. On a failed save, it falls prone.","If a creature is concentrating in the spell''s area, the creature must make a successful constitution saving throw against your spell save DC or lose concentration."],"range":"150 feet","components":["V","S","M"],"material":"A pinch of dust and a few drops of water.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"area_of_effect":{"type":"cylinder","size":40},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/sleet-storm","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-slow', 'spell', 'Slow', 'spell-slow', '{"higher_level":[],"index":"slow","name":"Slow","desc":["You alter time around up to six creatures of your choice in a 40-foot cube within range. Each target must succeed on a wisdom saving throw or be affected by this spell for the duration.","An affected target''s speed is halved, it takes a -2 penalty to AC and dexterity saving throws, and it can''t use reactions. On its turn, it can use either an action or a bonus action, not both. Regardless of the creature''s abilities or magic items, it can''t make more than one melee or ranged attack during its turn.","If the creature attempts to cast a spell with a casting time of 1 action, roll a d20. On an 11 or higher, the spell doesn''t take effect until the creature''s next turn, and the creature must use its action on that turn to complete the spell. If it can''t, the spell is wasted.","A creature affected by this spell makes another wisdom saving throw at the end of its turn. On a successful save, the effect ends for it."],"range":"120 feet","components":["V","S","M"],"material":"A drop of molasses.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none","desc":"On failed save, the creature is slowed."},"area_of_effect":{"type":"cube","size":40},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/slow","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-spare-the-dying', 'spell', 'Spare the Dying', 'spell-spare-the-dying', '{"higher_level":[],"index":"spare-the-dying","name":"Spare the Dying","desc":["You touch a living creature that has 0 hit points. The creature becomes stable. This spell has no effect on undead or constructs."],"range":"Touch","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/spare-the-dying","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-speak-with-animals', 'spell', 'Speak with Animals', 'spell-speak-with-animals', '{"higher_level":[],"index":"speak-with-animals","name":"Speak with Animals","desc":["You gain the ability to comprehend and verbally communicate with beasts for the duration. The knowledge and awareness of many beasts is limited by their intelligence, but at a minimum, beasts can give you information about nearby locations and monsters, including whatever they can perceive or have perceived within the past day. You might be able to persuade a beast to perform a small favor for you, at the GM''s discretion."],"range":"Self","components":["V","S"],"ritual":true,"duration":"10 minutes","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/speak-with-animals","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-speak-with-dead', 'spell', 'Speak with Dead', 'spell-speak-with-dead', '{"higher_level":[],"index":"speak-with-dead","name":"Speak with Dead","desc":["You grant the semblance of life and intelligence to a corpse of your choice within range, allowing it to answer the questions you pose. The corpse must still have a mouth and can''t be undead. The spell fails if the corpse was the target of this spell within the last 10 days.","Until the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are hostile to it or it recognizes you as an enemy. This spell doesn''t return the creature''s soul to its body, only its animating spirit. Thus, the corpse can''t learn new information, doesn''t comprehend anything that has happened since it died, and can''t speculate about future events."],"range":"10 feet","components":["V","S","M"],"material":"Burning incense.","ritual":false,"duration":"10 minutes","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/speak-with-dead","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-speak-with-plants', 'spell', 'Speak with Plants', 'spell-speak-with-plants', '{"higher_level":[],"index":"speak-with-plants","name":"Speak with Plants","desc":["You imbue plants within 30 feet of you with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell''s area within the past day, gaining information about creatures that have passed, weather, and other circumstances.","You can also turn difficult terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into difficult terrain that lasts for the duration, causing vines and branches to hinder pursuers, for example.","Plants might be able to perform other tasks on your behalf, at the GM''s discretion. The spell doesn''t enable plants to uproot themselves and move about, but they can freely move branches, tendrils, and stalks.","If a plant creature is in the area, you can communicate with it as if you shared a common language, but you gain no magical ability to influence it.","This spell can cause the plants created by the entangle spell to release a restrained creature."],"range":"Self","components":["V","S"],"ritual":false,"duration":"10 minutes","concentration":false,"casting_time":"1 action","level":3,"area_of_effect":{"type":"sphere","size":30},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/speak-with-plants","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-spider-climb', 'spell', 'Spider Climb', 'spell-spider-climb', '{"higher_level":[],"index":"spider-climb","name":"Spider Climb","desc":["Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings, while leaving its hands free. The target also gains a climbing speed equal to its walking speed."],"range":"Touch","components":["V","S","M"],"material":"A drop of bitumen and a spider.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":2,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/spider-climb","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-spike-growth', 'spell', 'Spike Growth', 'spell-spike-growth', '{"higher_level":[],"index":"spike-growth","name":"Spike Growth","desc":["The ground in a 20-foot radius centered on a point within range twists and sprouts hard spikes and thorns. The area becomes difficult terrain for the duration. When a creature moves into or within the area, it takes 2d4 piercing damage for every 5 feet it travels.","The transformation of the ground is camouflaged to look natural. Any creature that can''t see the area at the time the spell is cast can make a Wisdom (Perception) check against your spell save DC to recognize the terrain as hazardous before entering it."],"range":"150 feet","components":["V","S","M"],"material":"Seven sharp thorns or seven small twigs, each sharpened to a point.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":2,"area_of_effect":{"type":"cylinder","size":20},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/spike-growth","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-spirit-guardians', 'spell', 'Spirit Guardians', 'spell-spirit-guardians', '{"index":"spirit-guardians","name":"Spirit Guardians","desc":["You call forth spirits to protect you. They flit around you to a distance of 15 feet for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.","When you cast this spell, you can designate any number of creatures you can see to be unaffected by it. An affected creature''s speed is halved in the area, and when the creature enters the area for the first time on a turn or starts its turn there, it must make a wisdom saving throw. On a failed save, the creature takes 3d8 radiant damage (if you are good or neutral) or 3d8 necrotic damage (if you are evil). On a successful save, the creature takes half as much damage."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd."],"range":"Self","components":["V","S","M"],"material":"A holy symbol.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":3,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/spirit-guardians","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-spiritual-weapon', 'spell', 'Spiritual Weapon', 'spell-spiritual-weapon', '{"index":"spiritual-weapon","name":"Spiritual Weapon","desc":["You create a floating, spectral weapon within range that lasts for the duration or until you cast this spell again. When you cast the spell, you can make a melee spell attack against a creature within 5 feet of the weapon. On a hit, the target takes force damage equal to 1d8 + your spellcasting ability modifier.","As a bonus action on your turn, you can move the weapon up to 20 feet and repeat the attack against a creature within 5 feet of it.","The weapon can take whatever form you choose. Clerics of deities who are associated with a particular weapon (as St. Cuthbert is known for his mace and Thor for his hammer) make this spell''s effect resemble that weapon."],"higher_level":["When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for every two slot levels above the 2nd."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 bonus action","level":2,"attack_type":"melee","damage":{"damage_type":{"index":"force","name":"Force","url":"/api/2014/damage-types/force"},"damage_at_slot_level":{"2":"1d8 + MOD","3":"1d8 + MOD","4":"2d8 + MOD","5":"2d8 + MOD","6":"3d8 + MOD","7":"3d8 + MOD","8":"4d8 + MOD","9":"4d8 + MOD"}},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"life","name":"Life","url":"/api/2014/subclasses/life"}],"url":"/api/2014/spells/spiritual-weapon","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-stinking-cloud', 'spell', 'Stinking Cloud', 'spell-stinking-cloud', '{"higher_level":[],"index":"stinking-cloud","name":"Stinking Cloud","desc":["You create a 20-foot-radius sphere of yellow, nauseating gas centered on a point within range. The cloud spreads around corners, and its area is heavily obscured. The cloud lingers in the air for the duration.","Each creature that is completely within the cloud at the start of its turn must make a constitution saving throw against poison. On a failed save, the creature spends its action that turn retching and reeling. Creatures that don''t need to breathe or are immune to poison automatically succeed on this saving throw.","A moderate wind (at least 10 miles per hour) disperses the cloud after 4 rounds. A strong wind (at least 20 miles per hour) disperses it after 1 round."],"range":"90 feet","components":["V","S","M"],"material":"A rotten egg or several skunk cabbage leaves.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"none","desc":"On a failed save, the creature spends its action that turn retching and reeling."},"area_of_effect":{"type":"sphere","size":20},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"},{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/stinking-cloud","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-stone-shape', 'spell', 'Stone Shape', 'spell-stone-shape', '{"higher_level":[],"index":"stone-shape","name":"Stone Shape","desc":["You touch a stone object of Medium size or smaller or a section of stone no more than 5 feet in any dimension and form it into any shape that suits your purpose. So, for example, you could shape a large rock into a weapon, idol, or coffer, or make a small passage through a wall, as long as the wall is less than 5 feet thick. You could also shape a stone door or its frame to seal the door shut. The object you create can have up to two hinges and a latch, but finer mechanical detail isn''t possible."],"range":"Touch","components":["V","S","M"],"material":"Soft clay, to be crudely worked into the desired shape for the stone object.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":4,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/stone-shape","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-stoneskin', 'spell', 'Stoneskin', 'spell-stoneskin', '{"higher_level":[],"index":"stoneskin","name":"Stoneskin","desc":["This spell turns the flesh of a willing creature you touch as hard as stone. Until the spell ends, the target has resistance to nonmagical bludgeoning, piercing, and slashing damage."],"range":"Touch","components":["V","S","M"],"material":"Diamond dust worth 100 gp, which the spell consumes.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":4,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/stoneskin","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-storm-of-vengeance', 'spell', 'Storm of Vengeance', 'spell-storm-of-vengeance', '{"higher_level":[],"index":"storm-of-vengeance","name":"Storm of Vengeance","desc":["A churning storm cloud forms, centered on a point you can see and spreading to a radius of 360 feet. Lightning flashes in the area, thunder booms, and strong winds roar. Each creature under the cloud (no more than 5,000 feet beneath the cloud) when it appears must make a constitution saving throw. On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 5 minutes.","Each round you maintain concentration on this spell, the storm produces additional effects on your turn.","***Round 2.*** Acidic rain falls from the cloud. Each creature and object under the cloud takes 1d6 acid damage.","***Round 3.*** You call six bolts of lightning from the cloud to strike six creatures or objects of your choice beneath the cloud. A given creature or object can''t be struck by more than one bolt. A struck creature must make a dexterity saving throw. The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.","***Round 4.*** Hailstones rain down from the cloud. Each creature under the cloud takes 2d6 bludgeoning damage.","***Round 5-10.*** Gusts and freezing rain assail the area under the cloud. The area becomes difficult terrain and is heavily obscured. Each creature there takes 1d6 cold damage. Ranged weapon attacks in the area are impossible. The wind and rain count as a severe distraction for the purposes of maintaining concentration on spells. Finally, gusts of strong wind (ranging from 20 to 50 miles per hour) automatically disperse fog, mists, and similar phenomena in the area, whether mundane or magical."],"range":"Sight","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":9,"damage":{"damage_type":{"index":"thunder","name":"Thunder","url":"/api/2014/damage-types/thunder"},"damage_at_slot_level":{"9":"2d6"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"none","desc":"On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 5 minutes."},"area_of_effect":{"type":"sphere","size":360},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/storm-of-vengeance","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-suggestion', 'spell', 'Suggestion', 'spell-suggestion', '{"higher_level":[],"index":"suggestion","name":"Suggestion","desc":["You suggest a course of activity (limited to a sentence or two) and magically influence a creature you can see within range that can hear and understand you. Creatures that can''t be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act ends the spell.","The target must make a wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.","You can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a knight give her warhorse to the first beggar she meets. If the condition isn''t met before the spell expires, the activity isn''t performed.","If you or any of your companions damage the target, the spell ends."],"range":"30 feet","components":["V","M"],"material":"A snake''s tongue and either a bit of honeycomb or a drop of sweet oil.","ritual":false,"duration":"Up to 8 hours","concentration":true,"casting_time":"1 action","level":2,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/suggestion","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-sunbeam', 'spell', 'Sunbeam', 'spell-sunbeam', '{"higher_level":[],"index":"sunbeam","name":"Sunbeam","desc":["A beam of brilliant light flashes out from your hand in a 5-foot-wide, 60-foot-long line. Each creature in the line must make a constitution saving throw. On a failed save, a creature takes 6d8 radiant damage and is blinded until your next turn. On a successful save, it takes half as much damage and isn''t blinded by this spell. Undead and oozes have disadvantage on this saving throw.","You can create a new line of radiance as your action on any turn until the spell ends.","For the duration, a mote of brilliant radiance shines in your hand. It sheds bright light in a 30-foot radius and dim light for an additional 30 feet. This light is sunlight."],"range":"Self","components":["V","S","M"],"material":"A magnifying glass.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_at_slot_level":{"6":"6d8"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half","desc":"On a failed save, the creature is blinded until your next turn. On a successful save, it isn''t blinded by this spell."},"area_of_effect":{"type":"line","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/sunbeam","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-sunburst', 'spell', 'Sunburst', 'spell-sunburst', '{"higher_level":[],"index":"sunburst","name":"Sunburst","desc":["Brilliant sunlight flashes in a 60-foot radius centered on a point you choose within range. Each creature in that light must make a constitution saving throw. On a failed save, a creature takes 12d6 radiant damage and is blinded for 1 minute. On a successful save, it takes half as much damage and isn''t blinded by this spell. Undead and oozes have disadvantage on this saving throw.","A creature blinded by this spell makes another constitution saving throw at the end of each of its turns. On a successful save, it is no longer blinded.","This spell dispels any darkness in its area that was created by a spell."],"range":"150 feet","components":["V","S","M"],"material":"Fire and a piece of sunstone.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":8,"damage":{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_at_slot_level":{"8":"12d6"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half","desc":"On failure, the creature is also blinded for 1 minute."},"area_of_effect":{"type":"cylinder","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/sunburst","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-symbol', 'spell', 'Symbol', 'spell-symbol', '{"higher_level":[],"index":"symbol","name":"Symbol","desc":["When you cast this spell, you inscribe a harmful glyph either on a surface (such as a section of floor, a wall, or a table) or within an object that can be closed to conceal the glyph (such as a book, a scroll, or a treasure chest). If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.","The glyph is nearly invisible, requiring an Intelligence (Investigation) check against your spell save DC to find it.","You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or stepping on the glyph, removing another object covering it, approaching within a certain distance of it, or manipulating the object that holds it. For glyphs inscribed within an object, the most common triggers are opening the object, approaching within a certain distance of it, or seeing or reading the glyph.","You can further refine the trigger so the spell is activated only under certain circumstances or according to a creature''s physical characteristics (such as height or weight), or physical kind (for example, the ward could be set to affect hags or shapechangers). You can also specify creatures that don''t trigger the glyph, such as those who say a certain password.","When you inscribe the glyph, choose one of the options below for its effect. Once triggered, the glyph glows, filling a 60-foot-radius sphere with dim light for 10 minutes, after which time the spell ends. Each creature in the sphere when the glyph activates is targeted by its effect, as is a creature that enters the sphere for the first time on a turn or ends its turn there.","***Death.*** Each target must make a constitution saving throw, taking 10d 10 necrotic damage on a failed save, or half as much damage on a successful save.","***Discord.*** Each target must make a constitution saving throw. On a failed save, a target bickers and argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has disadvantage on attack rolls and ability checks.","***Fear.*** Each target must make a wisdom saving throw and becomes frightened for 1 minute on a failed save. While frightened, the target drops whatever it is holding and must move at least 30 feet away from the glyph on each of its turns, if able.","***Hopelessness.*** Each target must make a charisma saving throw. On a failed save, the target is overwhelmed with despair for 1 minute. During this time, it can''t attack or target any creature with harmful abilities, spells, or other magical effects.","***Insanity.*** Each target must make an intelligence saving throw. On a failed save, the target is driven insane for 1 minute. An insane creature can''t take actions, can''t understand what other creatures say, can''t read, and speaks only in gibberish. The GM controls its movement, which is erratic.","***Pain.*** Each target must make a constitution saving throw and becomes incapacitated with excruciating pain for 1 minute on a failed save.","***Sleep.*** Each target must make a wisdom saving throw and falls unconscious for 10 minutes on a failed save. A creature awakens if it takes damage or if someone uses an action to shake or slap it awake.","***Stunning.*** Each target must make a wisdom saving throw and becomes stunned for 1 minute on a failed save."],"range":"Touch","components":["V","S","M"],"material":"Mercury, phosphorus, and powdered diamond and opal with a total value of at least 1,000 gp, which the spell consumes.","ritual":false,"duration":"Until dispelled","concentration":false,"casting_time":"1 minute","level":7,"area_of_effect":{"type":"cube","size":10},"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/symbol","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-telekinesis', 'spell', 'Telekinesis', 'spell-telekinesis', '{"higher_level":[],"index":"telekinesis","name":"Telekinesis","desc":["You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell, and as your action each round for the duration, you can exert your will on one creature or object that you can see within range, causing the appropriate effect below. You can affect the same target round after round, or choose a new one at any time. If you switch targets, the prior target is no longer affected by the spell.","***Creature.*** You can try to move a Huge or smaller creature. Make an ability check with your spellcasting ability contested by the creature''s Strength check. If you win the contest, you move the creature up to 30 feet in any direction, including upward but not beyond the range of this spell. Until the end of your next turn, the creature is restrained in your telekinetic grip. A creature lifted upward is suspended in mid-air.","On subsequent rounds, you can use your action to attempt to maintain your telekinetic grip on the creature by repeating the contest.","***Object.*** You can try to move an object that weighs up to 1,000 pounds. If the object isn''t being worn or carried, you automatically move it up to 30 feet in any direction, but not beyond the range of this spell.","If the object is worn or carried by a creature, you must make an ability check with your spellcasting ability contested by that creature''s Strength check. If you succeed, you pull the object away from that creature and can move it up to 30 feet in any direction but not beyond the range of this spell.","You can exert fine control on objects with your telekinetic grip, such as manipulating a simple tool, opening a door or a container, stowing or retrieving an item from an open container, or pouring the contents from a vial."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":5,"area_of_effect":{"type":"sphere","size":30},"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/telekinesis","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-telepathic-bond', 'spell', 'Telepathic Bond', 'spell-telepathic-bond', '{"higher_level":[],"index":"telepathic-bond","name":"Telepathic Bond","desc":["You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures with Intelligence scores of 2 or less aren''t affected by this spell.","Until the spell ends, the targets can communicate telepathically through the bond whether or not they have a common language. The communication is possible over any distance, though it can''t extend to other planes of existence."],"range":"30 feet","components":["V","S","M"],"material":"Pieces of eggshell from two different kinds of creatures","ritual":true,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":5,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/telepathic-bond","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-teleport', 'spell', 'Teleport', 'spell-teleport', '{"higher_level":[],"index":"teleport","name":"Teleport","desc":["This spell instantly transports you and up to eight willing creatures of your choice that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be able to fit entirely inside a 10-foot cube, and it can''t be held or carried by an unwilling creature.","The destination you choose must be known to you, and it must be on the same plane of existence as you. Your familiarity with the destination determines whether you arrive there successfully. The GM rolls d100 and consults the table.","| Familiarity | Mishap | Similar Area | Off Target | On Target |","|---|---|---|---|---|","| Permanent circle | -- | -- | -- | 01-100 |","| Associated object | -- | -- | -- | 01-100 |","| Very familiar | 01-05 | 06-13 | 14-24 | 25-100 |","| Seen casually | 01-33 | 34-43 | 44-53 | 54-100 |","| Viewed once | 01-43 | 44-53 | 54-73 | 74-100 |","| Description | 01-43 | 44-53 | 54-73 | 74-100 |","| False destination | 01-50 | 51-100 | -- | -- |","***Familiarity.*** \"Permanent circle\" means a permanent teleportation circle whose sigil sequence you know.","\"Associated object\" means that you possess an object taken from the desired destination within the last six months, such as a book from a wizard''s library, bed linen from a royal suite, or a chunk of marble from a lich''s secret tomb.","\"Very familiar\" is a place you have been very often, a place you have carefully studied, or a place you can see when you cast the spell.","\"Seen casually\" is someplace you have seen more than once but with which you aren''t very familiar.","\"Viewed once\" is a place you have seen once, possibly using magic.","\"Description\" is a place whose location and appearance you know through someone else''s description, perhaps from a map.","\"False destination\" is a place that doesn''t exist. Perhaps you tried to scry an enemy''s sanctum but instead viewed an illusion, or you are attempting to teleport to a familiar location that no longer exists.","***On Target.*** You and your group (or the target object) appear where you want to.","***Off Target.*** You and your group (or the target object) appear a random distance away from the destination in a random direction. Distance off target is 1d10 x 1d10 percent of the distance that was to be traveled. For example, if you tried to travel 120 miles, landed off target, and rolled a 5 and 3 on the two d10s, then you would be off target by 15 percent, or 18 miles. The GM determines the direction off target randomly by rolling a d8 and designating 1 as north, 2 as northeast, 3 as east, and so on around the points of the compass.  If you were teleporting to a coastal city and wound up 18 miles out at sea, you could be in trouble.","***Similar Area.*** You and your group (or the target object) wind up in a different area that''s visually or thematically similar to the target area. If you are heading for your home laboratory, for example, you might wind up in another wizard''s laboratory or in an alchemical supply shop that has many of the same tools and implements as your laboratory. Generally, you appear in the closest similar place, but since the spell has no range limit, you could conceivably wind up anywhere on the plane.","***Mishap.*** The spell''s unpredictable magic results in a difficult journey. Each teleporting creature (or the target object) takes 3d10 force damage, and the GM rerolls on the table to see where you wind up (multiple mishaps can occur, dealing damage each time)."],"range":"10 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":7,"area_of_effect":{"type":"cube","size":10},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/teleport","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-teleportation-circle', 'spell', 'Teleportation Circle', 'spell-teleportation-circle', '{"higher_level":[],"index":"teleportation-circle","name":"Teleportation Circle","desc":["As you cast the spell, you draw a 10-foot-diameter circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn. Any creature that enters the portal instantly appears within 5 feet of the destination circle or in the nearest unoccupied space if that space is occupied.","Many major temples, guilds, and other important places have permanent teleportation circles inscribed somewhere within their confines. Each such circle includes a unique sigil sequence--a string of magical runes arranged in a particular pattern. When you first gain the ability to cast this spell, you learn the sigil sequences for two destinations on the Material Plane, determined by the GM. You can learn additional sigil sequences during your adventures. You can commit a new sigil sequence to memory after studying it for 1 minute.","You can create a permanent teleportation circle by casting this spell in the same location every day for one year. You need not use the circle to teleport when you cast the spell in this way."],"range":"10 feet","components":["V","M"],"material":"Rare chalks and inks infused with precious gems with 50 gp, which the spell consumes.","ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 minute","level":5,"area_of_effect":{"type":"sphere","size":10},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/teleportation-circle","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-thaumaturgy', 'spell', 'Thaumaturgy', 'spell-thaumaturgy', '{"higher_level":[],"index":"thaumaturgy","name":"Thaumaturgy","desc":["You manifest a minor wonder, a sign of supernatural power, within range. You create one of the following magical effects within range.","- Your voice booms up to three times as loud as normal for 1 minute.","- You cause flames to flicker, brighten, dim, or change color for 1 minute.","- You cause harmless tremors in the ground for 1 minute.","- You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.","- You instantaneously cause an unlocked door or window to fly open or slam shut.","- You alter the appearance of your eyes for 1 minute.","If you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time, and you can dismiss such an effect as an action."],"range":"30 feet","components":["V"],"ritual":false,"duration":"1 minute","concentration":false,"casting_time":"1 action","level":0,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/thaumaturgy","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-thunderwave', 'spell', 'Thunderwave', 'spell-thunderwave', '{"index":"thunderwave","name":"Thunderwave","desc":["A wave of thunderous force sweeps out from you. Each creature in a 15-foot cube originating from you must make a constitution saving throw. On a failed save, a creature takes 2d8 thunder damage and is pushed 10 feet away from you. On a successful save, the creature takes half as much damage and isn''t pushed.","In addition, unsecured objects that are completely within the area of effect are automatically pushed 10 feet away from you by the spell''s effect, and the spell emits a thunderous boom audible out to 300 feet."],"higher_level":["When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":1,"damage":{"damage_type":{"index":"thunder","name":"Thunder","url":"/api/2014/damage-types/thunder"},"damage_at_slot_level":{"1":"2d8","2":"3d8","3":"4d8","4":"5d8","5":"6d8","6":"7d8","7":"8d8","8":"9d8","9":"10d8"}},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_success":"half"},"area_of_effect":{"type":"cube","size":15},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/thunderwave","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-time-stop', 'spell', 'Time Stop', 'spell-time-stop', '{"higher_level":[],"index":"time-stop","name":"Time Stop","desc":["You briefly stop the flow of time for everyone but yourself. No time passes for other creatures, while you take 1d4 + 1 turns in a row, during which you can use actions and move as normal.","This spell ends if one of the actions you use during this period, or any effects that you create during this period, affects a creature other than you or an object being worn or carried by someone other than you. In addition, the spell ends if you move to a place more than 1,000 feet from the location where you cast it."],"range":"Self","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":9,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/time-stop","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-tiny-hut', 'spell', 'Tiny Hut', 'spell-tiny-hut', '{"higher_level":[],"index":"tiny-hut","name":"Tiny Hut","desc":["A 10-foot-radius immobile dome of force springs into existence around and above you and remains stationary for the duration. The spell ends if you leave its area.","Nine creatures of Medium size or smaller can fit inside the dome with you. The spell fails if its area includes a larger creature or more than nine creatures. Creatures and objects within the dome when you cast this spell can move through it freely. All other creatures and objects are barred from passing through it. Spells and other magical effects can''t extend through the dome or be cast through it. The atmosphere inside the space is comfortable and dry, regardless of the weather outside.","Until the spell ends, you can command the interior to become dimly lit or dark. The dome is opaque from the outside, of any color you choose, but it is transparent from the inside."],"range":"Self","components":["V","S","M"],"material":"A small crystal bead.","ritual":true,"duration":"8 hours","concentration":false,"casting_time":"1 minute","level":3,"area_of_effect":{"type":"sphere","size":10},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/tiny-hut","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-tongues', 'spell', 'Tongues', 'spell-tongues', '{"higher_level":[],"index":"tongues","name":"Tongues","desc":["This spell grants the creature you touch the ability to understand any spoken language it hears. Moreover, when the target speaks, any creature that knows at least one language and can hear the target understands what it says."],"range":"Touch","components":["V","M"],"material":"A small clay model of a ziggurat.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/tongues","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-transport-via-plants', 'spell', 'Transport via Plants', 'spell-transport-via-plants', '{"higher_level":[],"index":"transport-via-plants","name":"Transport via Plants","desc":["This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement."],"range":"10 feet","components":["V","S"],"ritual":false,"duration":"1 round","concentration":false,"casting_time":"1 action","level":6,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/transport-via-plants","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-tree-stride', 'spell', 'Tree Stride', 'spell-tree-stride', '{"higher_level":[],"index":"tree-stride","name":"Tree Stride","desc":["You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You must use 5 feet of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 feet and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you''re in. You appear in a spot of your choice within 5 feet of the destination tree, using another 5 feet of movement. If you have no movement left, you appear within 5 feet of the tree you entered.","You can use this transportation ability once per round for the duration. You must end each turn outside a tree."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":5,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/tree-stride","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-true-polymorph', 'spell', 'True Polymorph', 'spell-true-polymorph', '{"higher_level":[],"index":"true-polymorph","name":"True Polymorph","desc":["Choose one creature or nonmagical object that you can see within range. You transform the creature into a different creature, the creature into an object, or the object into a creature (the object must be neither worn nor carried by another creature). The transformation lasts for the duration, or until the target drops to 0 hit points or dies. If you concentrate on this spell for the full duration, the transformation becomes permanent.","Shapechangers aren''t affected by this spell. An unwilling creature can make a wisdom saving throw, and if it succeeds, it isn''t affected by this spell.","***Creature into Creature.*** If you turn a creature into another kind of creature, the new form can be any kind you choose whose challenge rating is equal to or less than the target''s (or its level, if the target doesn''t have a challenge rating). The target''s game statistics, including mental ability scores, are replaced by the statistics of the new form. It retains its alignment and personality.","The target assumes the hit points of its new form, and when it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn''t reduce the creature''s normal form to 0 hit points, it isn''t knocked unconscious.","The creature is limited in the actions it can perform by the nature of its new form, and it can''t speak, cast spells, or take any other action that requires hands or speech unless its new form is capable of such actions.","The target''s gear melds into the new form. The creature can''t activate, use, wield, or otherwise benefit from any of its equipment.","***Object into Creature.*** You can turn an object into any kind of creature, as long as the creature''s size is no larger than the object''s size and the creature''s challenge rating is 9 or lower. The creature is friendly to you and your companions. It acts on each of your turns. You decide what action it takes and how it moves. The GM has the creature''s statistics and resolves all of its actions and movement.","If the spell becomes permanent, you no longer control the creature. It might remain friendly to you, depending on how you have treated it.","***Creature into Object.*** If you turn a creature into an object, it transforms along with whatever it is wearing and carrying into that form. The creature''s statistics become those of the object, and the creature has no memory of time spent in this form, after the spell ends and it returns to its normal form."],"range":"30 feet","components":["V","S","M"],"material":"A drop of mercury, a dollop of gum arabic, and a wisp of smoke.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":9,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/true-polymorph","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-true-resurrection', 'spell', 'True Resurrection', 'spell-true-resurrection', '{"higher_level":[],"index":"true-resurrection","name":"True Resurrection","desc":["You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. If the creature''s soul is free and willing, the creature is restored to life with all its hit points.","This spell closes all wounds, neutralizes any poison, cures all diseases, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs.","The spell can even provide a new body if the original no longer exists, in which case you must speak the creature''s name. The creature then appears in an unoccupied space you choose within 10 feet of you."],"range":"Touch","components":["V","S","M"],"material":"A sprinkle of holy water and diamonds worth at least 25,000gp, which the spell consumes.","ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 hour","level":9,"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/true-resurrection","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-true-seeing', 'spell', 'True Seeing', 'spell-true-seeing', '{"higher_level":[],"index":"true-seeing","name":"True Seeing","desc":["This spell gives the willing creature you touch the ability to see things as they actually are. For the duration, the creature has truesight, notices secret doors hidden by magic, and can see into the Ethereal Plane, all out to a range of 120 feet."],"range":"Touch","components":["V","S","M"],"material":"An ointment for the eyes that costs 25gp; is made from mushroom powder, saffron, and fat; and is consumed by the spell.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":6,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/true-seeing","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-true-strike', 'spell', 'True Strike', 'spell-true-strike', '{"higher_level":[],"index":"true-strike","name":"True Strike","desc":["You extend your hand and point a finger at a target in range. Your magic grants you a brief insight into the target''s defenses. On your next turn, you gain advantage on your first attack roll against the target, provided that this spell hasn''t ended."],"range":"30 feet","components":["S"],"ritual":false,"duration":"Up to 1 round","concentration":true,"casting_time":"1 action","level":0,"school":{"index":"divination","name":"Divination","url":"/api/2014/magic-schools/divination"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/true-strike","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-unseen-servant', 'spell', 'Unseen Servant', 'spell-unseen-servant', '{"higher_level":[],"index":"unseen-servant","name":"Unseen Servant","desc":["This spell creates an invisible, mindless, shapeless force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 hit point, and a Strength of 2, and it can''t attack. If it drops to 0 hit points, the spell ends.","Once on each of your turns as a bonus action, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human servant could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring wine. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command.","If you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends."],"range":"60 feet","components":["V","S","M"],"material":"A piece of string and a bit of wood.","ritual":true,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":1,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/unseen-servant","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-vampiric-touch', 'spell', 'Vampiric Touch', 'spell-vampiric-touch', '{"index":"vampiric-touch","name":"Vampiric Touch","desc":["The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against a creature within your reach. On a hit, the target takes 3d6 necrotic damage, and you regain hit points equal to half the amount of necrotic damage dealt. Until the spell ends, you can make the attack again on each of your turns as an action."],"higher_level":["When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."],"range":"Self","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"attack_type":"melee","damage":{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_at_slot_level":{"3":"3d6","4":"4d6","5":"5d6","6":"6d6","7":"7d6","8":"8d6","9":"9d6"}},"school":{"index":"necromancy","name":"Necromancy","url":"/api/2014/magic-schools/necromancy"},"classes":[{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/vampiric-touch","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-vicious-mockery', 'spell', 'Vicious Mockery', 'spell-vicious-mockery', '{"higher_level":[],"index":"vicious-mockery","name":"Vicious Mockery","desc":["You unleash a string of insults laced with subtle enchantments at a creature you can see within range. If the target can hear you (though it need not understand you), it must succeed on a wisdom saving throw or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn.","This spell''s damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4)."],"range":"60 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":0,"damage":{"damage_type":{"index":"psychic","name":"Psychic","url":"/api/2014/damage-types/psychic"},"damage_at_character_level":{"1":"1d4","5":"2d4","11":"3d4","17":"4d4"}},"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"}],"subclasses":[],"url":"/api/2014/spells/vicious-mockery","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-wall-of-fire', 'spell', 'Wall of Fire', 'spell-wall-of-fire', '{"index":"wall-of-fire","name":"Wall of Fire","desc":["You create a wall of fire on a solid surface within range. You can make the wall up to 60 feet long, 20 feet high, and 1 foot thick, or a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall is opaque and lasts for the duration.","When the wall appears, each creature within its area must make a Dexterity saving throw. On a failed save, a creature takes 5d8 fire damage, or half as much damage on a successful save.","One side of the wall, selected by you when you cast this spell, deals 5d8 fire damage to each creature that ends its turn within 10 feet o f that side or inside the wall. A creature takes the same damage when it enters the wall for the first time on a turn or ends its turn there. The other side of the wall deals no damage.","The other side of the wall deals no damage."],"higher_level":["When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th."],"range":"120 feet","components":["V","S","M"],"material":"A small piece of phosphorus.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":4,"damage":{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_at_slot_level":{"4":"5d8"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"line","size":60},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"}],"url":"/api/2014/spells/wall-of-fire","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-wall-of-force', 'spell', 'Wall of Force', 'spell-wall-of-force', '{"higher_level":[],"index":"wall-of-force","name":"Wall of Force","desc":["An invisible wall of force springs into existence at a point you choose within range. The wall appears in any orientation you choose, as a horizontal or vertical barrier or at an angle. It can be free floating or resting on a solid surface. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-by-10-foot panels. Each panel must be contiguous with another panel. In any form, the wall is 1/4 inch thick. It lasts for the duration. If the wall cuts through a creature''s space when it appears, the creature is pushed to one side of the wall (your choice which side).","Nothing can physically pass through the wall. It is immune to all damage and can''t be dispelled by dispel magic. A disintegrate spell destroys the wall instantly, however. The wall also extends into the Ethereal Plane, blocking ethereal travel through the wall."],"range":"120 feet","components":["V","S","M"],"material":"A pinch of powder made by crushing a clear gemstone.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":5,"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/wall-of-force","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-wall-of-ice', 'spell', 'Wall of Ice', 'spell-wall-of-ice', '{"index":"wall-of-ice","name":"Wall of Ice","desc":["You create a wall of ice on a solid surface within range. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-square panels. Each panel must be contiguous with another panel. In any form, the wall is 1 foot thick and lasts for the duration.","If the wall cuts through a creature''s space when it appears, the creature within its area is pushed to one side of the wall and must make a dexterity saving throw. On a failed save, the creature takes 10d6 cold damage, or half as much damage on a successful save.","The wall is an object that can be damaged and thus breached. It has AC 12 and 30 hit points per 10-foot section, and it is vulnerable to fire damage. Reducing a 10-foot section of wall to 0 hit points destroys it and leaves behind a sheet of frigid air in the space the wall occupied. A creature moving through the sheet of frigid air for the first time on a turn must make a constitution saving throw. That creature takes 5d6 cold damage on a failed save, or half as much damage on a successful one."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, the damage the wall deals when it appears increases by 2d6, and the damage from passing through the sheet of frigid air increases by 1d6, for each slot level above 6th."],"range":"120 feet","components":["V","S","M"],"material":"A small piece of quartz.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"cold","name":"Cold","url":"/api/2014/damage-types/cold"},"damage_at_slot_level":{"6":"10d6","7":"12d6","8":"14d6","9":"16d6"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"sphere","size":10},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/wall-of-ice","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-wall-of-stone', 'spell', 'Wall of Stone', 'spell-wall-of-stone', '{"higher_level":[],"index":"wall-of-stone","name":"Wall of Stone","desc":["A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-foot-by-10-foot panels. Each panel must be contiguous with at least one other panel. Alternatively, you can create 10-foot-by-20-foot panels that are only 3 inches thick.","If the wall cuts through a creature''s space when it appears, the creature is pushed to one side of the wall (your choice). If a creature would be surrounded on all sides by the wall (or the wall and another solid surface), that creature can make a dexterity saving throw. On a success, it can use its reaction to move up to its speed so that it is no longer enclosed by the wall.","The wall can have any shape you desire, though it can''t occupy the same space as a creature or object. The wall doesn''t need to be vertical or rest on any firm foundation. It must, however, merge with and be solidly supported by existing stone. Thus, you can use this spell to bridge a chasm or create a ramp.","If you create a span greater than 20 feet in length, you must halve the size of each panel to create supports. You can crudely shape the wall to create crenellations, battlements, and so on.","The wall is an object made of stone that can be damaged and thus breached. Each panel has AC 15 and 30 hit points per inch of thickness. Reducing a panel to 0 hit points destroys it and might cause connected panels to collapse at the GM''s discretion.","If you maintain your concentration on this spell for its whole duration, the wall becomes permanent and can''t be dispelled. Otherwise, the wall disappears when the spell ends."],"range":"120 feet","components":["V","S","M"],"material":"A small block of granite.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":5,"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/wall-of-stone","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-wall-of-thorns', 'spell', 'Wall of Thorns', 'spell-wall-of-thorns', '{"index":"wall-of-thorns","name":"Wall of Thorns","desc":["You create a wall of tough, pliable, tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight.","When the wall appears, each creature within its area must make a dexterity saving throw. On a failed save, a creature takes 7d8 piercing damage, or half as much damage on a successful save.","A creature can move through the wall, albeit slowly and painfully. For every 1 foot a creature moves through the wall, it must spend 4 feet of movement. Furthermore, the first time a creature enters the wall on a turn or ends its turn there, the creature must make a dexterity saving throw. It takes 7d8 slashing damage on a failed save, or half as much damage on a successful one."],"higher_level":["When you cast this spell using a spell slot of 7th level or higher, both types of damage increase by 1d8 for each slot level above 6th."],"range":"120 feet","components":["V","S","M"],"material":"A handful of thorns.","ritual":false,"duration":"Up to 10 minutes","concentration":true,"casting_time":"1 action","level":6,"damage":{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_at_slot_level":{"6":"7d8","7":"8d8","8":"9d8","9":"10d8"}},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_success":"half"},"area_of_effect":{"type":"line","size":60},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/wall-of-thorns","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-warding-bond', 'spell', 'Warding Bond', 'spell-warding-bond', '{"higher_level":[],"index":"warding-bond","name":"Warding Bond","desc":["This spell wards a willing creature you touch and creates a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws, and it has resistance to all damage. Also, each time it takes damage, you take the same amount of damage.","The spell ends if you drop to 0 hit points or if you and the target become separated by more than 60 feet.","It also ends if the spell is cast again on either of the connected creatures. You can also dismiss the spell as an action."],"range":"Touch","components":["V","S","M"],"material":"A pair of platinum rings worth at least 50gp each, which you and the target must wear for the duration.","ritual":false,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":2,"school":{"index":"abjuration","name":"Abjuration","url":"/api/2014/magic-schools/abjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/warding-bond","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-water-breathing', 'spell', 'Water Breathing', 'spell-water-breathing', '{"higher_level":[],"index":"water-breathing","name":"Water Breathing","desc":["This spell gives a maximum of ten willing creatures within range and you can see, the ability to breathe underwater until the end of its term. Affected creatures also retain their normal breathing pattern."],"range":"30 feet","components":["V","S","M"],"material":"A short piece of reed or straw.","ritual":true,"duration":"24 hours","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/water-breathing","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-water-walk', 'spell', 'Water Walk', 'spell-water-walk', '{"higher_level":[],"index":"water-walk","name":"Water Walk","desc":["This spell grants the ability to move across any liquid surface--such as water, acid, mud, snow, quicksand, or lava--as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures you can see within range gain this ability for the duration.","If you target a creature submerged in a liquid, the spell carries the target to the surface of the liquid at a rate of 60 feet per round."],"range":"30 feet","components":["V","S","M"],"material":"A piece of cork.","ritual":true,"duration":"1 hour","concentration":false,"casting_time":"1 action","level":3,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"},{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/water-walk","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-web', 'spell', 'Web', 'spell-web', '{"higher_level":[],"index":"web","name":"Web","desc":["You conjure a mass of thick, sticky webbing at a point of your choice within range. The webs fill a 20-foot cube from that point for the duration. The webs are difficult terrain and lightly obscure their area.","If the webs aren''t anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the conjured web collapses on itself, and the spell ends at the start of your next turn. Webs layered over a flat surface have a depth of 5 feet.","Each creature that starts its turn in the webs or that enters them during its turn must make a dexterity saving throw. On a failed save, the creature is restrained as long as it remains in the webs or until it breaks free.","A creature restrained by the webs can use its action to make a Strength check against your spell save DC. If it succeeds, it is no longer restrained.","The webs are flammable. Any 5-foot cube of webs exposed to fire burns away in 1 round, dealing 2d4 fire damage to any creature that starts its turn in the fire."],"range":"60 feet","components":["V","S","M"],"material":"A bit of spiderweb.","ritual":false,"duration":"Up to 1 hour","concentration":true,"casting_time":"1 action","level":2,"area_of_effect":{"type":"cube","size":20},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"land","name":"Land","url":"/api/2014/subclasses/land"}],"url":"/api/2014/spells/web","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-weird', 'spell', 'Weird', 'spell-weird', '{"higher_level":[],"index":"weird","name":"Weird","desc":["Drawing on the deepest fears of a group of creatures, you create illusory creatures in their minds, visible only to them. Each creature in a 30-foot-radius sphere centered on a point of your choice within range must make a wisdom saving throw. On a failed save, a creature becomes frightened for the duration. The illusion calls on the creature''s deepest fears, manifesting its worst nightmares as an implacable threat. At the start of each of the frightened creature''s turns, it must succeed on a wisdom saving throw or take 4d10 psychic damage. On a successful save, the spell ends for that creature."],"range":"120 feet","components":["V","S"],"ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":9,"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_success":"none"},"area_of_effect":{"type":"sphere","size":30},"school":{"index":"illusion","name":"Illusion","url":"/api/2014/magic-schools/illusion"},"classes":[{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/weird","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-wind-walk', 'spell', 'Wind Walk', 'spell-wind-walk', '{"higher_level":[],"index":"wind-walk","name":"Wind Walk","desc":["You and up to ten willing creatures you can see within range assume a gaseous form for the duration, appearing as wisps of cloud. While in this cloud form, a creature has a flying speed of 300 feet and has resistance to damage from nonmagical weapons. The only actions a creature can take in this form are the Dash action or to revert to its normal form. Reverting takes 1 minute, during which time a creature is incapacitated and can''t move. Until the spell ends, a creature can revert to cloud form, which also requires the 1-minute transformation.","If a creature is in cloud form and flying when the effect ends, the creature descends 60 feet per round for 1 minute until it lands, which it does safely. If it can''t land after 1 minute, the creature falls the remaining distance."],"range":"30 feet","components":["V","S","M"],"material":"Fire and holy water.","ritual":false,"duration":"8 hours","concentration":false,"casting_time":"1 minute","level":6,"school":{"index":"transmutation","name":"Transmutation","url":"/api/2014/magic-schools/transmutation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"}],"subclasses":[],"url":"/api/2014/spells/wind-walk","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-wind-wall', 'spell', 'Wind Wall', 'spell-wind-wall', '{"higher_level":[],"index":"wind-wall","name":"Wind Wall","desc":["A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration.","When the wall appears, each creature within its area must make a strength saving throw. A creature takes 3d8 bludgeoning damage on a failed save, or half as much damage on a successful one.","The strong wind keeps fog, smoke, and other gases at bay. Small or smaller flying creatures or objects can''t pass through the wall. Loose, lightweight materials brought into the wall fly upward. Arrows, bolts, and other ordinary projectiles launched at targets behind the wall are deflected upward and automatically miss. (Boulders hurled by giants or siege engines, and similar projectiles, are unaffected.) Creatures in gaseous form can''t pass through it."],"range":"120 feet","components":["V","S","M"],"material":"A tiny fan and a feather of exotic origin.","ritual":false,"duration":"Up to 1 minute","concentration":true,"casting_time":"1 action","level":3,"damage":{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_at_slot_level":{"3":"3d8"}},"dc":{"dc_type":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"dc_success":"half"},"area_of_effect":{"type":"line","size":50},"school":{"index":"evocation","name":"Evocation","url":"/api/2014/magic-schools/evocation"},"classes":[{"index":"druid","name":"Druid","url":"/api/2014/classes/druid"},{"index":"ranger","name":"Ranger","url":"/api/2014/classes/ranger"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"}],"url":"/api/2014/spells/wind-wall","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-wish', 'spell', 'Wish', 'spell-wish', '{"higher_level":[],"index":"wish","name":"Wish","desc":["Wish is the mightiest spell a mortal creature can cast. By simply speaking aloud, you can alter the very foundations of reality in accord with your desires.","The basic use of this spell is to duplicate any other spell of 8th level or lower. You don''t need to meet any requirements in that spell, including costly components. The spell simply takes effect.","Alternatively, you can create one of the following effects of your choice:","- You create one object of up to 25,000 gp in value that isn''t a magic item. The object can be no more than 300 feet in any dimension, and it appears in an unoccupied space you can see on the ground.","- You allow up to twenty creatures that you can see to regain all hit points, and you end all effects on them described in the greater restoration spell.","- You grant up to ten creatures that you can see resistance to a damage type you choose.","- You grant up to ten creatures you can see immunity to a single spell or other magical effect for 8 hours. For instance, you could make yourself and all your companions immune to a lich''s life drain attack.","- You undo a single recent event by forcing a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a wish spell could undo an opponent''s successful save, a foe''s critical hit, or a friend''s failed save. You can force the reroll to be made with advantage or disadvantage, and you can choose whether to use the reroll or the original roll.","You might be able to achieve something beyond the scope of the above examples. State your wish to the GM as precisely as possible. The GM has great latitude in ruling what occurs in such an instance; the greater the wish, the greater the likelihood that something goes wrong. This spell might simply fail, the effect you desire might only be partly achieved, or you might suffer some unforeseen consequence as a result of how you worded the wish. For example, wishing that a villain were dead might propel you forward in time to a period when that villain is no longer alive, effectively removing you from the game. Similarly, wishing for a legendary magic item or artifact might instantly transport you to the presence of the item''s current owner.","The stress of casting this spell to produce any effect other than duplicating another spell weakens you. After enduring that stress, each time you cast a spell until you finish a long rest, you take 1d10 necrotic damage per level of that spell. This damage can''t be reduced or prevented in any way. In addition, your Strength drops to 3, if it isn''t 3 or lower already, for 2d4 days. For each of those days that you spend resting and doing nothing more than light activity, your remaining recovery time decreases by 2 days. Finally, there is a 33 percent chance that you are unable to cast wish ever again if you suffer this stress."],"range":"Self","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":9,"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"sorcerer","name":"Sorcerer","url":"/api/2014/classes/sorcerer"},{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"}],"subclasses":[],"url":"/api/2014/spells/wish","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-word-of-recall', 'spell', 'Word of Recall', 'spell-word-of-recall', '{"higher_level":[],"index":"word-of-recall","name":"Word of Recall","desc":["You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary. You and any creatures that teleport with you appear in the nearest unoccupied space to the spot you designated when you prepared your sanctuary (see below). If you cast this spell without first preparing a sanctuary, the spell has no effect.","You must designate a sanctuary by casting this spell within a location, such as a temple, dedicated to or strongly linked to your deity. If you attempt to cast the spell in this manner in an area that isn''t dedicated to your deity, the spell has no effect."],"range":"5 feet","components":["V"],"ritual":false,"duration":"Instantaneous","concentration":false,"casting_time":"1 action","level":6,"area_of_effect":{"type":"sphere","size":5},"school":{"index":"conjuration","name":"Conjuration","url":"/api/2014/magic-schools/conjuration"},"classes":[{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"}],"subclasses":[],"url":"/api/2014/spells/word-of-recall","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('spell-zone-of-truth', 'spell', 'Zone of Truth', 'spell-zone-of-truth', '{"higher_level":[],"index":"zone-of-truth","name":"Zone of Truth","desc":["You create a magical zone that guards against deception in a 15-foot-radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell''s area for the first time on a turn or starts its turn there must make a Charisma saving throw. On a failed save, a creature can''t speak a deliberate lie while in the radius. You know whether each creature succeeds or fails on its saving throw.","An affected creature is aware of the spell and can thus avoid answering questions to which it would normally respond with a lie. Such a creature can remain evasive in its answers as long as it remains within the boundaries of the truth."],"range":"60 feet","components":["V","S"],"ritual":false,"duration":"10 minutes","concentration":false,"casting_time":"1 action","level":2,"area_of_effect":{"type":"sphere","size":15},"school":{"index":"enchantment","name":"Enchantment","url":"/api/2014/magic-schools/enchantment"},"classes":[{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},{"index":"cleric","name":"Cleric","url":"/api/2014/classes/cleric"},{"index":"paladin","name":"Paladin","url":"/api/2014/classes/paladin"}],"subclasses":[{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},{"index":"devotion","name":"Devotion","url":"/api/2014/subclasses/devotion"}],"url":"/api/2014/spells/zone-of-truth","updated_at":"2026-04-01T20:35:39.218Z"}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-abacus', 'equipment', 'Abacus', 'equipment-abacus', '{"desc":[],"special":[],"index":"abacus","name":"Abacus","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":2,"unit":"gp"},"weight":2,"url":"/api/2014/equipment/abacus","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-acid-vial', 'equipment', 'Acid (vial)', 'equipment-acid-vial', '{"special":[],"index":"acid-vial","name":"Acid (vial)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":25,"unit":"gp"},"weight":1,"desc":["As an action, you can splash the contents of this vial onto a creature within 5 feet of you or throw the vial up to 20 feet, shattering it on impact. In either case, make a ranged attack against a creature or object, treating the acid as an improvised weapon.","On a hit, the target takes 2d6 acid damage."],"url":"/api/2014/equipment/acid-vial","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-alchemists-fire-flask', 'equipment', 'Alchemist''s fire (flask)', 'equipment-alchemists-fire-flask', '{"special":[],"index":"alchemists-fire-flask","name":"Alchemist''s fire (flask)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":50,"unit":"gp"},"desc":["This sticky, adhesive fluid ignites when exposed to air.","As an action, you can throw this flask up to 20 feet, shattering it on impact. Make a ranged attack against a creature or object, treating the alchemist''s fire as an improvised weapon.","On a hit, the target takes 1d4 fire damage at the start of each of its turns. A creature can end this damage by using its action to make a DC 10 Dexterity check to extinguish the flames."],"weight":1,"url":"/api/2014/equipment/alchemists-fire-flask","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-alchemists-supplies', 'equipment', 'Alchemist''s Supplies', 'equipment-alchemists-supplies', '{"special":[],"index":"alchemists-supplies","name":"Alchemist''s Supplies","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Artisan''s Tools","cost":{"quantity":50,"unit":"gp"},"weight":8,"desc":["These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency."],"url":"/api/2014/equipment/alchemists-supplies","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-alms-box', 'equipment', 'Alms box', 'equipment-alms-box', '{"special":[],"index":"alms-box","name":"Alms box","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":0,"unit":"cp"},"weight":0,"desc":["A small box for alms, typically found in a priest''s pack."],"url":"/api/2014/equipment/alms-box","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-amulet', 'equipment', 'Amulet', 'equipment-amulet', '{"special":[],"index":"amulet","name":"Amulet","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"holy-symbols","name":"Holy Symbols","url":"/api/2014/equipment-categories/holy-symbols"},"cost":{"quantity":5,"unit":"gp"},"weight":1,"desc":["A holy symbol is a representation of a god or pantheon. It might be an amulet depicting a symbol representing a deity, the same symbol carefully engraved or inlaid as an emblem on a shield, or a tiny box holding a fragment of a sacred relic.","Appendix B lists the symbols commonly associated with many gods in the multiverse. A cleric or paladin can use a holy symbol as a spellcasting focus. To use the symbol in this way, the caster must hold it in hand, wear it visibly, or bear it on a shield."],"url":"/api/2014/equipment/amulet","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-animal-feed-1-day', 'equipment', 'Animal Feed (1 day)', 'equipment-animal-feed-1-day', '{"desc":[],"special":[],"index":"animal-feed-1-day","name":"Animal Feed (1 day)","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Tack, Harness, and Drawn Vehicles","cost":{"quantity":5,"unit":"cp"},"weight":10,"url":"/api/2014/equipment/animal-feed-1-day","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-antitoxin-vial', 'equipment', 'Antitoxin (vial)', 'equipment-antitoxin-vial', '{"special":[],"index":"antitoxin-vial","name":"Antitoxin (vial)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":50,"unit":"gp"},"weight":0,"desc":["A creature that drinks this vial of liquid gains advantage on saving throws against poison for 1 hour. It confers no benefit to undead or constructs."],"url":"/api/2014/equipment/antitoxin-vial","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-arrow', 'equipment', 'Arrow', 'equipment-arrow', '{"desc":[],"special":[],"index":"arrow","name":"Arrow","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"ammunition","name":"Ammunition","url":"/api/2014/equipment-categories/ammunition"},"quantity":20,"cost":{"quantity":1,"unit":"gp"},"weight":1,"url":"/api/2014/equipment/arrow","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-backpack', 'equipment', 'Backpack', 'equipment-backpack', '{"desc":[],"special":[],"index":"backpack","name":"Backpack","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":2,"unit":"gp"},"weight":5,"url":"/api/2014/equipment/backpack","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-bagpipes', 'equipment', 'Bagpipes', 'equipment-bagpipes', '{"special":[],"index":"bagpipes","name":"Bagpipes","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Musical Instrument","cost":{"quantity":30,"unit":"gp"},"weight":6,"desc":["Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency."],"url":"/api/2014/equipment/bagpipes","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-ball-bearings-bag-of-1000', 'equipment', 'Ball bearings (bag of 1,000)', 'equipment-ball-bearings-bag-of-1000', '{"special":[],"index":"ball-bearings-bag-of-1000","name":"Ball bearings (bag of 1,000)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":1,"unit":"gp"},"weight":2,"desc":["As an action, you can spill these tiny metal balls from their pouch to cover a level, square area that is 10 feet on a side.","A creature moving across the covered area must succeed on a DC 10 Dexterity saving throw or fall prone.","A creature moving through the area at half speed doesn''t need to make the save."],"image":"/api/images/equipment/ball-bearings-bag-of-1000.png","url":"/api/2014/equipment/ball-bearings-bag-of-1000","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
