INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-caltrops', 'equipment', 'Caltrops', 'equipment-caltrops', '{"special":[],"index":"caltrops","name":"Caltrops","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":5,"unit":"cp"},"weight":2,"desc":["As an action, you can spread a bag of caltrops to cover a square area that is 5 feet on a side.","Any creature that enters the area must succeed on a DC 15 Dexterity saving throw or stop moving this turn and take 1 piercing damage.","Taking this damage reduces the creature''s walking speed by 10 feet until the creature regains at least 1 hit point.","A creature moving through the area at half speed doesn''t need to make the save."],"url":"/api/2014/equipment/caltrops","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
