INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-crystal', 'equipment', 'Crystal', 'equipment-crystal', '{"special":[],"index":"crystal","name":"Crystal","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"arcane-foci","name":"Arcane Foci","url":"/api/2014/equipment-categories/arcane-foci"},"cost":{"quantity":10,"unit":"gp"},"weight":1,"desc":["An arcane focus is a special item--an orb, a crystal, a rod, a specially constructed staff, a wand-like length of wood, or some similar item--designed to channel the power of arcane spells. A sorcerer, warlock, or wizard can use such an item as a spellcasting focus."],"url":"/api/2014/equipment/crystal","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
