INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-dice-set', 'equipment', 'Dice Set', 'equipment-dice-set', '{"special":[],"index":"dice-set","name":"Dice Set","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Gaming Sets","cost":{"quantity":1,"unit":"sp"},"weight":0,"desc":["This item encompasses a wide range of game pieces, including dice and decks of cards (for games such as Three-Dragon Ante). A few common examples appear on the Tools table, but other kinds of gaming sets exist. If you are proficient with a gaming set, you can add your proficiency bonus to ability checks you make to play a game with that set. Each type of gaming set requires a separate proficiency."],"url":"/api/2014/equipment/dice-set","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
