INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-disguise-kit', 'equipment', 'Disguise Kit', 'equipment-disguise-kit', '{"special":[],"index":"disguise-kit","name":"Disguise Kit","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"kits","name":"Kits","url":"/api/2014/equipment-categories/kits"},"cost":{"quantity":25,"unit":"gp"},"weight":3,"desc":["This pouch of cosmetics, hair dye, and small props lets you create disguises that change your physical appearance. Proficiency with this kit lets you add your proficiency bonus to any ability checks you make to create a visual disguise."],"url":"/api/2014/equipment/disguise-kit","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
