INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-drum', 'equipment', 'Drum', 'equipment-drum', '{"special":[],"index":"drum","name":"Drum","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Musical Instrument","cost":{"quantity":6,"unit":"gp"},"weight":3,"desc":["Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency."],"url":"/api/2014/equipment/drum","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
