INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-emblem', 'equipment', 'Emblem', 'equipment-emblem', '{"special":[],"index":"emblem","name":"Emblem","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"holy-symbols","name":"Holy Symbols","url":"/api/2014/equipment-categories/holy-symbols"},"cost":{"quantity":5,"unit":"gp"},"weight":0,"desc":["A holy symbol is a representation of a god or pantheon. It might be an amulet depicting a symbol representing a deity, the same symbol carefully engraved or inlaid as an emblem on a shield, or a tiny box holding a fragment of a sacred relic.","Appendix B lists the symbols commonly associated with many gods in the multiverse. A cleric or paladin can use a holy symbol as a spellcasting focus. To use the symbol in this way, the caster must hold it in hand, wear it visibly, or bear it on a shield."],"url":"/api/2014/equipment/emblem","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
