INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-glassblowers-tools', 'equipment', 'Glassblower''s Tools', 'equipment-glassblowers-tools', '{"special":[],"index":"glassblowers-tools","name":"Glassblower''s Tools","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Artisan''s Tools","cost":{"quantity":30,"unit":"gp"},"weight":5,"desc":["These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency."],"url":"/api/2014/equipment/glassblowers-tools","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
