INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-healers-kit', 'equipment', 'Healer''s Kit', 'equipment-healers-kit', '{"special":[],"index":"healers-kit","name":"Healer''s Kit","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"kits","name":"Kits","url":"/api/2014/equipment-categories/kits"},"cost":{"quantity":5,"unit":"gp"},"weight":3,"desc":["This kit is a leather pouch containing bandages, salves, and splints. The kit has ten uses. As an action, you can expend one use of the kit to stabilize a creature that has 0 hit points, without needing to make a Wisdom (Medicine) check."],"url":"/api/2014/equipment/healers-kit","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-herbalism-kit', 'equipment', 'Herbalism Kit', 'equipment-herbalism-kit', '{"special":[],"index":"herbalism-kit","name":"Herbalism Kit","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"kits","name":"Kits","url":"/api/2014/equipment-categories/kits"},"cost":{"quantity":5,"unit":"gp"},"weight":3,"desc":["This kit contains a variety of instruments such as clippers, mortar and pestle, and pouches and vials used by herbalists to create remedies and potions. Proficiency with this kit lets you add your proficiency bonus to any ability checks you make to identify or apply herbs. Also, proficiency with this kit is required to create antitoxin and potions of healing."],"url":"/api/2014/equipment/herbalism-kit","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-hide-armor', 'equipment', 'Hide Armor', 'equipment-hide-armor', '{"desc":[],"special":[],"index":"hide-armor","name":"Hide Armor","equipment_category":{"index":"armor","name":"Armor","url":"/api/2014/equipment-categories/armor"},"armor_category":"Medium","armor_class":{"base":12,"dex_bonus":true,"max_bonus":2},"str_minimum":0,"stealth_disadvantage":false,"weight":12,"cost":{"quantity":10,"unit":"gp"},"url":"/api/2014/equipment/hide-armor","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-holy-water-flask', 'equipment', 'Holy water (flask)', 'equipment-holy-water-flask', '{"special":[],"index":"holy-water-flask","name":"Holy water (flask)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":25,"unit":"gp"},"weight":1,"desc":["As an action, you can splash the contents of this flask onto a creature within 5 feet of you or throw it up to 20 feet, shattering it on impact. In either case, make a ranged attack against a target creature, treating the holy water as an improvised weapon.","If the target is a fiend or undead, it takes 2d6 radiant damage.","A cleric or paladin may create holy water by performing a special ritual.","The ritual takes 1 hour to perform, uses 25 gp worth of powdered silver, and requires the caster to expend a 1st-level spell slot."],"url":"/api/2014/equipment/holy-water-flask","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-horn', 'equipment', 'Horn', 'equipment-horn', '{"special":[],"index":"horn","name":"Horn","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Musical Instrument","cost":{"quantity":3,"unit":"gp"},"weight":2,"desc":["Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency."],"url":"/api/2014/equipment/horn","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-horse-draft', 'equipment', 'Horse, draft', 'equipment-horse-draft', '{"desc":[],"special":[],"index":"horse-draft","name":"Horse, draft","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Mounts and Other Animals","cost":{"quantity":50,"unit":"gp"},"speed":{"quantity":40,"unit":"ft/round"},"capacity":"540 lb.","url":"/api/2014/equipment/horse-draft","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
