INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-hourglass', 'equipment', 'Hourglass', 'equipment-hourglass', '{"desc":[],"special":[],"index":"hourglass","name":"Hourglass","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":25,"unit":"gp"},"weight":1,"url":"/api/2014/equipment/hourglass","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-hunting-trap', 'equipment', 'Hunting trap', 'equipment-hunting-trap', '{"special":[],"index":"hunting-trap","name":"Hunting trap","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":5,"unit":"gp"},"desc":["When you use your action to set it, this trap forms a saw-toothed steel ring that snaps shut when a creature steps on a pressure plate in the center. The trap is affixed by a heavy chain to an immobile object, such as a tree or a spike driven into the ground.","A creature that steps on the plate must succeed on a DC 13 Dexterity saving throw or take 1d4 piercing damage and stop moving. Thereafter, until the creature breaks free of the trap, its movement is limited by the length of the chain (typically 3 feet long).","A creature can use its action to make a DC 13 Strength check, freeing itself or another creature within its reach on a success. Each failed check deals 1 piercing damage to the trapped creature."],"weight":25,"url":"/api/2014/equipment/hunting-trap","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-ink-1-ounce-bottle', 'equipment', 'Ink (1 ounce bottle)', 'equipment-ink-1-ounce-bottle', '{"desc":[],"special":[],"index":"ink-1-ounce-bottle","name":"Ink (1 ounce bottle)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":10,"unit":"gp"},"weight":0,"url":"/api/2014/equipment/ink-1-ounce-bottle","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
