INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-keelboat', 'equipment', 'Keelboat', 'equipment-keelboat', '{"special":[],"index":"keelboat","name":"Keelboat","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Waterborne Vehicles","cost":{"quantity":3000,"unit":"gp"},"speed":{"quantity":1,"unit":"mph"},"desc":["Keelboats and rowboats are used on lakes and rivers. If going downstream, add the speed of the current (typically 3 miles per hour) to the speed of the vehicle. These vehicles can''t be rowed against any significant current, but they can be pulled upstream by draft animals on the shores. A rowboat weighs 100 pounds, in case adventurers carry it over land."],"url":"/api/2014/equipment/keelboat","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-ladder-10-foot', 'equipment', 'Ladder (10-foot)', 'equipment-ladder-10-foot', '{"desc":[],"special":[],"index":"ladder-10-foot","name":"Ladder (10-foot)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":1,"unit":"sp"},"weight":25,"url":"/api/2014/equipment/ladder-10-foot","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-lamp', 'equipment', 'Lamp', 'equipment-lamp', '{"special":[],"index":"lamp","name":"Lamp","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":5,"unit":"sp"},"weight":1,"desc":["A lamp casts bright light in a 15-foot radius and dim light for an additional 30 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil."],"url":"/api/2014/equipment/lamp","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-lance', 'equipment', 'Lance', 'equipment-lance', '{"desc":[],"index":"lance","name":"Lance","equipment_category":{"index":"weapon","name":"Weapon","url":"/api/2014/equipment-categories/weapon"},"weapon_category":"Martial","weapon_range":"Melee","category_range":"Martial Melee","cost":{"quantity":10,"unit":"gp"},"damage":{"damage_dice":"1d12","damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"}},"range":{"normal":5},"weight":6,"properties":[{"index":"reach","name":"Reach","url":"/api/2014/weapon-properties/reach"},{"index":"special","name":"Special","url":"/api/2014/weapon-properties/special"}],"special":["You have disadvantage when you use a lance to attack a target within 5 feet of you. Also, a lance requires two hands to wield when you aren''t mounted."],"url":"/api/2014/equipment/lance","updated_at":"2026-04-01T20:35:37.141Z","contents":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-lantern-bullseye', 'equipment', 'Lantern, bullseye', 'equipment-lantern-bullseye', '{"special":[],"index":"lantern-bullseye","name":"Lantern, bullseye","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":10,"unit":"gp"},"weight":2,"desc":["A bullseye lantern casts bright light in a 60-foot cone and dim light for an additional 60 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil."],"url":"/api/2014/equipment/lantern-bullseye","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-lantern-hooded', 'equipment', 'Lantern, hooded', 'equipment-lantern-hooded', '{"special":[],"index":"lantern-hooded","name":"Lantern, hooded","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":5,"unit":"gp"},"weight":2,"desc":["A hooded lantern casts bright light in a 30-foot radius and dim light for an additional 30 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil. As an action, you can lower the hood, reducing the light to dim light in a 5-foot radius."],"url":"/api/2014/equipment/lantern-hooded","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-leather-armor', 'equipment', 'Leather Armor', 'equipment-leather-armor', '{"desc":[],"special":[],"index":"leather-armor","name":"Leather Armor","equipment_category":{"index":"armor","name":"Armor","url":"/api/2014/equipment-categories/armor"},"armor_category":"Light","armor_class":{"base":11,"dex_bonus":true},"str_minimum":0,"stealth_disadvantage":false,"weight":10,"cost":{"quantity":10,"unit":"gp"},"url":"/api/2014/equipment/leather-armor","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-leatherworkers-tools', 'equipment', 'Leatherworker''s Tools', 'equipment-leatherworkers-tools', '{"special":[],"index":"leatherworkers-tools","name":"Leatherworker''s Tools","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Artisan''s Tools","cost":{"quantity":5,"unit":"gp"},"weight":5,"desc":["These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency."],"url":"/api/2014/equipment/leatherworkers-tools","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
