INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-little-bag-of-sand', 'equipment', 'Little bag of sand', 'equipment-little-bag-of-sand', '{"special":[],"index":"little-bag-of-sand","name":"Little bag of sand","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":0,"unit":"cp"},"weight":0,"desc":["A small bag of sand, typically found in a scholar''s pack."],"url":"/api/2014/equipment/little-bag-of-sand","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-lock', 'equipment', 'Lock', 'equipment-lock', '{"special":[],"index":"lock","name":"Lock","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":10,"unit":"gp"},"weight":1,"desc":["A key is provided with the lock. Without the key, a creature proficient with thieves'' tools can pick this lock with a successful DC 15 Dexterity check. Your GM may decide that better locks are available for higher prices."],"url":"/api/2014/equipment/lock","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
