INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-longsword', 'equipment', 'Longsword', 'equipment-longsword', '{"desc":[],"special":[],"index":"longsword","name":"Longsword","equipment_category":{"index":"weapon","name":"Weapon","url":"/api/2014/equipment-categories/weapon"},"weapon_category":"Martial","weapon_range":"Melee","category_range":"Martial Melee","cost":{"quantity":15,"unit":"gp"},"damage":{"damage_dice":"1d8","damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"}},"range":{"normal":5},"weight":3,"properties":[{"index":"versatile","name":"Versatile","url":"/api/2014/weapon-properties/versatile"}],"two_handed_damage":{"damage_dice":"1d10","damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"}},"url":"/api/2014/equipment/longsword","updated_at":"2026-04-01T20:35:37.141Z","contents":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-lute', 'equipment', 'Lute', 'equipment-lute', '{"special":[],"index":"lute","name":"Lute","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Musical Instrument","cost":{"quantity":35,"unit":"gp"},"weight":2,"desc":["Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency."],"url":"/api/2014/equipment/lute","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-lyre', 'equipment', 'Lyre', 'equipment-lyre', '{"special":[],"index":"lyre","name":"Lyre","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Musical Instrument","cost":{"quantity":30,"unit":"gp"},"weight":2,"desc":["Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency."],"url":"/api/2014/equipment/lyre","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-mace', 'equipment', 'Mace', 'equipment-mace', '{"desc":[],"special":[],"index":"mace","name":"Mace","equipment_category":{"index":"weapon","name":"Weapon","url":"/api/2014/equipment-categories/weapon"},"weapon_category":"Simple","weapon_range":"Melee","category_range":"Simple Melee","cost":{"quantity":5,"unit":"gp"},"damage":{"damage_dice":"1d6","damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"}},"range":{"normal":5},"weight":4,"properties":[{"index":"monk","name":"Monk","url":"/api/2014/weapon-properties/monk"}],"url":"/api/2014/equipment/mace","updated_at":"2026-04-01T20:35:37.141Z","contents":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-magnifying-glass', 'equipment', 'Magnifying glass', 'equipment-magnifying-glass', '{"special":[],"index":"magnifying-glass","name":"Magnifying glass","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":100,"unit":"gp"},"weight":0,"desc":["This lens allows a closer look at small objects. It is also useful as a substitute for flint and steel when starting fires. Lighting a fire with a magnifying glass requires light as bright as sunlight to focus, tinder to ignite, and about 5 minutes for the fire to ignite.","A magnifying glass grants advantage on any ability check made to appraise or inspect an item that is small or highly detailed."],"url":"/api/2014/equipment/magnifying-glass","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-manacles', 'equipment', 'Manacles', 'equipment-manacles', '{"special":[],"index":"manacles","name":"Manacles","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":2,"unit":"gp"},"weight":6,"desc":["These metal restraints can bind a Small or Medium creature. Escaping the manacles requires a successful DC 20 Dexterity check. Breaking them requires a successful DC 20 Strength check.","Each set of manacles comes with one key. Without the key, a creature proficient with thieves'' tools can pick the manacles'' lock with a successful DC 15 Dexterity check. Manacles have 15 hit points."],"url":"/api/2014/equipment/manacles","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-masons-tools', 'equipment', 'Mason''s Tools', 'equipment-masons-tools', '{"special":[],"index":"masons-tools","name":"Mason''s Tools","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Artisan''s Tools","cost":{"quantity":10,"unit":"gp"},"weight":8,"desc":["These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency."],"url":"/api/2014/equipment/masons-tools","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
