INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-mess-kit', 'equipment', 'Mess Kit', 'equipment-mess-kit', '{"special":[],"index":"mess-kit","name":"Mess Kit","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"kits","name":"Kits","url":"/api/2014/equipment-categories/kits"},"cost":{"quantity":2,"unit":"sp"},"weight":1,"desc":["This tin box contains a cup and simple cutlery. The box clamps together, and one side can be used as a cooking pan and the other as a plate or shallow bowl."],"url":"/api/2014/equipment/mess-kit","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
