INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-mule', 'equipment', 'Mule', 'equipment-mule', '{"desc":[],"special":[],"index":"mule","name":"Mule","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Mounts and Other Animals","cost":{"quantity":8,"unit":"gp"},"speed":{"quantity":40,"unit":"ft/round"},"capacity":"420 lb.","url":"/api/2014/equipment/mule","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-navigators-tools', 'equipment', 'Navigator''s Tools', 'equipment-navigators-tools', '{"special":[],"index":"navigators-tools","name":"Navigator''s Tools","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Other Tools","cost":{"quantity":25,"unit":"gp"},"weight":2,"desc":["This set of instruments is used for navigation at sea. Proficiency with navigator''s tools lets you chart a ship''s course and follow navigation charts. In addition, these tools allow you to add your proficiency bonus to any ability check you make to avoid getting lost at sea."],"url":"/api/2014/equipment/navigators-tools","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-net', 'equipment', 'Net', 'equipment-net', '{"desc":[],"index":"net","name":"Net","equipment_category":{"index":"weapon","name":"Weapon","url":"/api/2014/equipment-categories/weapon"},"weapon_category":"Martial","weapon_range":"Ranged","category_range":"Martial Ranged","cost":{"quantity":1,"unit":"gp"},"range":{"normal":5,"long":15},"weight":3,"properties":[{"index":"thrown","name":"Thrown","url":"/api/2014/weapon-properties/thrown"},{"index":"special","name":"Special","url":"/api/2014/weapon-properties/special"}],"special":["A Large or smaller creature hit by a net is restrained until it is freed. A net has no effect on creatures that are formless, or creatures that are Huge or larger. A creature can use its action to make a DC 10 Strength check, freeing itself or another creature within its reach on a success. Dealing 5 slashing damage to the net (AC 10) also frees the creature without harming it, ending the effect and destroying the net. When you use an action, bonus action, or reaction to attack with a net, you can make only one attack regardless of the number of attacks you can normally make."],"throw_range":{"normal":5,"long":15},"url":"/api/2014/equipment/net","updated_at":"2026-04-01T20:35:37.141Z","contents":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-oil-flask', 'equipment', 'Oil (flask)', 'equipment-oil-flask', '{"special":[],"index":"oil-flask","name":"Oil (flask)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":1,"unit":"sp"},"weight":1,"desc":["Oil usually comes in a clay flask that holds 1 pint.","As an action, you can splash the oil in this flask onto a creature within 5 feet of you or throw it up to 20 feet, shattering it on impact. Make a ranged attack against a target creature or object, treating the oil as an improvised weapon.","On a hit, the target is covered in oil. If the target takes any fire damage before the oil dries (after 1 minute), the target takes an additional 5 fire damage from the burning oil.","You can also pour a flask of oil on the ground to cover a 5-foot-square area, provided that the surface is level.","If lit, the oil burns for 2 rounds and deals 5 fire damage to any creature that enters the area or ends its turn in the area. A creature can take this damage only once per turn."],"url":"/api/2014/equipment/oil-flask","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-orb', 'equipment', 'Orb', 'equipment-orb', '{"special":[],"index":"orb","name":"Orb","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"arcane-foci","name":"Arcane Foci","url":"/api/2014/equipment-categories/arcane-foci"},"cost":{"quantity":20,"unit":"gp"},"weight":3,"desc":["An arcane focus is a special item--an orb, a crystal, a rod, a specially constructed staff, a wand-like length of wood, or some similar item--designed to channel the power of arcane spells. A sorcerer, warlock, or wizard can use such an item as a spellcasting focus."],"url":"/api/2014/equipment/orb","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-padded-armor', 'equipment', 'Padded Armor', 'equipment-padded-armor', '{"desc":[],"special":[],"index":"padded-armor","name":"Padded Armor","equipment_category":{"index":"armor","name":"Armor","url":"/api/2014/equipment-categories/armor"},"armor_category":"Light","armor_class":{"base":11,"dex_bonus":true},"str_minimum":0,"stealth_disadvantage":true,"weight":8,"cost":{"quantity":5,"unit":"gp"},"url":"/api/2014/equipment/padded-armor","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-painters-supplies', 'equipment', 'Painter''s Supplies', 'equipment-painters-supplies', '{"special":[],"index":"painters-supplies","name":"Painter''s Supplies","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Artisan''s Tools","cost":{"quantity":10,"unit":"gp"},"weight":5,"desc":["These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency."],"url":"/api/2014/equipment/painters-supplies","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-pan-flute', 'equipment', 'Pan flute', 'equipment-pan-flute', '{"special":[],"index":"pan-flute","name":"Pan flute","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Musical Instrument","cost":{"quantity":12,"unit":"gp"},"weight":2,"desc":["Several of the most common types of musical instruments are shown on the table as examples. If you have proficiency with a given musical instrument, you can add your proficiency bonus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus. Each type of musical instrument requires a separate proficiency."],"url":"/api/2014/equipment/pan-flute","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
