INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-playing-card-set', 'equipment', 'Playing Card Set', 'equipment-playing-card-set', '{"special":[],"index":"playing-card-set","name":"Playing Card Set","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Gaming Sets","cost":{"quantity":5,"unit":"sp"},"weight":0,"desc":["This item encompasses a wide range of game pieces, including dice and decks of cards (for games such as Three-Dragon Ante). A few common examples appear on the Tools table, but other kinds of gaming sets exist. If you are proficient with a gaming set, you can add your proficiency bonus to ability checks you make to play a game with that set. Each type of gaming set requires a separate proficiency."],"image":"/api/images/equipment/playing-card-set.png","url":"/api/2014/equipment/playing-card-set","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-poison-basic-vial', 'equipment', 'Poison, basic (vial)', 'equipment-poison-basic-vial', '{"special":[],"index":"poison-basic-vial","name":"Poison, basic (vial)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":100,"unit":"gp"},"weight":0,"desc":["You can use the poison in this vial to coat one slashing or piercing weapon or up to three pieces of ammunition. Applying the poison takes an action. A creature hit by the poisoned weapon or ammunition must make a DC 10 Constitution saving throw or take 1d4 poison damage. Once applied, the poison retains potency for 1 minute before drying."],"url":"/api/2014/equipment/poison-basic-vial","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-poisoners-kit', 'equipment', 'Poisoner''s Kit', 'equipment-poisoners-kit', '{"special":[],"index":"poisoners-kit","name":"Poisoner''s Kit","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"kits","name":"Kits","url":"/api/2014/equipment-categories/kits"},"cost":{"quantity":50,"unit":"gp"},"weight":2,"desc":["A poisoner''s kit includes the vials, chemicals, and other equipment necessary for the creation of poisons. Proficiency with this kit lets you add your proficiency bonus to any ability checks you make to craft or use poisons."],"url":"/api/2014/equipment/poisoners-kit","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
