INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-pouch', 'equipment', 'Pouch', 'equipment-pouch', '{"special":[],"index":"pouch","name":"Pouch","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":5,"unit":"sp"},"weight":1,"desc":["A cloth or leather pouch can hold up to 20 sling bullets or 50 blowgun needles, among other things. A compartmentalized pouch for holding spell components is called a component pouch (described earlier in this section)."],"url":"/api/2014/equipment/pouch","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
