INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-ram-portable', 'equipment', 'Ram, portable', 'equipment-ram-portable', '{"special":[],"index":"ram-portable","name":"Ram, portable","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":4,"unit":"gp"},"weight":35,"desc":["You can use a portable ram to break down doors. When doing so, you gain a +4 bonus on the Strength check. One other character can help you use the ram, giving you advantage on this check."],"url":"/api/2014/equipment/ram-portable","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-rapier', 'equipment', 'Rapier', 'equipment-rapier', '{"desc":[],"special":[],"index":"rapier","name":"Rapier","equipment_category":{"index":"weapon","name":"Weapon","url":"/api/2014/equipment-categories/weapon"},"weapon_category":"Martial","weapon_range":"Melee","category_range":"Martial Melee","cost":{"quantity":25,"unit":"gp"},"damage":{"damage_dice":"1d8","damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"}},"range":{"normal":5},"weight":2,"properties":[{"index":"finesse","name":"Finesse","url":"/api/2014/weapon-properties/finesse"}],"url":"/api/2014/equipment/rapier","updated_at":"2026-04-01T20:35:37.141Z","contents":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-rations-1-day', 'equipment', 'Rations (1 day)', 'equipment-rations-1-day', '{"special":[],"index":"rations-1-day","name":"Rations (1 day)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":5,"unit":"sp"},"weight":2,"desc":["Rations consist of dry foods suitable for extended travel, including jerky, dried fruit, hardtack, and nuts."],"url":"/api/2014/equipment/rations-1-day","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-reliquary', 'equipment', 'Reliquary', 'equipment-reliquary', '{"special":[],"index":"reliquary","name":"Reliquary","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"holy-symbols","name":"Holy Symbols","url":"/api/2014/equipment-categories/holy-symbols"},"cost":{"quantity":5,"unit":"gp"},"weight":2,"desc":["A holy symbol is a representation of a god or pantheon. It might be an amulet depicting a symbol representing a deity, the same symbol carefully engraved or inlaid as an emblem on a shield, or a tiny box holding a fragment of a sacred relic.","Appendix B lists the symbols commonly associated with many gods in the multiverse. A cleric or paladin can use a holy symbol as a spellcasting focus. To use the symbol in this way, the caster must hold it in hand, wear it visibly, or bear it on a shield."],"url":"/api/2014/equipment/reliquary","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-ring-mail', 'equipment', 'Ring Mail', 'equipment-ring-mail', '{"desc":[],"special":[],"index":"ring-mail","name":"Ring Mail","equipment_category":{"index":"armor","name":"Armor","url":"/api/2014/equipment-categories/armor"},"armor_category":"Heavy","armor_class":{"base":14,"dex_bonus":false},"str_minimum":0,"stealth_disadvantage":true,"weight":40,"cost":{"quantity":30,"unit":"gp"},"url":"/api/2014/equipment/ring-mail","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
