INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-rod', 'equipment', 'Rod', 'equipment-rod', '{"special":[],"index":"rod","name":"Rod","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"arcane-foci","name":"Arcane Foci","url":"/api/2014/equipment-categories/arcane-foci"},"cost":{"quantity":10,"unit":"gp"},"weight":2,"desc":["An arcane focus is a special item--an orb, a crystal, a rod, a specially constructed staff, a wand-like length of wood, or some similar item--designed to channel the power of arcane spells. A sorcerer, warlock, or wizard can use such an item as a spellcasting focus."],"url":"/api/2014/equipment/rod","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-rope-hempen-50-feet', 'equipment', 'Rope, hempen (50 feet)', 'equipment-rope-hempen-50-feet', '{"special":[],"index":"rope-hempen-50-feet","name":"Rope, hempen (50 feet)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":1,"unit":"gp"},"weight":10,"desc":["Rope, whether made of hemp or silk, has 2 hit points and can be burst with a DC 17 Strength check."],"url":"/api/2014/equipment/rope-hempen-50-feet","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-rope-silk-50-feet', 'equipment', 'Rope, silk (50 feet)', 'equipment-rope-silk-50-feet', '{"special":[],"index":"rope-silk-50-feet","name":"Rope, silk (50 feet)","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":10,"unit":"gp"},"weight":5,"desc":["Rope, whether made of hemp or silk, has 2 hit points and can be burst with a DC 17 Strength check."],"url":"/api/2014/equipment/rope-silk-50-feet","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-rowboat', 'equipment', 'Rowboat', 'equipment-rowboat', '{"special":[],"index":"rowboat","name":"Rowboat","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Waterborne Vehicles","cost":{"quantity":50,"unit":"gp"},"speed":{"quantity":1.5,"unit":"mph"},"desc":["Keelboats and rowboats are used on lakes and rivers. If going downstream, add the speed of the current (typically 3 miles per hour) to the speed of the vehicle. These vehicles can''t be rowed against any significant current, but they can be pulled upstream by draft animals on the shores. A rowboat weighs 100 pounds, in case adventurers carry it over land."],"url":"/api/2014/equipment/rowboat","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
