INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-saddle-military', 'equipment', 'Saddle, Military', 'equipment-saddle-military', '{"special":[],"index":"saddle-military","name":"Saddle, Military","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Tack, Harness, and Drawn Vehicles","cost":{"quantity":20,"unit":"gp"},"weight":30,"desc":["A military saddle braces the rider, helping you keep your seat on an active mount in battle. It gives you advantage on any check you make to remain mounted."],"url":"/api/2014/equipment/saddle-military","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
