INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-scale-merchants', 'equipment', 'Scale, merchant''s', 'equipment-scale-merchants', '{"special":[],"index":"scale-merchants","name":"Scale, merchant''s","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":5,"unit":"gp"},"weight":3,"desc":["A scale includes a small balance, pans, and a suitable assortment of weights up to 2 pounds. With it, you can measure the exact weight of small objects, such as raw precious metals or trade goods, to help determine their worth."],"url":"/api/2014/equipment/scale-merchants","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
