INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-sprig-of-mistletoe', 'equipment', 'Sprig of mistletoe', 'equipment-sprig-of-mistletoe', '{"special":[],"index":"sprig-of-mistletoe","name":"Sprig of mistletoe","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"druidic-foci","name":"Druidic Foci","url":"/api/2014/equipment-categories/druidic-foci"},"cost":{"quantity":1,"unit":"gp"},"weight":0,"desc":["A druidic focus might be a sprig of mistletoe or holly, a wand or scepter made of yew or another special wood, a staff drawn whole out of a living tree, or a totem object incorporating feathers, fur, bones, and teeth from sacred animals. A druid can use such an object as a spellcasting focus."],"url":"/api/2014/equipment/sprig-of-mistletoe","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
