INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-tent-two-person', 'equipment', 'Tent, two-person', 'equipment-tent-two-person', '{"special":[],"index":"tent-two-person","name":"Tent, two-person","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":2,"unit":"gp"},"weight":20,"desc":["A simple and portable canvas shelter, a tent sleeps two."],"url":"/api/2014/equipment/tent-two-person","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-thieves-tools', 'equipment', 'Thieves'' Tools', 'equipment-thieves-tools', '{"special":[],"index":"thieves-tools","name":"Thieves'' Tools","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Other Tools","cost":{"quantity":25,"unit":"gp"},"weight":1,"desc":["This set of tools includes a small file, a set of lock picks, a small mirror mounted on a metal handle, a set of narrow-bladed scissors, and a pair of pliers. Proficiency with these tools lets you add your proficiency bonus to any ability checks you make to disarm traps or open locks."],"url":"/api/2014/equipment/thieves-tools","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-tinderbox', 'equipment', 'Tinderbox', 'equipment-tinderbox', '{"special":[],"index":"tinderbox","name":"Tinderbox","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":5,"unit":"sp"},"weight":1,"desc":["This small container holds flint, fire steel, and tinder (usually dry cloth soaked in light oil) used to kindle a fire. Using it to light a torch--or anything else with abundant, exposed fuel--takes an action.","Lighting any other fire takes 1 minute."],"url":"/api/2014/equipment/tinderbox","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-tinkers-tools', 'equipment', 'Tinker''s Tools', 'equipment-tinkers-tools', '{"special":[],"index":"tinkers-tools","name":"Tinker''s Tools","equipment_category":{"index":"tools","name":"Tools","url":"/api/2014/equipment-categories/tools"},"tool_category":"Artisan''s Tools","cost":{"quantity":50,"unit":"gp"},"weight":10,"desc":["These special tools include the items needed to pursue a craft or trade. The table shows examples of the most common types of tools, each providing items related to a single craft. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft. Each type of artisan''s tools requires a separate proficiency."],"url":"/api/2014/equipment/tinkers-tools","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
INSERT INTO srd_entries (id, category, name, slug, data_json, source) VALUES ('equipment-torch', 'equipment', 'Torch', 'equipment-torch', '{"special":[],"index":"torch","name":"Torch","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":1,"unit":"cp"},"weight":1,"desc":["A torch burns for 1 hour, providing bright light in a 20-foot radius and dim light for an additional 20 feet. If you make a melee attack with a burning torch and hit, it deals 1 fire damage."],"url":"/api/2014/equipment/torch","updated_at":"2026-04-01T20:35:37.141Z","contents":[],"properties":[]}', 'SRD 5.1');
